window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s84-25","number":25,"surah":84,"verses":[14,15],"references":[{"surah":84,"verses":[14,15]}],"verseLabel":"الانشقاق: 14–15","question":"لماذا خُتم الرد بقوله ﴿إِنَّ رَبَّهُ كَانَ بِهِ بَصِيرًا﴾؟","answer":"لأن علم الله المحيط بأحواله وأعماله يمنع ضياعها أو الإفلات من جزائها؛ وفي ﴿بصيرًا﴾ مبالغة في الإحاطة بالمعلن والمستور.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص613، تحت عنوان «نكتة المبالغة في الوصف ﴿بصيرًا﴾»","url":""}]},{"id":"s84-9","number":9,"surah":84,"verses":[16,17,18],"references":[{"surah":84,"verses":[16,17,18]}],"verseLabel":"الانشقاق: 16–18","question":"ماذا يجمع الليل في قوله ﴿وَاللَّيْلِ وَمَا وَسَقَ﴾؟","answer":"يجمع ما انتشر في النهار من الناس والدواب فيردهم إلى مساكنهم، ويضم ما يظهر فيه من الكواكب؛ فالقسم بمشهد الاحتواء والسكون.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص621، تحت عنوان «دلالة التعبير بالفعل ﴿وسق﴾ مادة وصيغة»","url":""}]},{"id":"s84-26","number":26,"surah":84,"verses":[16,17,18],"references":[{"surah":84,"verses":[16,17,18]}],"verseLabel":"الانشقاق: 16–18","question":"ما المشهد في قوله ﴿وَالْقَمَرِ إِذَا اتَّسَقَ﴾؟","answer":"هو اكتمال القمر واجتماع نوره حتى يصير بدرًا، فيقسم بلحظة بلوغ النور تمامه بعد تدرجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص622، تحت عنوان «دلالة التعبير بالفعل ﴿اتسق﴾ مادة وصيغة»","url":""}]},{"id":"s84-10","number":10,"surah":84,"verses":[19],"references":[{"surah":84,"verses":[19]}],"verseLabel":"الانشقاق: 19","question":"ما الصورة في قوله ﴿لَتَرْكَبُنَّ طَبَقًا عَنْ طَبَقٍ﴾؟","answer":"صور انتقال الإنسان بين أحواله بركوب طبقة بعد طبقة؛ من أطوار الحياة إلى الموت والبعث والحساب، فلا يستقر على حال.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص623، تحت عنوان «نكتة استعمال الفعل (لتركبن)»","url":""}]},{"id":"s84-27","number":27,"surah":84,"verses":[19],"references":[{"surah":84,"verses":[19]}],"verseLabel":"الانشقاق: 19","question":"ماذا يعني ﴿طَبَقًا عَنْ طَبَقٍ﴾؟","answer":"يعني حالًا بعد حال متوافقًا بعضه فوق بعض، فتتتابع أطوار الإنسان وشدائده في نظام محتوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص625، تحت عنوان «دلالة لفظ ﴿طبق﴾ في الآية»","url":""}]},{"id":"s84-11","number":11,"surah":84,"verses":[20,21],"references":[{"surah":84,"verses":[20,21]}],"verseLabel":"الانشقاق: 20–21","question":"لماذا سأل القرآن ﴿فَمَا لَهُمْ لَا يُؤْمِنُونَ﴾؟","answer":"للتعجيب والإنكار من إصرارهم بعد وضوح الآيات؛ فالكون كله منقاد لربه وهم وحدهم يختارون العناد.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص631، تحت عنوان «بلاغة الاستفهام بـ(ما)»","url":""}]},{"id":"s84-28","number":28,"surah":84,"verses":[20,21],"references":[{"surah":84,"verses":[20,21]}],"verseLabel":"الانشقاق: 20–21","question":"لماذا خُص السجود بالذكر في قوله ﴿وَإِذَا قُرِئَ عَلَيْهِمُ الْقُرْآنُ لَا يَسْجُدُونَ﴾؟","answer":"لأنه أظهر علامات الخضوع والاستجابة، فنفيه يكشف رفضهم الانقياد للقرآن، ويقابل سجود الكون وطاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص635، تحت عنوان «دلالة تخصيص السجود بالذكر في قوله ﴿لا يسجدون﴾»","url":""}]},{"id":"s84-12","number":12,"surah":84,"verses":[22,23],"references":[{"surah":84,"verses":[22,23]}],"verseLabel":"الانشقاق: 22–23","question":"ما الصورة في قوله ﴿وَاللَّهُ أَعْلَمُ بِمَا يُوعُونَ﴾؟","answer":"أصل الإيعاء جمع الشيء في وعاء، واستعير لما يجمعونه في صدورهم من التكذيب والعداوة؛ فكأن القلب وعاء لسرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص640–641، تحت عنوان «بلاغة المجاز في لفظ ﴿يوعون﴾»","url":""}]},{"id":"s84-29","number":29,"surah":84,"verses":[22,23],"references":[{"surah":84,"verses":[22,23]}],"verseLabel":"الانشقاق: 22–23","question":"ماذا تحمل جملة ﴿وَاللَّهُ أَعْلَمُ بِمَا يُوعُونَ﴾ من تهديد؟","answer":"تقرر أن الله محيط بما يخفونه كما يعلم ما يظهرون، وفيها وعيد بأن الأسرار المضمرة داخلة في الحساب والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص641، تحت عنوان «فائدة الجملة الخبرية ﴿والله أعلم بما يوعون﴾»","url":""}]},{"id":"s84-13","number":13,"surah":84,"verses":[24],"references":[{"surah":84,"verses":[24]}],"verseLabel":"الانشقاق: 24","question":"ما أثر ﴿فَبَشِّرْهُمْ بِعَذَابٍ أَلِيمٍ﴾؟","answer":"جاءت البشارة بالعذاب تهكمًا بالمكذبين؛ إذ وضع الخبر المؤلم موضع ما ينتظر منه السرور. فيضاعف الأسلوب أثر الوعيد ويجعل الإعلان بالعذاب مقابلة لموقفهم من الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص641–642، تحت عنوان «دلالة التعبير بالفعل: ﴿فبشرهم﴾»","url":""}]},{"id":"s84-14","number":14,"surah":84,"verses":[25],"references":[{"surah":84,"verses":[25]}],"verseLabel":"الانشقاق: 25","question":"لماذا جاء ﴿لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ﴾ في الانشقاق بلا فاء؟","answer":"لأن الاستثناء حُمِل على الانقطاع بمعنى «لكن»، فجاءت الجملة استئنافًا يفتح شأن المؤمنين وثوابهم بعد وعيد المكذبين، لا جوابًا متفرعًا بالفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص646، تحت عنوان «علة فصل ﴿لهم أجر﴾»","url":""}]},{"id":"s84-30","number":30,"surah":84,"verses":[1],"references":[{"surah":84,"verses":[1]}],"verseLabel":"الانشقاق: 1","question":"ما سر تقديم الاسم على فعله بعد «إذا» في قوله: ﴿إِذَا السَّمَاءُ انشَقَّتْ﴾؟","answer":"التقديم هنا للتهويل، لأنه لم يحدث أن انشقت السماء قط، فالهول والفزع هنا أكبر. بخلاف ﴿إِذَا زُلْزِلَتِ الْأَرْضُ﴾ فلم يقدّم الاسم، لأن مشهد الزلازل واقع متكرر على الأعوام والأيام، وإن كانت تلك الزلزلة أعظمها.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج4، ص104.","url":""}]},{"id":"s85-1","number":1,"surah":85,"verses":[1,2,3],"references":[{"surah":85,"verses":[1,2,3]}],"verseLabel":"البروج: 1–3","question":"لماذا أقسم الله بالسماء ذات البروج؟","answer":"لما فيها من عظمة البناء ومنازل الأجرام وانتظامها، فهي آية ظاهرة على قدرة من يقسم بها على البعث والجزاء ونصرة المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص660، تحت عنوان «دلالة القسم بالسماء ووصفها»","url":""}]},{"id":"s85-15","number":15,"surah":85,"verses":[1,2,3],"references":[{"surah":85,"verses":[1,2,3]}],"verseLabel":"البروج: 1–3","question":"ما المناسبة بين السماء ذات البروج واليوم الموعود وشاهد ومشهود؟","answer":"تجمع بين مسرح القدرة في السماء وموعد الحساب ومن يحضر ذلك اليوم وما يشهده؛ فتنتقل من نظام الكون إلى اليوم الذي تنكشف فيه الحقائق وتؤدى الشهادات.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص662، تحت عنوان «مناسبة العطف بين الجمل»","url":""}]},{"id":"s85-16","number":16,"surah":85,"verses":[1,2,3],"references":[{"surah":85,"verses":[1,2,3]}],"verseLabel":"البروج: 1–3","question":"كيف يوسع ﴿شَاهِدٍ وَمَشْهُودٍ﴾ معنى الإحاطة الإلهية؟","answer":"يجمع كل من يشهد وكل ما تقع عليه الشهادة، فيشعر بأن الجريمة والجزاء داخل علم الله ومشهد خلقه، ولا يضيع منها خفي ولا ظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص666، تحت عنوان «بلاغة الكناية عن صفة الإحاطة الإلهية»","url":""}]},{"id":"s85-2","number":2,"surah":85,"verses":[3],"references":[{"surah":85,"verses":[3]}],"verseLabel":"البروج: 3","question":"لماذا نُكّر ﴿شَاهِدٍ وَمَشْهُودٍ﴾؟","answer":"ليعم كل شاهد وكل مشهود يصح دخولهما في المعنى، ويترك اللفظ متسعًا لمشاهد القيامة وغيرها بدل حصره في فرد واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص663–664، تحت عنوان «غرض تنكير ﴿وشاهد ومشهود﴾»","url":""}]},{"id":"s85-17","number":17,"surah":85,"verses":[3],"references":[{"surah":85,"verses":[3]}],"verseLabel":"البروج: 3","question":"لماذا جاء ﴿شَاهِدٍ﴾ مفردًا مع كثرة الشهود؟","answer":"لأن المفرد المنكر يراد به الجنس، فيشمل كل شاهد من غير حاجة إلى الجمع، ويجعل كل فرد قائمًا بنفسه في مقام الشهادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص666، تحت عنوان «نكتة إفراد لفظ (شاهد)»","url":""}]},{"id":"s85-3","number":3,"surah":85,"verses":[4],"references":[{"surah":85,"verses":[4]}],"verseLabel":"البروج: 4","question":"كيف تعمل جملة ﴿قُتِلَ أَصْحَابُ الْأُخْدُودِ﴾ جوابًا للقسم؟","answer":"تأتي دعاءً عليهم بالهلاك وخبرًا عن استحقاقهم له في آن، فتجعل القسم تمهيدًا لحكم إلهي جازم على الجناة وتشد الانتباه إلى قصتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص667–668، تحت عنوان «بلاغة جواب القسم المقدر بين الإنشاء والخبر»","url":""}]},{"id":"s85-18","number":18,"surah":85,"verses":[4],"references":[{"surah":85,"verses":[4]}],"verseLabel":"البروج: 4","question":"لماذا افتتحت قصة أصحاب الأخدود بكلمة ﴿قُتِلَ﴾؟","answer":"للدعاء عليهم بالهلاك وإظهار شدة السخط قبل تفصيل الجريمة، فكأن الحكم صدر عليهم من أول كلمة، ثم يأتي الخبر مفسرًا لاستحقاقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص668–669، تحت عنوان «بلاغة التعبير بمفردة ﴿قتل﴾»","url":""}]},{"id":"s85-4","number":4,"surah":85,"verses":[5],"references":[{"surah":85,"verses":[5]}],"verseLabel":"البروج: 5","question":"لماذا وُصفت نار الأخدود بأنها ﴿ذَاتِ الْوَقُودِ﴾؟","answer":"لتصوير نار ملازمة للوقود كثيرة المادة، أعدها الجناة لتبقى مشتعلة وتشتد، لا نارًا عارضة خمدت سريعًا. والوصف يكشف تعمدهم إحكام أداة التعذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص671–672، تحت عنوان «بلاغة الوصف بـ﴿ذات الوقود﴾»","url":""}]},{"id":"s85-5","number":5,"surah":85,"verses":[6,7],"references":[{"surah":85,"verses":[6,7]}],"verseLabel":"البروج: 6–7","question":"ماذا تكشف كلمة ﴿قُعُودٌ﴾ عن أصحاب الأخدود؟","answer":"تكشف أنهم استقروا مطمئنين حول النار زمنًا، لا مارين بالمشهد مصادفة؛ فالقعود يصور برودهم وإصرارهم وهم يتابعون التعذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص674–675، تحت عنوان «بلاغة مفردة ﴿قعود﴾ مادة وصيغة»","url":""}]},{"id":"s85-19","number":19,"surah":85,"verses":[6,7],"references":[{"surah":85,"verses":[6,7]}],"verseLabel":"البروج: 6–7","question":"ماذا يضيف وصفهم بأنهم ﴿شُهُودٌ﴾ على ما يفعلون؟","answer":"يجعلهم حاضرين مراقبين للجريمة بإرادتهم، يشهد بعضهم لبعض تنفيذها، فلا يبقى مجال لادعاء الجهل أو الغياب عن الفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص678، تحت عنوان «دلالة التعبير بمفردة ﴿شهود﴾»","url":""}]},{"id":"s85-6","number":6,"surah":85,"verses":[8],"references":[{"surah":85,"verses":[8]}],"verseLabel":"البروج: 8","question":"ما المفارقة في أن نقمة الجناة على المؤمنين كانت بسبب إيمانهم؟","answer":"لم يجدوا فيهم عيبًا إلا الإيمان بالله، وهو أجل صفاتهم؛ فتحولت صيغة الاتهام إلى مدح للمؤمنين وفضيحة للجناة الذين عاقبوا الفضيلة نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص681، تحت عنوان «بديع فن المدح بما يشبه الذم»","url":""}]},{"id":"s85-20","number":20,"surah":85,"verses":[8],"references":[{"surah":85,"verses":[8]}],"verseLabel":"البروج: 8","question":"لماذا وُصف الله هنا بالعزيز الحميد مالك السماوات والأرض؟","answer":"العزيز قادر على الانتقام ممن فتن أولياءه، والحميد مستحق لمحبتهم وثباتهم، والمالك لا يخرج الجناة من سلطانه. فتجيب الصفات عن ضعف المظلوم الظاهر بقوة ربه وكماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص682، تحت عنوان «توجيه تخصيص أوصاف العزيز الحميد المالك بالذكر»","url":""}]},{"id":"s85-7","number":7,"surah":85,"verses":[9],"references":[{"surah":85,"verses":[9]}],"verseLabel":"البروج: 9","question":"ما مناسبة ﴿لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ﴾ لقصة مستضعفين؟","answer":"تقديم «له» يقصر ملك السماوات والأرض على الله، فيقرر أن الجميع تحت سلطانه وحكمه. وفي هذا وعيد للمعذبين وتثبيت للمؤمنين؛ فلا يمنع الظالمين ملكهم الظاهر من أخذه، ولا تخرج حقوق المظلومين عن حكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص683، تحت عنوان «غرض تقديم الجار والمجرور على المسند إليه»","url":""}]},{"id":"s85-8","number":8,"surah":85,"verses":[10],"references":[{"surah":85,"verses":[10]}],"verseLabel":"البروج: 10","question":"ماذا تفيد ﴿ثُمَّ﴾ في فتح التوبة لفتاني المؤمنين؟","answer":"تبرز بُعد ما بين جريمتهم وبين باب الرحمة المفتوح لهم؛ فعلى فظاعة التعذيب وطوله، لم يغلق الله طريق الرجوع إن صدقوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص692، تحت عنوان «دلالة استعمال حرف التراخي»","url":""}]},{"id":"s85-21","number":21,"surah":85,"verses":[10],"references":[{"surah":85,"verses":[10]}],"verseLabel":"البروج: 10","question":"لماذا عبّر عن رجوع الجناة بـ﴿التوبة﴾؟","answer":"لأنها رجوع صادق يقطع الجريمة ويصلح أثرها، لا مجرد ندم لفظي؛ وفي اختيارها إعلان أن الإسلام والتصحيح يمحوان ما قبلهما إذا تحققت شروطهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص693، تحت عنوان «بلاغة استعمال مفردة التوبة»","url":""}]},{"id":"s85-22","number":22,"surah":85,"verses":[10],"references":[{"surah":85,"verses":[10]}],"verseLabel":"البروج: 10","question":"ماذا يكشف قوله ﴿ثُمَّ لَمْ يَتُوبُوا﴾ عن استحقاقهم العذاب؟","answer":"يكشف أنهم لم يعاقبوا على زلة عابرة فقط، بل على الإصرار بعد أن ظل باب التوبة ممكنًا؛ فاجتمع الجرم مع رفض الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص693، تحت عنوان «دلالة التعبير بالمضارع المنفي»","url":""}]},{"id":"s85-9","number":9,"surah":85,"verses":[11],"references":[{"surah":85,"verses":[11]}],"verseLabel":"البروج: 11","question":"كيف تقابل جنات المؤمنين نار الفاتنين في سورة البروج؟","answer":"تقابل إحراق الجناة للمؤمنين بنعيم تجري مياهه من تحتهم، وتقابل ضيق الأخدود بسعة الجنات ودوامها؛ فيظهر عدل الجزاء وانقلاب الموازين.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص694–695، تحت عنوان «موقع جملة: ﴿إن الذين آمنوا وعملوا الصالحات﴾ في السياق»","url":""}]},{"id":"s85-23","number":23,"surah":85,"verses":[11],"references":[{"surah":85,"verses":[11]}],"verseLabel":"البروج: 11","question":"لماذا وُصف فوز المؤمنين بأنه ﴿الْفَوْزُ الْكَبِيرُ﴾؟","answer":"لأنه يجمع النجاة من عذاب الجناة ومن عذاب الآخرة مع الظفر بالجنة ورضوان الله؛ فلا يقاس بما فقدوه في الدنيا ولا بأي نجاح مؤقت.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص699، تحت عنوان «نكتة وصف ﴿الفوز﴾ بالكبير»","url":""}]},{"id":"s85-10","number":10,"surah":85,"verses":[12],"references":[{"surah":85,"verses":[12]}],"verseLabel":"البروج: 12","question":"ما الذي توحي به كلمة ﴿بَطْشَ﴾ ووصفه بالشدة؟","answer":"توحي بأخذ قوي حاسم لا يفلت منه الظالم، وتطمئن المظلوم أن إمهال الجناة لا يعني عجزًا؛ فإذا جاء الأخذ لم تدفعه قوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص704، تحت عنوان «دلالة مفردة ﴿بطش﴾»","url":""}]},{"id":"s85-24","number":24,"surah":85,"verses":[12],"references":[{"surah":85,"verses":[12]}],"verseLabel":"البروج: 12","question":"ماذا يضيف قوله للنبي ﴿بَطْشَ رَبِّكَ﴾؟","answer":"يضيف القرب والرعاية والنصرة؛ فالذي سيتولى الظالمين هو رب النبي ومربيه وحافظ دعوته، فيثبت قلبه ويهدد مكذبيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص705، تحت عنوان «دلالة إضافة لفظ الربوبية إلى ضمير النبي ﷺ»","url":""}]},{"id":"s85-11","number":11,"surah":85,"verses":[13,14,15,16],"references":[{"surah":85,"verses":[13,14,15,16]}],"verseLabel":"البروج: 13–16","question":"لماذا جمع بين أن الله ﴿يُبْدِئُ وَيُعِيدُ﴾؟","answer":"ليقرر إحاطة قدرته بالإنشاء الأول والبعث والجزاء؛ فمن بدأ الخلق لا تعجزه إعادته، ومن يعيد قادر على رد الحقوق والانتقام للمظلومين.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص707، تحت عنوان «بلاغة فن الطباق»","url":""}]},{"id":"s85-25","number":25,"surah":85,"verses":[13,14,15,16],"references":[{"surah":85,"verses":[13,14,15,16]}],"verseLabel":"البروج: 13–16","question":"لماذا ذُكرت صفة ﴿الْغَفُورُ﴾ بعد وعيد أصحاب الأخدود؟","answer":"لأن السياق فتح التوبة حتى للفتانين، فجاءت الصفة تثبت أن الوعيد لا يغلق الرحمة أمام من رجع، وتمنع اليأس مع بقاء العدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص708، تحت عنوان «نكتة اختيار صفة ﴿الغفور﴾ وتناسبها مع السياق»","url":""}]},{"id":"s85-26","number":26,"surah":85,"verses":[13,14,15,16],"references":[{"surah":85,"verses":[13,14,15,16]}],"verseLabel":"البروج: 13–16","question":"ماذا يضيف اقتران ﴿الْغَفُورُ﴾ بـ﴿الْوَدُودُ﴾؟","answer":"يبين أن التائب لا ينال محو الذنب فحسب، بل يعود إلى محبة الله وقربه؛ فالمغفرة ترفع أثر الماضي والود يمنح علاقة جديدة كريمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص709، تحت عنوان «نكتة قرن صفة ﴿الغفور﴾ بصفة ﴿الودود﴾»","url":""}]},{"id":"s85-27","number":27,"surah":85,"verses":[13,14,15,16],"references":[{"surah":85,"verses":[13,14,15,16]}],"verseLabel":"البروج: 13–16","question":"لماذا خُص العرش بالذكر في ﴿ذُو الْعَرْشِ الْمَجِيدُ﴾؟","answer":"لأنه أعظم المخلوقات ورمز الملك والسلطان، فذكره يدل على جلال مالكه وسعة قدرته وتدبيره للكون كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص709، تحت عنوان «توجيه تخصيص ﴿العرش﴾ بالذكر»","url":""}]},{"id":"s85-28","number":28,"surah":85,"verses":[13,14,15,16],"references":[{"surah":85,"verses":[13,14,15,16]}],"verseLabel":"البروج: 13–16","question":"ماذا يحسم ختام الصفات بـ﴿فَعَّالٌ لِمَا يُرِيدُ﴾؟","answer":"يحسم أن إرادة الله نافذة لا يعوقها أحد، فيقدر على الإعادة والمغفرة والنصرة والبطش كما يشاء. وصيغة المبالغة تفيد دوام الفعل وكمال القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص710–711، تحت عنوان «بلاغة التذييل بصيغة المبالغة»","url":""}]},{"id":"s85-12","number":12,"surah":85,"verses":[17,18],"references":[{"surah":85,"verses":[17,18]}],"verseLabel":"البروج: 17–18","question":"لماذا سُئل النبي ﴿هَلْ أَتَاكَ حَدِيثُ الْجُنُودِ﴾؟","answer":"للتشويق إلى خبر معروف العاقبة، وتثبيت النبي بأن جند المكذبين مهما ظهر سلطانهم انتهوا إلى الهزيمة. والسؤال يفتح شاهدًا تاريخيًا على سنّة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص714، تحت عنوان «غرض الاستفهام وبلاغته»","url":""}]},{"id":"s85-29","number":29,"surah":85,"verses":[17,18],"references":[{"surah":85,"verses":[17,18]}],"verseLabel":"البروج: 17–18","question":"لماذا خُص فرعون وثمود من بين جنود المكذبين؟","answer":"لأنهما نموذجان بارزان لقوة منظمة وبطش شديد انتهيا إلى الهلاك؛ فذكرهما المختصر يغني عن تفصيل القصة ويشبه حال مكذبي الرسالة بعاقبتهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص715، تحت عنوان «توجيه تخصيص ﴿فرعون وثمود﴾ بالذكر»","url":""}]},{"id":"s85-13","number":13,"surah":85,"verses":[19,20],"references":[{"surah":85,"verses":[19,20]}],"verseLabel":"البروج: 19–20","question":"ما الصورة التي ترسمها ﴿وَاللَّهُ مِنْ وَرَائِهِمْ مُحِيطٌ﴾؟","answer":"ترسم المكذبين داخل قبضة لا منفذ منها، كمن أحاط به ما وراءه وسائر جهاته؛ فلا يغيبون عن علم الله ولا يفلتون من قدرته وإن ظنوا أنهم يحاصرون المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص719–720، تحت عنوان «بلاغة الاستعارة في مفردة ﴿محيط﴾»","url":""}]},{"id":"s85-14","number":14,"surah":85,"verses":[21,22],"references":[{"surah":85,"verses":[21,22]}],"verseLabel":"البروج: 21–22","question":"ماذا يحقق الانتقال بـ﴿بَلْ هُوَ قُرْآنٌ مَجِيدٌ﴾؟","answer":"يترك جدل المكذبين ليقرر الحقيقة التي لا يغيرها تكذيبهم: القرآن رفيع الشأن ثابت المصدر، وهم المحاصرون بالباطل لا هو.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص722، تحت عنوان «نوع الإضراب ودلالته»","url":""}]},{"id":"s85-30","number":30,"surah":85,"verses":[21,22],"references":[{"surah":85,"verses":[21,22]}],"verseLabel":"البروج: 21–22","question":"لماذا وُصف القرآن بأنه ﴿مَجِيدٌ﴾؟","answer":"لشرف معانيه وعلو مصدره وكثرة خيره وآثاره؛ فهو عظيم في ذاته وهدايته، لا تنقص منزلته معارضة المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص722، تحت عنوان «نكتة وصف القرآن بصفة المجيد»","url":""}]},{"id":"s85-31","number":31,"surah":85,"verses":[21,22],"references":[{"surah":85,"verses":[21,22]}],"verseLabel":"البروج: 21–22","question":"ماذا يضيف ختام القرآن بأنه ﴿فِي لَوْحٍ مَحْفُوظٍ﴾؟","answer":"يؤكد أن أصله مصون من التبديل والعبث وأن تكذيب البشر لا يمس حقيقته؛ فالحفظ يطمئن إلى ثبات الوحي كما نزل.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص723، تحت عنوان «نكتة وصف محل القرآن بالحفظ»","url":""}]},{"id":"s85-32","number":32,"surah":85,"verses":[10,11],"references":[{"surah":85,"verses":[10,11]}],"verseLabel":"البروج: 10–11","question":"ما سر الفاء في ﴿فَلَهُمْ عَذَابُ جَهَنَّمَ﴾، وتركها في ﴿لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ﴾؟","answer":"المقام يقتضي توكيد الأولى، لأنها جاءت تعقيبًا على الذين فتنوا المؤمنين عن دينهم وجعلوهم في الأخاديد، فأكد لهم العذاب بسبب فتنتهم. ويحتمل أن يكون حذفها من أصحاب الجنة إشارة إلى أن دخولها ليس بالعمل وحده بل برحمة الله، أما أعمال أهل النار فهي سبب دخولهم إياها.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج4، ص129–130.","url":""}]},{"id":"s85-33","number":33,"surah":85,"verses":[19,20],"references":[{"surah":85,"verses":[19,20]}],"verseLabel":"البروج: 19–20","question":"ما سر قوله: ﴿بَلِ الَّذِينَ كَفَرُوا فِي تَكْذِيبٍ﴾، وفي النبأ: ﴿وَكَذَّبُوا بِآيَاتِنَا كِذَّابًا﴾؟","answer":"«الكِذّاب» قد يُستعمل للإفراط في التكذيب، فلما زاد في النبأ الوصف بالطغيان والتفصيل في الكفر جاء به مؤكدًا للفعل، ولم يقل هنا إلا «في تكذيب». والمعنى أنهم ساقطون في التكذيب وأنه محيط بهم، فناسب أن يقول بعده: ﴿وَاللَّهُ مِن وَرَائِهِم مُّحِيطٌ﴾، فالتكذيب محيط بهم والله محيط بالجميع. وفي «الكشاف» نحو هذا في معنى «الكذّاب».","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص112–113.","url":""}]},{"id":"s86-1","number":1,"surah":86,"verses":[1,2,3],"references":[{"surah":86,"verses":[1,2,3]}],"verseLabel":"الطارق: 1–3","question":"كيف يعظم سؤال ﴿وَمَا أَدْرَاكَ مَا الطَّارِقُ﴾ شأن الطارق؟","answer":"يوقف السامع عند أمر مجهول عظيم لا تدرك حقيقته إلا ببيان الله، فيتشوق إلى تفسيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص736، تحت عنوان «بلاغة الاستفهام في قوله: ﴿وما أدراك﴾»","url":""}]},{"id":"s86-13","number":13,"surah":86,"verses":[1,2,3],"references":[{"surah":86,"verses":[1,2,3]}],"verseLabel":"الطارق: 1–3","question":"لماذا فسر الطارق بـ﴿النَّجْمُ﴾ معرفًا؟","answer":"يجوز أن يستغرق جنس النجوم ذات الضوء النافذ، أو يعهد إلى نجم معروف؛ وفي الحالين يزيل البيان إبهام الطارق.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص738–739، تحت عنوان «نوع (أل) ودلالتها في ﴿النجم﴾»","url":""}]},{"id":"s86-2","number":2,"surah":86,"verses":[3],"references":[{"surah":86,"verses":[3]}],"verseLabel":"الطارق: 3","question":"كيف يصور وصف النجم بـ﴿الثَّاقِبُ﴾ ضوءه؟","answer":"استعار الثقب لنفاذ ضوء النجم في ظلمة الليل، فكأن شعاعه يخترق الظلام بقوة ووضوح.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص739–740، تحت عنوان «نوع الاستعارة وبلاغتها في ﴿الثاقب﴾»","url":""}]},{"id":"s86-3","number":3,"surah":86,"verses":[4],"references":[{"surah":86,"verses":[4]}],"verseLabel":"الطارق: 4","question":"لماذا جاء جواب القسم ﴿إِنْ كُلُّ نَفْسٍ لَمَّا عَلَيْهَا حَافِظٌ﴾ مؤكدًا؟","answer":"لتقرير أن أعمال كل نفس محفوظة ومحصاة، ورد إنكار الحساب والجزاء بتوكيد لا يدع مجالًا للشك.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص741، تحت عنوان «بلاغة التوكيد في جملة الجواب»","url":""}]},{"id":"s86-4","number":4,"surah":86,"verses":[5],"references":[{"surah":86,"verses":[5]}],"verseLabel":"الطارق: 5","question":"ما الغرض من أمر الإنسان أن ينظر ﴿مِمَّ خُلِقَ﴾؟","answer":"دعوتُه إلى التفكر في ضعفه الأول ليستدل بقدرة الخالق على إمكان بعثه ومحاسبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص747، تحت عنوان «الغرض من الأمر بالنظر»","url":""}]},{"id":"s86-14","number":14,"surah":86,"verses":[5],"references":[{"surah":86,"verses":[5]}],"verseLabel":"الطارق: 5","question":"لماذا اختير فعل ﴿فَلْيَنْظُرِ﴾ في التأمل في أصل الخلق؟","answer":"لأنه نظر عقلي يتجاوز المشاهدة إلى التدبر والفهم، فيحول المعلومة إلى حجة على البعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص748، تحت عنوان «دلالة التعبير بفعل النظر دون غيره»","url":""}]},{"id":"s86-5","number":5,"surah":86,"verses":[6],"references":[{"surah":86,"verses":[6]}],"verseLabel":"الطارق: 6","question":"ماذا يصور وصف الماء بـ﴿دَافِقٍ﴾؟","answer":"يصور اندفاعه بقوة وسرعة، فيبرز حيوية النطفة على ضعف مادتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص752، تحت عنوان «دلالة التعبير بـ﴿دافق﴾ مادة وصيغة»","url":""}]},{"id":"s86-15","number":15,"surah":86,"verses":[6],"references":[{"surah":86,"verses":[6]}],"verseLabel":"الطارق: 6","question":"كيف أسند الدفق إلى الماء نفسه في ﴿مَاءٍ دَافِقٍ﴾؟","answer":"أُسند الفعل إلى الماء مجازًا للمبالغة، كأنه يندفع بنفسه؛ فتقوى صورة الحركة.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص752، تحت عنوان «نوع المجاز وبلاغته في الوصف»","url":""}]},{"id":"s86-6","number":6,"surah":86,"verses":[7],"references":[{"surah":86,"verses":[7]}],"verseLabel":"الطارق: 7","question":"لماذا عبر عن منشأ الماء بقوله ﴿يَخْرُجُ﴾؟","answer":"ليصور انتقاله من موضعه الخفي إلى الظهور انتقالًا حقيقيًا منظمًا، شاهدًا على دقة الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص753، تحت عنوان «وجه التعبير بفعل الخروج»","url":""}]},{"id":"s86-16","number":16,"surah":86,"verses":[7],"references":[{"surah":86,"verses":[7]}],"verseLabel":"الطارق: 7","question":"كيف يجعل قوله ﴿يَخْرُجُ﴾ مشهد خلق الإنسان حاضرًا أمام السامع؟","answer":"يستحضر العملية كأنها متجددة حاضرة تتكرر في كل إنسان، فيقرب دليل القدرة إلى الحس.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص753–754، تحت عنوان «بلاغة التعبير عن الخروج بصيغة المضارع»","url":""}]},{"id":"s86-17","number":17,"surah":86,"verses":[7],"references":[{"surah":86,"verses":[7]}],"verseLabel":"الطارق: 7","question":"ما فائدة ﴿بَيْنِ﴾ في ﴿مِنْ بَيْنِ الصُّلْبِ وَالتَّرَائِبِ﴾؟","answer":"تحدد منشأ دقيقًا محاطًا بهذين الموضعين، فتبرز إحاطة علم الله وقدرته بأصل الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص754، تحت عنوان «فائدة التعبير بالظرف ﴿بين﴾»","url":""}]},{"id":"s86-7","number":7,"surah":86,"verses":[8],"references":[{"surah":86,"verses":[8]}],"verseLabel":"الطارق: 8","question":"لماذا جاءت ﴿إِنَّهُ عَلَى رَجْعِهِ لَقَادِرٌ﴾ مفصولة عما قبلها؟","answer":"لأنها نتيجة مستقلة للدليل السابق: من قدر على الخلق الأول قادر على الإعادة، فاستحقت الوقوف عندها.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص758، تحت عنوان «سر فصل الآية عما قبلها»","url":""}]},{"id":"s86-18","number":18,"surah":86,"verses":[8],"references":[{"surah":86,"verses":[8]}],"verseLabel":"الطارق: 8","question":"لماذا عُبر عن البعث بـ﴿رَجْعِهِ﴾؟","answer":"لأنه إعادة للإنسان إلى الحياة بعد الموت وإرجاع له إلى حال الخلق الأولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص759، تحت عنوان «غرض التعبير عن البعث بالرجع»","url":""}]},{"id":"s86-19","number":19,"surah":86,"verses":[8],"references":[{"surah":86,"verses":[8]}],"verseLabel":"الطارق: 8","question":"ما أثر تتابع المؤكدات في ﴿إِنَّهُ عَلَى رَجْعِهِ لَقَادِرٌ﴾؟","answer":"يواجه إنكار البعث بإن واللام والجملة الاسمية، فيثبت القدرة عليه ثبوتًا لا يتزلزل.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص759، تحت عنوان «سر تتابع المؤكدات في الآية»","url":""}]},{"id":"s86-8","number":8,"surah":86,"verses":[9,10],"references":[{"surah":86,"verses":[9,10]}],"verseLabel":"الطارق: 9–10","question":"ماذا يصور قوله ﴿يَوْمَ تُبْلَى السَّرَائِرُ﴾؟","answer":"يصوّر اختبار خفايا النفوس وكشفها حتى تظهر النيات والعقائد والأعمال المستورة ويجازى أصحابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص760–761، تحت عنوان «وجه التعبير بالفعل: ﴿تبلى﴾»","url":""}]},{"id":"s86-9","number":9,"surah":86,"verses":[10],"references":[{"surah":86,"verses":[10]}],"verseLabel":"الطارق: 10","question":"لماذا جمع ﴿فَمَا لَهُ مِنْ قُوَّةٍ وَلَا نَاصِرٍ﴾؟","answer":"لينفي طريقَي دفع العذاب: قدرة الإنسان من نفسه، واستعانته بقوة من خارجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص763، تحت عنوان «وجه العطف بالواو»","url":""}]},{"id":"s86-20","number":20,"surah":86,"verses":[10],"references":[{"surah":86,"verses":[10]}],"verseLabel":"الطارق: 10","question":"ماذا يفيد تنكير ﴿نَاصِرٍ﴾ في سياق النفي؟","answer":"يعم كل ناصر محتمل، فلا يجد الإنسان أحدًا يخلصه من الجزاء بعد كشف سرائره.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص764، تحت عنوان «دلالة التعبير بـ﴿ناصر﴾ اسم فاعل نكرة»","url":""}]},{"id":"s86-10","number":10,"surah":86,"verses":[11,12],"references":[{"surah":86,"verses":[11,12]}],"verseLabel":"الطارق: 11–12","question":"لماذا وصفت السماء بأنها ﴿ذَاتِ الرَّجْعِ﴾؟","answer":"لأنها تعيد المطر مرة بعد مرة، وفي رجعها صورة تمهد لإمكان رجع الإنسان بعد موته.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص769، تحت عنوان «دلالة التعبير بـ﴿الرجع﴾، ووجه مناسبته للمقسم عليه»","url":""}]},{"id":"s86-21","number":21,"surah":86,"verses":[11,12],"references":[{"surah":86,"verses":[11,12]}],"verseLabel":"الطارق: 11–12","question":"ماذا يصور وصف الأرض بأنها ﴿ذَاتِ الصَّدْعِ﴾؟","answer":"يصور انشقاقها عن النبات والحياة بعد كمونها، شاهدًا محسوسًا على قدرة الإحياء.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص771، تحت عنوان «معنى ﴿الصدع﴾، وبلاغة التعبير به»","url":""}]},{"id":"s86-22","number":22,"surah":86,"verses":[11,12],"references":[{"surah":86,"verses":[11,12]}],"verseLabel":"الطارق: 11–12","question":"كيف يناسب صدع الأرض الحديث عن بعث الإنسان؟","answer":"كما تنشق الأرض عن النبات بعد مواته، تنشق عن الناس عند البعث؛ فالمشهد الكوني يقرب حقيقة الإعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص771–772، تحت عنوان «وجه المناسبة بين الأرض وصدعها وبعث الإنسان»","url":""}]},{"id":"s86-11","number":11,"surah":86,"verses":[13,14],"references":[{"surah":86,"verses":[13,14]}],"verseLabel":"الطارق: 13–14","question":"لماذا وصف القرآن بأنه ﴿قَوْلٌ فَصْلٌ﴾؟","answer":"لأنه يفصل بين الحق والباطل بحكم حاسم لا التباس فيه ولا نقص.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص773، تحت عنوان «سر وصف القول بـ﴿فصل﴾»","url":""}]},{"id":"s86-23","number":23,"surah":86,"verses":[13,14],"references":[{"surah":86,"verses":[13,14]}],"verseLabel":"الطارق: 13–14","question":"ماذا يقرر نفي الهزل عن القرآن؟","answer":"يقرر أنه جد خالص في أخباره وأحكامه ووعده ووعيده، وليس فيه شيء من العبث.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص774–775، تحت عنوان «دلالة تعريف (الهزل)، وفائدة نفيه»","url":""}]},{"id":"s86-12","number":12,"surah":86,"verses":[15,16,17],"references":[{"surah":86,"verses":[15,16,17]}],"verseLabel":"الطارق: 15–17","question":"كيف يصور قوله ﴿إِنَّهُمْ يَكِيدُونَ كَيْدًا﴾ استمرار تدبير المكذبين؟","answer":"يصور مكرهم المتجدد المستمر لإبطال الدعوة وإيذاء الرسول، مع تنوع وسائلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص780، تحت عنوان «سر التعبير بالفعل: ﴿يكيدون﴾ مادة وصيغة»","url":""}]},{"id":"s86-24","number":24,"surah":86,"verses":[15,16,17],"references":[{"surah":86,"verses":[15,16,17]}],"verseLabel":"الطارق: 15–17","question":"ماذا يقرر قوله ﴿وَأَكِيدُ كَيْدًا﴾ في مواجهة تدبير المكذبين؟","answer":"يقرر تدبير الله المحكم الذي يحيط بمكرهم ويبطل أثره، وحمايته المستمرة لرسوله ودعوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص781، تحت عنوان «معنى ﴿وأكيد﴾، ودلالة التعبير به مضارعًا»","url":""}]},{"id":"s86-25","number":25,"surah":86,"verses":[15,16,17],"references":[{"surah":86,"verses":[15,16,17]}],"verseLabel":"الطارق: 15–17","question":"ما أثر مقابلة كيدهم بكيد الله باللفظ نفسه؟","answer":"تحمل مشاكلة تهكمية: كيدهم حيلة ضعيفة، وتدبير الله حق غالب يرد مكرهم عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص782، تحت عنوان «بلاغة التناسب في لفظ الكيد»","url":""}]},{"id":"s86-26","number":26,"surah":86,"verses":[15,16,17],"references":[{"surah":86,"verses":[15,16,17]}],"verseLabel":"الطارق: 15–17","question":"لماذا أمر الله بإمهال الكافرين ﴿أَمْهِلْهُمْ رُوَيْدًا﴾؟","answer":"لتهديدهم بأن العذاب قريب لا يحتاج استعجالًا، وتطمين الرسول بأن مكرهم لن يطول.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص783–784، تحت عنوان «غرض الأمر بالإمهال، ولطيفة تضعيف عينه»","url":""}]},{"id":"s87-1","number":1,"surah":87,"verses":[1],"references":[{"surah":87,"verses":[1]}],"verseLabel":"الأعلى: 1","question":"لماذا عُدي التسبيح إلى ﴿اسْمَ رَبِّكَ﴾؟","answer":"لأن تنزيه اسم الله يستلزم تنزيه ذاته وصفاته وأفعاله، ويصون اسمه عن كل استعمال لا يليق.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص796–797، تحت عنوان «وجه تعدية فعل التسبيح إلى الاسم»","url":""}]},{"id":"s87-2","number":2,"surah":87,"verses":[1],"references":[{"surah":87,"verses":[1]}],"verseLabel":"الأعلى: 1","question":"لماذا ناسب وصف الرب بـ﴿الْأَعْلَى﴾ مطلع سورة التسبيح؟","answer":"لأن التنزيه مقام إثبات العلو المطلق لله فوق كل نقص ومماثلة، ثم تذكر السورة آثار قدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص798–799، تحت عنوان «بلاغة الوصف بـ﴿الأعلى﴾ وغيره من الصفات المذكورة»","url":""}]},{"id":"s87-14","number":14,"surah":87,"verses":[1],"references":[{"surah":87,"verses":[1]}],"verseLabel":"الأعلى: 1","question":"ماذا تضيف صيغة التفضيل في ﴿الْأَعْلَى﴾؟","answer":"تقرر أن علو الله مطلق فوق كل علو، فلا يلحقه أحد في ذاته وصفاته وسلطانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص799–800، تحت عنوان «دلالة صوغ ﴿الأعلى﴾ اسم تفضيل»","url":""}]},{"id":"s87-3","number":3,"surah":87,"verses":[2,3],"references":[{"surah":87,"verses":[2,3]}],"verseLabel":"الأعلى: 2–3","question":"ماذا يقرر فعل ﴿خَلَقَ﴾ في مطلع السورة؟","answer":"يستحضر الإيجاد من العدم بوصفه أصل دلائل القدرة، ويمهد لما بعده من إحكام الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص800، تحت عنوان «دلالة التعبير بفعل الخلق مادة وصيغة»","url":""}]},{"id":"s87-15","number":15,"surah":87,"verses":[2,3],"references":[{"surah":87,"verses":[2,3]}],"verseLabel":"الأعلى: 2–3","question":"ماذا تفيد ﴿فَسَوَّى﴾ بعد الخلق؟","answer":"تفيد أن الله أعطى كل مخلوق صورته المتوازنة وأكمل أعضاءه ووظائفه بلا تفاوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص801–802، تحت عنوان «سر التعبير بفعل التسوية»","url":""}]},{"id":"s87-16","number":16,"surah":87,"verses":[2,3],"references":[{"surah":87,"verses":[2,3]}],"verseLabel":"الأعلى: 2–3","question":"ماذا يقرر قوله ﴿قَدَّرَ فَهَدَى﴾؟","answer":"يقرر أن الله حدد لكل مخلوق خصائصه وأجله ورزقه، ثم هداه إلى ما يصلحه ويؤدي وظيفته.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص803–804، تحت عنوان «دلالة التعبير بفعل التقدير مادة وصيغة»","url":""}]},{"id":"s87-4","number":4,"surah":87,"verses":[4,5],"references":[{"surah":87,"verses":[4,5]}],"verseLabel":"الأعلى: 4–5","question":"كيف ينقلب المرعى النضر في لحظة إلى ﴿غُثَاءً أَحْوَى﴾؟","answer":"تصور سرعة انتقال النبات من الخضرة إلى اليبس والسواد، تذكيرًا بسرعة زوال الحياة الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص807، تحت عنوان «معنى (الفاء) في قوله: ﴿فجعله غثاء أحوى﴾»","url":""}]},{"id":"s87-17","number":17,"surah":87,"verses":[4,5],"references":[{"surah":87,"verses":[4,5]}],"verseLabel":"الأعلى: 4–5","question":"ما الصورة في ﴿غُثَاءً أَحْوَى﴾؟","answer":"تصور المرعى بعد نضارته حطامًا يابسًا مائلًا إلى السواد، فيجتمع الذبول والقتامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص808، تحت عنوان «موقع ﴿أحوى﴾ ودلالته»","url":""}]},{"id":"s87-5","number":5,"surah":87,"verses":[6,7],"references":[{"surah":87,"verses":[6,7]}],"verseLabel":"الأعلى: 6–7","question":"ما صلة إقراء النبي ﷺ بوعده في قوله ﴿فَلَا تَنْسَى﴾؟","answer":"تجعل عدم النسيان ثمرة مباشرة لإقراء الله، فتطمئن النبي إلى حفظ الوحي وصيانته.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص14، تحت عنوان «معنى الفاء في قوله: ﴿فلا تنسى﴾»","url":""}]},{"id":"s87-18","number":18,"surah":87,"verses":[6,7],"references":[{"surah":87,"verses":[6,7]}],"verseLabel":"الأعلى: 6–7","question":"كيف يفهم الاستثناء ﴿إِلَّا مَا شَاءَ اللَّهُ﴾ مع ضمان الحفظ؟","answer":"لا ينقض الوعد، بل يقرر أن الحفظ بمشيئة الله وقدرته لا باستقلال العبد، مع احتمال ما اقتضت الحكمة نسخه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص15، تحت عنوان «بلاغة الاستثناء بـ﴿إلا﴾»","url":""}]},{"id":"s87-6","number":6,"surah":87,"verses":[7],"references":[{"surah":87,"verses":[7]}],"verseLabel":"الأعلى: 7","question":"لماذا فصل قوله ﴿إِنَّهُ يَعْلَمُ الْجَهْرَ وَمَا يَخْفَى﴾ بعد وعد الحفظ؟","answer":"جاء تعليلًا مستقلًا للوعد: من أحاط علمه بالظاهر والخفي يعلم حاجة رسوله ويحفظ له الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص17، تحت عنوان «علة فصل قوله: ﴿إنه يعلم الجهر وما يخفى﴾»","url":""}]},{"id":"s87-19","number":19,"surah":87,"verses":[7],"references":[{"surah":87,"verses":[7]}],"verseLabel":"الأعلى: 7","question":"لماذا قدم ﴿الْجَهْرَ﴾ على ﴿مَا يَخْفَى﴾؟","answer":"بدأ بما يظهر للناس ثم ترقى إلى ما لا يحيط به إلا الله، لإثبات شمول علمه من الظاهر إلى أدق الخفايا.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص20، تحت عنوان «مناسبة التعبير بالجهر والإخفاء، ووجه ترتيبهما»","url":""}]},{"id":"s87-7","number":7,"surah":87,"verses":[8],"references":[{"surah":87,"verses":[8]}],"verseLabel":"الأعلى: 8","question":"ما دلالة قول الله لنبيه ﷺ ﴿وَنُيَسِّرُكَ﴾؟","answer":"لم يقل نيسر لك فحسب، بل يجعل ذات الرسول مهيأة للخير ومتمكنة من أداء الرسالة بيسر.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص25، تحت عنوان «براعة تعدية فعل التيسير إلى ضمير المخاطب»","url":""}]},{"id":"s87-20","number":20,"surah":87,"verses":[8],"references":[{"surah":87,"verses":[8]}],"verseLabel":"الأعلى: 8","question":"ماذا تشمل ﴿الْيُسْرَى﴾؟","answer":"تشمل الطريقة الأيسر والأكمل في حفظ الوحي وتبليغه والعمل به، وكل خير في الدنيا والآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص26، تحت عنوان «دلالة التعبير بـ (اليسرى) مادة وصيغة»","url":""}]},{"id":"s87-8","number":8,"surah":87,"verses":[9],"references":[{"surah":87,"verses":[9]}],"verseLabel":"الأعلى: 9","question":"من تشملهم الذكرى في الأمر المطلق ﴿فَذَكِّرْ﴾؟","answer":"ليعم التذكير جميع الناس وكل ما يحتاجون إليه من هداية ووعد ووعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص32، تحت عنوان «فائدة حذف مفعول الأمر بالتذكير»","url":""}]},{"id":"s87-21","number":21,"surah":87,"verses":[9],"references":[{"surah":87,"verses":[9]}],"verseLabel":"الأعلى: 9","question":"ما دلالة قيد ﴿إِنْ نَفَعَتِ الذِّكْرَى﴾؟","answer":"ليس لإيقاف الدعوة عند عدم الاستجابة، بل لحث المنتفع وتوبيخ المعرض، مع علم أن الذكرى تنفع من يخشى.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص32، تحت عنوان «موقع جملة: ﴿إن نفعت الذكرى﴾ ودلالتها»","url":""}]},{"id":"s87-9","number":9,"surah":87,"verses":[10,11],"references":[{"surah":87,"verses":[10,11]}],"verseLabel":"الأعلى: 10–11","question":"كيف يصور قوله ﴿سَيَذَّكَّرُ مَنْ يَخْشَى﴾ أثر الخشية المتجدد؟","answer":"يصوّر خشية حية متجددة تدفع صاحبها كل مرة إلى قبول الموعظة والعمل بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص34، تحت عنوان «سر التعبير بالمضارع: ﴿يخشى﴾ مادة وصيغة»","url":""}]},{"id":"s87-22","number":22,"surah":87,"verses":[10,11],"references":[{"surah":87,"verses":[10,11]}],"verseLabel":"الأعلى: 10–11","question":"كيف يصور قوله ﴿وَيَتَجَنَّبُهَا الْأَشْقَى﴾ إصرار الأشقى على الابتعاد عن الذكرى؟","answer":"يصور تعمده الابتعاد عن الذكرى ومبالغته في اتخاذ جانب بعيد عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص35، تحت عنوان «سر التعبير بالفعل (يتجنب) زمانًا وصيغة»","url":""}]},{"id":"s87-23","number":23,"surah":87,"verses":[10,11],"references":[{"surah":87,"verses":[10,11]}],"verseLabel":"الأعلى: 10–11","question":"ما أثر المقابلة بين ﴿مَنْ يَخْشَى﴾ و﴿الْأَشْقَى﴾؟","answer":"تقسم السامعين إلى قلب حي ينتفع، وآخر بلغ غاية الشقاء فيهرب من الهدى، فتوضح أثر الاختيار.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص36، تحت عنوان «بلاغة المقابلة»","url":""}]},{"id":"s87-11","number":11,"surah":87,"verses":[14,15],"references":[{"surah":87,"verses":[14,15]}],"verseLabel":"الأعلى: 14–15","question":"ماذا تفيد صيغة ﴿تَزَكَّى﴾؟","answer":"تفيد سعي الإنسان وتكلفه تطهير نفسه من الشرك والرذائل وتنميتها بالطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص46، تحت عنوان «دلالة التعبير بفعل التزكية مادة وصيغة»","url":""}]},{"id":"s87-24","number":24,"surah":87,"verses":[14,15],"references":[{"surah":87,"verses":[14,15]}],"verseLabel":"الأعلى: 14–15","question":"ما الصلة بين التزكي وذكر اسم الرب في طريق الفلاح؟","answer":"ليجمع بين تطهير الباطن وحضور ذكر الله في القلب واللسان، وهما متلازمان في طريق الفلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص46–47، تحت عنوان «توجيه العطف بالواو»","url":""}]},{"id":"s87-25","number":25,"surah":87,"verses":[14,15],"references":[{"surah":87,"verses":[14,15]}],"verseLabel":"الأعلى: 14–15","question":"كيف يقود ذكر اسم الرب إلى الصلاة في قوله ﴿فَصَلَّى﴾؟","answer":"تجعل الصلاة ثمرة للذكر والتزكي؛ فإذا استنار القلب ظهر أثره في أعظم العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص48، تحت عنوان «معنى الفاء ودلالتها»","url":""}]},{"id":"s87-12","number":12,"surah":87,"verses":[16,17],"references":[{"surah":87,"verses":[16,17]}],"verseLabel":"الأعلى: 16–17","question":"ماذا يصور فعل ﴿تُؤْثِرُونَ﴾ في اختيار الدنيا؟","answer":"يصوّر تفضيل الناس العاجل مع علمهم بوجود البديل، فيكشف خلل الموازنة لا مجرد الجهل.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص53، تحت عنوان «دلالة التعبير بفعل الإيثار مادة وصيغة»","url":""}]},{"id":"s87-26","number":26,"surah":87,"verses":[16,17],"references":[{"surah":87,"verses":[16,17]}],"verseLabel":"الأعلى: 16–17","question":"ماذا يفيد تنكير ﴿خَيْرٌ﴾ في وصف الآخرة؟","answer":"يفخم خيرها ويعم وجوهه كلها؛ فهي خير من الدنيا في ذاتها ولذاتها وأحوالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص56، تحت عنوان «نكتة التعبير بـ﴿خير﴾ نكرة منونًا»","url":""}]},{"id":"s87-27","number":27,"surah":87,"verses":[16,17],"references":[{"surah":87,"verses":[16,17]}],"verseLabel":"الأعلى: 16–17","question":"لماذا وصف الآخرة بأنها ﴿أَبْقَى﴾؟","answer":"لأن نعيمها لا ينقطع، بخلاف الدنيا مهما طال بقاؤها؛ فجمع الوصفان جودة النعيم ودوامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص57، تحت عنوان «نكتة التعبير عن المعطوف باسم التفضيل»","url":""}]},{"id":"s87-13","number":13,"surah":87,"verses":[18,19],"references":[{"surah":87,"verses":[18,19]}],"verseLabel":"الأعلى: 18–19","question":"إلى ماذا يشير قوله ﴿إِنَّ هَذَا لَفِي الصُّحُفِ الْأُولَى﴾؟","answer":"يشير إلى مضامين السورة من التوحيد والتزكية والصلاة وإيثار الآخرة، ويعظمها بإثبات قدمها في الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص61، تحت عنوان «دلالة التعبير باسم الإشارة»","url":""}]},{"id":"s87-28","number":28,"surah":87,"verses":[18,19],"references":[{"surah":87,"verses":[18,19]}],"verseLabel":"الأعلى: 18–19","question":"لماذا وصفت الصحف بأنها ﴿الْأُولَى﴾؟","answer":"لبيان قدم هذا الهدى وسبق وروده في الوحي، وتشويق السامع إلى معرفة تلك الصحف.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص62، تحت عنوان «نكتة وصف ﴿الصحف﴾ بـ﴿الأولى﴾»","url":""}]},{"id":"s87-29","number":29,"surah":87,"verses":[18,19],"references":[{"surah":87,"verses":[18,19]}],"verseLabel":"الأعلى: 18–19","question":"لماذا خصت صحف إبراهيم وموسى بالذكر؟","answer":"لأنهما من أشهر أصول الشرائع وأقدمها وأوثقها معرفة عند المخاطبين، وفي ذكرهما تأكيد لوحدة الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص62–63، تحت عنوان «وجه اصطفاء صحف إبراهيم وموسى عليهما السلام بالذكر»","url":""}]},{"id":"s87-30","number":30,"surah":87,"verses":[8],"references":[{"surah":87,"verses":[8]}],"verseLabel":"الأعلى: 8","question":"ما دلالة مجيء ﴿وَنُيَسِّرُكَ لِلْيُسْرَى﴾ بغير السين، مع قوله في سورة الليل: ﴿فَسَنُيَسِّرُهُ لِلْيُسْرَى﴾؟","answer":"حُذفت السين مع الرسول صلى الله عليه وسلم لأن أمره ميسر على كل حال وعلى سبيل الدوام، لا يختص ذلك بوقت دون وقت، ولو قال: «سنيسرك» لكان وعدًا بالتيسير في الاستقبال دون الحال، وهو غير مراد.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص132.","url":""}]},{"id":"s87-31","number":31,"surah":87,"verses":[4,5],"references":[{"surah":87,"verses":[4,5]}],"verseLabel":"الأعلى: 4–5","question":"ما سر العطف بالفاء في قوله: ﴿وَالَّذِي أَخْرَجَ الْمَرْعَى فَجَعَلَهُ غُثَاءً أَحْوَى﴾ مع أن صيرورته غثاء لا تعقب خروجه؟","answer":"الفاء هنا للتعقيب المجازي؛ فالمقام قد يقتضي من المتكلم تقصير المدة الطويلة فيأتي بالفاء، وقد يقتضي العكس فيأتي بـ«ثم»، كما عُبّر عن جعله حطامًا بـ«ثم» في آيتي الزمر والحديد. فمقام التقصير، كالنهي عن الانصراف إلى الدنيا وبيان سرعة زوالها، تناسبه الفاء.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج3، ص233–235.","url":""}]},{"id":"s87-32","number":32,"surah":87,"verses":[11,12],"references":[{"surah":87,"verses":[11,12]}],"verseLabel":"الأعلى: 11–12","question":"ما دلالة وصف النار بـ«الكبرى» في قوله: ﴿وَيَتَجَنَّبُهَا الْأَشْقَى الَّذِي يَصْلَى النَّارَ الْكُبْرَى﴾؟","answer":"فيه إشارة إلى نار مخصوصة أُعدّت للأشقى؛ فإن النار دركات وبعض العذاب أشد من بعض، فالأشقى يصلى نارًا قد لا يصلاها غيره ممن هو دونه في الشقاء.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص141.","url":""}]},{"id":"s87-33","number":33,"surah":87,"verses":[16],"references":[{"surah":87,"verses":[16]}],"verseLabel":"الأعلى: 16","question":"ما دلالة «بل» في قوله: ﴿بَلْ تُؤْثِرُونَ الْحَيَاةَ الدُّنْيَا﴾ بعد قوله: ﴿قَدْ أَفْلَحَ مَن تَزَكَّى﴾؟","answer":"«بل» هنا للإضراب الانتقالي، وهو الانتقال من غرض إلى غرض آخر مع عدم إرادة إبطال الكلام الأول؛ فجملة ﴿بَلْ تُؤْثِرُونَ الْحَيَاةَ الدُّنْيَا﴾ ليست إبطالًا لما قبلها، بل انتقال إلى غرض آخر.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج3، ص258؛ النحو العربي أحكام ومعان، ج2، ص322.","url":""}]},{"id":"s88-1","number":1,"surah":88,"verses":[1],"references":[{"surah":88,"verses":[1]}],"verseLabel":"الغاشية: 1","question":"لماذا افتتحت السورة بـ﴿هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ﴾؟","answer":"لتشويق السامع إلى خبر عظيم وتنبيهه أن ما سيأتي جدير بالاستماع، مع تقرير أن حديث القيامة سيبلغه ويوقظه من الغفلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص79–80، تحت عنوان «بلاغة الاستفهام بـ﴿هل﴾»","url":""}]},{"id":"s88-15","number":15,"surah":88,"verses":[1],"references":[{"surah":88,"verses":[1]}],"verseLabel":"الغاشية: 1","question":"ماذا يصور اسم القيامة ﴿الْغَاشِيَةِ﴾؟","answer":"يصور هولًا يعم الناس ويغشاهم فلا يجد أحد خارجًا عن سلطانه؛ فالاسم يجمع الشمول والمفاجأة وثقل ما يحيط بالخلائق.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص82–83، تحت عنوان «نكتة التعبير بلفظ ﴿الغاشية﴾»","url":""}]},{"id":"s88-2","number":2,"surah":88,"verses":[2,3,4,5,6,7],"references":[{"surah":88,"verses":[2,3,4,5,6,7]}],"verseLabel":"الغاشية: 2–7","question":"لماذا بدأ مشهد القيامة بالوجوه لا بالأجساد؟","answer":"خصت الوجوه لأنها أبرز ما تظهر عليه آثار السرور والحزن والذل. ويجوز أن يراد بها أصحابها على المجاز المرسل أو الكناية؛ فيبدأ التصوير بأظهر موضع يدل على حال الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص86، تحت عنوان «بلاغة التعبير بـ(الوجوه) بين المجاز المرسل والكناية»","url":""}]},{"id":"s88-3","number":3,"surah":88,"verses":[3],"references":[{"surah":88,"verses":[3]}],"verseLabel":"الغاشية: 3","question":"ماذا يكشف وصف الوجوه بأنها ﴿عَامِلَةٌ نَاصِبَةٌ﴾؟","answer":"يكشف دوام أصحابها في عمل شاق يورث التعب والذل، سواء في الدنيا في غير هدى أو في جر العذاب يوم القيامة؛ فالوجه يحمل أثر الشقاء كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص89، تحت عنوان «دلالة الإخبار عن الوجوه بالوصفين: ﴿عاملة﴾ ﴿ناصبة﴾»","url":""}]},{"id":"s88-16","number":16,"surah":88,"verses":[3],"references":[{"surah":88,"verses":[3]}],"verseLabel":"الغاشية: 3","question":"أين تكمن المفارقة التهكمية في ﴿عَامِلَةٌ نَاصِبَةٌ﴾؟","answer":"في أن العمل الذي كان يرجى منه النجاة لم يثمر إلا مزيدًا من النصب لأنه ضل طريق الحق؛ فتبدو كثرة الجهد سخرية مؤلمة حين تنتهي إلى النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص90، تحت عنوان «بلاغة الاستعارة التهكمية في قوله: ﴿عاملة ناصبة﴾»","url":""}]},{"id":"s88-4","number":4,"surah":88,"verses":[4,5,6,7],"references":[{"surah":88,"verses":[4,5,6,7]}],"verseLabel":"الغاشية: 4–7","question":"ماذا يضيف وصف النار بأنها ﴿حَامِيَةً﴾؟","answer":"يصور نارًا قد بلغت الغاية في الحرارة والاشتعال، وتنكيرها يعظم هولها ويمنع تصورها كنار مألوفة يمكن احتمالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص93، تحت عنوان «سر وصف (النار) بـ﴿حامية﴾ وتنكيره»","url":""}]},{"id":"s88-17","number":17,"surah":88,"verses":[4,5,6,7],"references":[{"surah":88,"verses":[4,5,6,7]}],"verseLabel":"الغاشية: 4–7","question":"لماذا وُصفت العين التي يشربون منها بأنها ﴿آنِيَةٍ﴾؟","answer":"لأن ماءها بلغ أقصى الحرارة، فيتحول الشراب الذي ينتظر منه التبريد إلى امتداد للعذاب. وتنكيرها يضخم شدة العين وفظاعتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص95، تحت عنوان «سر وصف العين بـ﴿آنية﴾ وتنكيره»","url":""}]},{"id":"s88-5","number":5,"surah":88,"verses":[6,7],"references":[{"surah":88,"verses":[6,7]}],"verseLabel":"الغاشية: 6–7","question":"لماذا نُفي عن الضريع أن يسمن أو يغني من جوع؟","answer":"لينفى عنه نوعا منفعة الطعام معًا: لا يبني البدن ولا يسكن ألم الجوع، بل يجمع مرارة الأكل وبقاء الحاجة. فالعطف يغلق كل احتمال لنفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص100–101، تحت عنوان «دلالة التعبير بقوله: ﴿ولا يغني﴾»","url":""}]},{"id":"s88-6","number":6,"surah":88,"verses":[8,9,10],"references":[{"surah":88,"verses":[8,9,10]}],"verseLabel":"الغاشية: 8–10","question":"ما أثر مقابلة الوجوه الناعمة بالوجوه الخاشعة؟","answer":"تجعل أثر المصير ظاهرًا على الوجه: ذل وتعب لأهل النار، ونضرة وراحة لأهل الجنة. وبالتقابل يزداد الفارق بين الطريقين وضوحًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص116، تحت عنوان «دلالة مقابلة قوله: ﴿ناعمة﴾ لقوله: ﴿خاشعة﴾»","url":""}]},{"id":"s88-18","number":18,"surah":88,"verses":[8,9,10],"references":[{"surah":88,"verses":[8,9,10]}],"verseLabel":"الغاشية: 8–10","question":"ماذا يعني أن وجوه أهل الجنة ﴿لِسَعْيِهَا رَاضِيَةٌ﴾؟","answer":"يعني أنهم يرون ثمرة أعمالهم مقبولة مضاعفة فيرضون عنها وعن جزائها، بخلاف من تعب سعيه ثم خاب. فالرضا يجمع نجاح العمل وطمأنينة صاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص119، تحت عنوان «دلالة التعبير بقوله: ﴿لسعيها راضية﴾»","url":""}]},{"id":"s88-7","number":7,"surah":88,"verses":[11],"references":[{"surah":88,"verses":[11]}],"verseLabel":"الغاشية: 11","question":"ما النعمة التي تتجاوز مجرد غياب اللغو في ﴿لَا تَسْمَعُ فِيهَا لَاغِيَةً﴾؟","answer":"هي صفاء الجنة من كل كلام باطل أو جارح أو مزعج؛ فنفي سماع كلمة لاغية يكني عن بيئة كاملة السلام، لا يكدّر نعيمها أذى اللسان ولا ضوضاؤه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص125، تحت عنوان «دلالة نفي سماع اللغو على نفي كل ما يؤذي»","url":""}]},{"id":"s88-8","number":8,"surah":88,"verses":[12,13,14,15,16],"references":[{"surah":88,"verses":[12,13,14,15,16]}],"verseLabel":"الغاشية: 12–16","question":"ماذا يضيف وصف عين الجنة بأنها ﴿جَارِيَةٌ﴾؟","answer":"يصور ماءً متجددًا متاحًا لا يركد ولا ينقطع، يجمع الري وحسن المنظر والصوت، فتبدو النعمة حية مستمرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص127، تحت عنوان «سر وصف العين بـ﴿جارية﴾ وصوغه اسم فاعل»","url":""}]},{"id":"s88-19","number":19,"surah":88,"verses":[12,13,14,15,16],"references":[{"surah":88,"verses":[12,13,14,15,16]}],"verseLabel":"الغاشية: 12–16","question":"لماذا وُصفت سرر الجنة بأنها ﴿مَرْفُوعَةٌ﴾؟","answer":"للدلالة على علو المكان والقدر، وحسن الإشراف وراحة الجالس، فهي هيئة تكريم لا مجرد أثاث للجلوس.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص128، تحت عنوان «سر وصف السرر بـ﴿مرفوعة﴾»","url":""}]},{"id":"s88-20","number":20,"surah":88,"verses":[12,13,14,15,16],"references":[{"surah":88,"verses":[12,13,14,15,16]}],"verseLabel":"الغاشية: 12–16","question":"ماذا يوحي وصف الأكواب بأنها ﴿مَوْضُوعَةٌ﴾؟","answer":"يوحي بأنها مهيأة قريبة في مواضعها تنتظر الشارب من غير طلب ولا عناء، فتكتمل خدمة أهل الجنة وراحتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص129، تحت عنوان «سر وصف الأكواب بـ﴿موضوعة﴾»","url":""}]},{"id":"s88-21","number":21,"surah":88,"verses":[12,13,14,15,16],"references":[{"surah":88,"verses":[12,13,14,15,16]}],"verseLabel":"الغاشية: 12–16","question":"لماذا وُصفت النمارق بأنها ﴿مَصْفُوفَةٌ﴾؟","answer":"لتصوير الوسائد كثيرة مرتبة متناسقة، معدة لمجالس الأنس والاجتماع، فيجتمع الجمال والراحة وحسن الاستقبال.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص130–131، تحت عنوان «سر وصف النمارق بـ﴿مصفوفة﴾»","url":""}]},{"id":"s88-22","number":22,"surah":88,"verses":[12,13,14,15,16],"references":[{"surah":88,"verses":[12,13,14,15,16]}],"verseLabel":"الغاشية: 12–16","question":"ماذا يضيف وصف الزرابي بأنها ﴿مَبْثُوثَةٌ﴾؟","answer":"يصور البسط الفاخرة منشورة بكثرة في أنحاء المجلس، ميسرة للجلوس حيث شاء أهله، فيدل على السعة والترف وتمام الإعداد.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص131، تحت عنوان «نكتة وصف الزرابي بـ﴿مبثوثة﴾»","url":""}]},{"id":"s88-9","number":9,"surah":88,"verses":[17],"references":[{"surah":88,"verses":[17]}],"verseLabel":"الغاشية: 17","question":"لماذا خُصت الإبل بالدعوة إلى النظر؟","answer":"لأنها أقرب عجائب الخلق إلى المخاطبين وأشدها نفعًا لهم، تجمع القوة والصبر وحمل الأثقال والانتفاع في بيئة الصحراء، فالحجة أمام أعينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص141، تحت عنوان «سر إيثار ذكر ﴿الإبل﴾ دون غيرها من الحيوانات»","url":""}]},{"id":"s88-23","number":23,"surah":88,"verses":[17],"references":[{"surah":88,"verses":[17]}],"verseLabel":"الغاشية: 17","question":"لماذا بدأ ترتيب آيات النظر بالإبل؟","answer":"ليبدأ من المشاهد القريب الملازم لحياة العربي، ثم يرتفع بصره إلى السماء ويمر بالجبال وينتهي بالأرض؛ فيتحرك التأمل من الأقرب إلى الآفاق المحيطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص141–142، تحت عنوان «علة الابتداء بـ﴿الإبل﴾ وترتيب المذكورات»","url":""}]},{"id":"s88-10","number":10,"surah":88,"verses":[17,18,19,20],"references":[{"surah":88,"verses":[17,18,19,20]}],"verseLabel":"الغاشية: 17–20","question":"ما الجامع بين الإبل والسماء والجبال والأرض في دعوة النظر؟","answer":"إنها أركان عالم المخاطب: مركوبه القريب، والسماء فوقه، والجبال البارزة أمامه، والأرض التي يسير عليها. وجمعها يحيط نظره بآيات القدرة من كل جهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص137، تحت عنوان «وجه الجمع بين (الإبل) و(السماء) و(الجبال) و(الأرض) دون غيرها»","url":""}]},{"id":"s88-11","number":11,"surah":88,"verses":[18,19,20],"references":[{"surah":88,"verses":[18,19,20]}],"verseLabel":"الغاشية: 18–20","question":"لماذا قيل عن الإبل ﴿كَيْفَ خُلِقَتْ﴾؟","answer":"لأن موضع العجب أصل تكوينها الجامع بين ضخامة الجسد والانقياد والصبر والمنافع، فلفظ الخلق يوجه إلى الحكمة في مجموع بنيتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص144، تحت عنوان «سر التعبير بالفعل ﴿خلقت﴾ دلالة وصيغة»","url":""}]},{"id":"s88-24","number":24,"surah":88,"verses":[18,19,20],"references":[{"surah":88,"verses":[18,19,20]}],"verseLabel":"الغاشية: 18–20","question":"ماذا يلفت إليه قوله عن السماء ﴿كَيْفَ رُفِعَتْ﴾؟","answer":"يلفت إلى علوها الهائل وبقائها بلا عمد مرئية، فيستحضر الناظر قدرة رفعتها وحفظت نظامها فوقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص145، تحت عنوان «نكتة التعبير بمفردة ﴿رفعت﴾»","url":""}]},{"id":"s88-25","number":25,"surah":88,"verses":[18,19,20],"references":[{"surah":88,"verses":[18,19,20]}],"verseLabel":"الغاشية: 18–20","question":"لماذا وصف الجبال بأنها ﴿نُصِبَتْ﴾؟","answer":"ليصور قيامها الشامخ الثابت كمعالم منصوبة في الأرض، بما فيها من هيبة وثقل ومنافع ودلالة على إحكام الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص146، تحت عنوان «نكتة التعبير بمفردة ﴿نصبت﴾»","url":""}]},{"id":"s88-26","number":26,"surah":88,"verses":[18,19,20],"references":[{"surah":88,"verses":[18,19,20]}],"verseLabel":"الغاشية: 18–20","question":"ماذا يصور قوله عن الأرض ﴿كَيْفَ سُطِحَتْ﴾؟","answer":"يصور تهيئة سطحها للعيش والسير والزراعة مع عظم جرمها، فيلتقي اتساعها المشاهد مع صلاحها لمصالح الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص147، تحت عنوان «نكتة التعبير بمفردة ﴿سطحت﴾»","url":""}]},{"id":"s88-12","number":12,"surah":88,"verses":[21,22],"references":[{"surah":88,"verses":[21,22]}],"verseLabel":"الغاشية: 21–22","question":"ماذا يحدد القصر في ﴿إِنَّمَا أَنْتَ مُذَكِّرٌ﴾ من مهمة الرسول؟","answer":"يحدد أن عليه البلاغ وإيقاظ الفطرة وإقامة الحجة، لا إجبار القلوب على الإيمان؛ فيثبت واجبه ويخفف عنه تبعة اختيار المعاندين.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص154، تحت عنوان «بلاغة القصر بـ﴿إنما﴾»","url":""}]},{"id":"s88-27","number":27,"surah":88,"verses":[21,22],"references":[{"surah":88,"verses":[21,22]}],"verseLabel":"الغاشية: 21–22","question":"ما الذي تنفيه كلمة ﴿بِمُصَيْطِرٍ﴾ عن الرسول؟","answer":"تنفي أن يكون متسلطًا قاهرًا يملك التحكم في ضمائر الناس أو إكراههم، مع بقاء سلطته في البيان والحجة لا في إجبار الاختيار.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص157، تحت عنوان «نكتة التعبير بمفردة (مصيطر) اسم فاعل منكر»","url":""}]},{"id":"s88-13","number":13,"surah":88,"verses":[23,24],"references":[{"surah":88,"verses":[23,24]}],"verseLabel":"الغاشية: 23–24","question":"كيف نفهم الاستثناء ﴿إِلَّا مَنْ تَوَلَّى وَكَفَرَ﴾؟","answer":"على القول الذي ترجحه الموسوعة، الاستثناء منقطع و«إلا» بمعنى «لكن»: لست مسيطرًا عليهم، لكن من تولى وكفر فالله يعذبه. وتذكر الموسوعة وجوهًا أخرى للاتصال؛ لذا يصاغ هذا التوجيه بوصفه وجهًا راجحًا، لا الاحتمال الوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص158–159، تحت عنوان «بلاغة الاستثناء بـ﴿إلا﴾»","url":""}]},{"id":"s88-14","number":14,"surah":88,"verses":[25,26],"references":[{"surah":88,"verses":[25,26]}],"verseLabel":"الغاشية: 25–26","question":"ماذا تؤكد عبارة ﴿إِنَّ إِلَيْنَا إِيَابَهُمْ﴾؟","answer":"تؤكد أن رجوعهم حتمي وإلى الله وحده، فلا مهرب ولا مرجع آخر. وتقديم ﴿إلينا﴾ يحصر المصير ويواجه وهم الإفلات.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص167–168، تحت عنوان «بلاغة تتابع التأكيدات في الآية»","url":""}]},{"id":"s88-28","number":28,"surah":88,"verses":[25,26],"references":[{"surah":88,"verses":[25,26]}],"verseLabel":"الغاشية: 25–26","question":"كيف يتدرج المشهد من إياب الخلق إلى الله إلى حسابهم؟","answer":"لإبراز الحساب مرحلة عظيمة مستقلة تعقب الرجوع، لا مجرد نتيجة هامشية؛ فيعودون أولًا ثم يقفون موقف المحاسبة الذي ينتظرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص170، تحت عنوان «سر العطف بـ﴿ثم﴾»","url":""}]},{"id":"s88-29","number":29,"surah":88,"verses":[25,26],"references":[{"surah":88,"verses":[25,26]}],"verseLabel":"الغاشية: 25–26","question":"ماذا يطمئن ويهدد في قوله ﴿إِنَّ عَلَيْنَا حِسَابَهُمْ﴾؟","answer":"يقرر أن الله تكفل بحسابهم وعدل جزائهم ولم يترك أمرهم للنبي أو للخلق؛ فيطمئن الرسول إلى أن خصومه لن يفلتوا، ويوقن المكذب أن حسابه واقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص171، تحت عنوان «فائدة تقديم المسند ﴿علينا﴾»","url":""}]},{"id":"s89-1","number":1,"surah":89,"verses":[1,2,3,4,5],"references":[{"surah":89,"verses":[1,2,3,4,5]}],"verseLabel":"الفجر: 1–5","question":"لماذا نُكِّرت ﴿لَيَالٍ عَشْرٍ﴾ في القسم؟","answer":"للتعظيم والتفخيم؛ فهي ليال شريفة عظيمة البركة، ومن أشهر تفسيرها عشر ذي الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص187، تحت عنوان «فائدة تنكير (ليال)»","url":""}]},{"id":"s89-18","number":18,"surah":89,"verses":[1,2,3,4,5],"references":[{"surah":89,"verses":[1,2,3,4,5]}],"verseLabel":"الفجر: 1–5","question":"لماذا أقسم الله بـ﴿الشَّفْعِ وَالْوَتْرِ﴾؟","answer":"لأنهما يجمعان نظام المخلوقات بين الأزواج والأفراد، أو يشيران إلى أزمنة وعبادات مخصوصة؛ فتتسع العبارة لدلائل القدرة والطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص188–189، تحت عنوان «نكتة القسم بالشفع والوتر»","url":""}]},{"id":"s89-19","number":19,"surah":89,"verses":[1,2,3,4,5],"references":[{"surah":89,"verses":[1,2,3,4,5]}],"verseLabel":"الفجر: 1–5","question":"ماذا يصور قوله ﴿وَاللَّيْلِ إِذَا يَسْرِ﴾؟","answer":"يشخص الليل كمسافر يمضي وينحسر، فتتحرك الظلمة نحو الزوال ويتهيأ ظهور الفجر.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص189، تحت عنوان «دلالة تقييد الليل بكونه ﴿إذا يسر﴾»","url":""}]},{"id":"s89-20","number":20,"surah":89,"verses":[1,2,3,4,5],"references":[{"surah":89,"verses":[1,2,3,4,5]}],"verseLabel":"الفجر: 1–5","question":"لماذا طال القسم في مطلع سورة الفجر؟","answer":"لزيادة تشويق السامع إلى جواب القسم وتعظيم الخبر الآتي، مع جمع مشاهد الزمن والعبادة والكون في تمهيد واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص192، تحت عنوان «نكتة تطويل القسم»","url":""}]},{"id":"s89-2","number":2,"surah":89,"verses":[5],"references":[{"surah":89,"verses":[5]}],"verseLabel":"الفجر: 5","question":"ماذا يفيد سؤال ﴿هَلْ فِي ذَلِكَ قَسَمٌ لِذِي حِجْرٍ﴾؟","answer":"يقرر أن في هذه الأقسام كفاية وحجة لمن يعقل، ويوبخ ضمنًا من لم ينتفع بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص196، تحت عنوان «بلاغة الاستفهام وغرضه»","url":""}]},{"id":"s89-21","number":21,"surah":89,"verses":[5],"references":[{"surah":89,"verses":[5]}],"verseLabel":"الفجر: 5","question":"لماذا سمي العقل ﴿حِجْرٍ﴾؟","answer":"لأنه يحجر صاحبه عن الباطل والهوى كما يمنع الحاجز التجاوز، فالعقل الحق قوة ضبط لا مجرد معرفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص199، تحت عنوان «بلاغة استعمال مفردة ﴿حجر﴾، ولطائفه»","url":""}]},{"id":"s89-22","number":22,"surah":89,"verses":[5],"references":[{"surah":89,"verses":[5]}],"verseLabel":"الفجر: 5","question":"بمن يعرّض قوله ﴿لِذِي حِجْرٍ﴾؟","answer":"يعرض بالمكذبين الذين لم يحجزهم عقلهم عن الإنكار رغم وضوح الدلائل، فكأنهم فقدوا وظيفة العقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص199، تحت عنوان «بلاغة التعريض»","url":""}]},{"id":"s89-3","number":3,"surah":89,"verses":[6],"references":[{"surah":89,"verses":[6]}],"verseLabel":"الفجر: 6","question":"لماذا عبّر عن أخبار الأمم بقوله ﴿أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ﴾؟","answer":"لإنزال الخبر المعلوم منزلة المشاهد في وضوحه وثبوته، حتى يرى السامع مصارع الطغاة رأي عين.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص207، تحت عنوان «نوع الرؤية وفائدة التعبير بها»","url":""}]},{"id":"s89-23","number":23,"surah":89,"verses":[6],"references":[{"surah":89,"verses":[6]}],"verseLabel":"الفجر: 6","question":"ماذا تضيف كلمة ﴿رَبُّكَ﴾ في عرض مصارع الطغاة؟","answer":"تثبت النبي ﷺ بأن ربه الذي يرعاه هو الذي أهلكهم، وفي إضافة الرب إلى ضميره تشريف ووعد بالنصرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص209، تحت عنوان «دلالة إضافة لفظ الربوبية إلى ضمير الخطاب»","url":""}]},{"id":"s89-4","number":4,"surah":89,"verses":[6,7,8,9,10],"references":[{"surah":89,"verses":[6,7,8,9,10]}],"verseLabel":"الفجر: 6–10","question":"لماذا خُصت عاد وثمود وفرعون بالذكر؟","answer":"لشهرة قوتهم وعمرانهم وسلطانهم وخبر هلاكهم عند المخاطبين؛ فاجتماعهم يثبت أن اختلاف أسباب القوة لا يمنع أخذ الطغاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص210، تحت عنوان «توجيه تخصيص المذكورين بالذكر»","url":""}]},{"id":"s89-5","number":5,"surah":89,"verses":[7],"references":[{"surah":89,"verses":[7]}],"verseLabel":"الفجر: 7","question":"ماذا يوحي وصف عاد بأنها ﴿إِرَمَ ذَاتِ الْعِمَادِ﴾؟","answer":"يوحي بقوة الأبنية أو الخيام وعظم الحضارة، ويستحضر منعتهم التي لم تحمهم من العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص212، تحت عنوان «نكتة وصف عاد بـ﴿ذات العماد﴾»","url":""}]},{"id":"s89-24","number":24,"surah":89,"verses":[7],"references":[{"surah":89,"verses":[7]}],"verseLabel":"الفجر: 7","question":"كيف يجمع لفظ ﴿الْعِمَادِ﴾ بين الحقيقة والصورة؟","answer":"قد يراد به أعمدة البناء حقيقة، وقد يشبه به طول أجسام عاد وقوتها؛ وفي الوجهين يبرز رسوخ القوة وضخامتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص213، تحت عنوان «بلاغة لفظ ﴿العماد﴾ بين الحقيقة والمجاز»","url":""}]},{"id":"s89-6","number":6,"surah":89,"verses":[9],"references":[{"surah":89,"verses":[9]}],"verseLabel":"الفجر: 9","question":"ماذا تصور كلمة ﴿جَابُوا﴾ في وصف ثمود؟","answer":"تصور شق الصخر وقطعه ونحته بقوة حتى اتخذوه بيوتًا، فتجعل صنعتهم وعمرانهم مشهدًا محسوسًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص219، تحت عنوان «بلاغة استعمال مفردة ﴿جابوا﴾»","url":""}]},{"id":"s89-25","number":25,"surah":89,"verses":[9],"references":[{"surah":89,"verses":[9]}],"verseLabel":"الفجر: 9","question":"لماذا قيل ﴿الصَّخْرَ﴾ لا «الحجر»؟","answer":"لأن الصخر أشد صلابة وأعظم جرمًا، فاختياره أدل على قوة ثمود وقدرتهم على النحت.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص219، تحت عنوان «فائدة ذكر ﴿الصخر﴾ دون الحجر»","url":""}]},{"id":"s89-8","number":8,"surah":89,"verses":[12],"references":[{"surah":89,"verses":[12]}],"verseLabel":"الفجر: 12","question":"لماذا وُصف فعل الأمم بأنه ﴿طَغَوْا﴾؟","answer":"لأن الطغيان تجاوز الحد في الكفر والظلم والتسلط، وهو الأصل الذي ولّد فسادهم في البلاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص224، تحت عنوان «فائدة ذكر الطغيان دون القيام»","url":""}]},{"id":"s89-26","number":26,"surah":89,"verses":[12],"references":[{"surah":89,"verses":[12]}],"verseLabel":"الفجر: 12","question":"لماذا قيل ﴿فَأَكْثَرُوا فِيهَا الْفَسَادَ﴾ لا «أفسدوا»؟","answer":"ليصور كثرة وجوه فسادهم واتساعها وتكرارها، لا مجرد وقوع الإفساد مرة أو في جانب واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص226، تحت عنوان «براعة التعبير بالإكثار من الفساد دون الإفساد»","url":""}]},{"id":"s89-9","number":9,"surah":89,"verses":[13],"references":[{"surah":89,"verses":[13]}],"verseLabel":"الفجر: 13","question":"ما الصورة في قوله ﴿فَصَبَّ عَلَيْهِمْ رَبُّكَ﴾؟","answer":"استعير الصب لنزول العذاب متتابعًا سريعًا غامرًا كما يصب الماء، فتتجسد كثافته وإحاطته.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص228، تحت عنوان «بلاغة الاستعارة في لفظ (صب)»","url":""}]},{"id":"s89-27","number":27,"surah":89,"verses":[13],"references":[{"surah":89,"verses":[13]}],"verseLabel":"الفجر: 13","question":"لماذا سمي العذاب ﴿سَوْطَ عَذَابٍ﴾؟","answer":"شبه العذاب بالسوط لما فيه من إيلام وإهانة، مع الإشارة إلى أن ما نزل بهم جزء من عذاب أعظم.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص229، تحت عنوان «بلاغة الاستعارة في استعمال مفردة ﴿سوط﴾»","url":""}]},{"id":"s89-10","number":10,"surah":89,"verses":[14],"references":[{"surah":89,"verses":[14]}],"verseLabel":"الفجر: 14","question":"ما موقع ﴿إِنَّ رَبَّكَ لَبِالْمِرْصَادِ﴾ بعد قصص الطغاة؟","answer":"تعلل ما نزل بهم وتعمم سنته في الجزاء، وتصلح جوابًا للقسم: فالله يرصد أعمال العباد ولا يفوته ظالم.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص231–232، تحت عنوان «موقع جملة ﴿إن ربك لبالمرصاد﴾ بين التعليل وجواب القسم»","url":""}]},{"id":"s89-28","number":28,"surah":89,"verses":[14],"references":[{"surah":89,"verses":[14]}],"verseLabel":"الفجر: 14","question":"لماذا تكرر عنوان الربوبية في ﴿إِنَّ رَبَّكَ لَبِالْمِرْصَادِ﴾؟","answer":"لتثبيت النبي ﷺ بأن ربه المتولي له يرصد أعداءه ويكفيه أمرهم، فاجتمع الوعيد للطغاة والوعد للرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص233، تحت عنوان «نكتة تكرار عنوان الربوبية»","url":""}]},{"id":"s89-29","number":29,"surah":89,"verses":[14],"references":[{"surah":89,"verses":[14]}],"verseLabel":"الفجر: 14","question":"ما الصورة في ﴿إِنَّ رَبَّكَ لَبِالْمِرْصَادِ﴾؟","answer":"تمثل إحاطة الله بأعمال الناس وأخذه الجناة بحال من يرصد الطريق فلا يفوته مار، من غير تشبيه لله بخلقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص233–234، تحت عنوان «بلاغة الكناية بالاستعارة التمثيلية»","url":""}]},{"id":"s89-11","number":11,"surah":89,"verses":[15,16],"references":[{"surah":89,"verses":[15,16]}],"verseLabel":"الفجر: 15–16","question":"لماذا وصف توسيع الرزق وتضييقه بالابتلاء؟","answer":"لأن الحالين اختبار للشكر والصبر، فلا السعة دليل كرامة ذاتية ولا الضيق دليل هوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص242، تحت عنوان «بلاغة استعمال مفردة ﴿ابتلاه﴾ دون مقارباتها»","url":""}]},{"id":"s89-30","number":30,"surah":89,"verses":[15,16],"references":[{"surah":89,"verses":[15,16]}],"verseLabel":"الفجر: 15–16","question":"لماذا قال ﴿فَقَدَرَ عَلَيْهِ رِزْقَهُ﴾ ولم يقل «فأهانه»؟","answer":"لأن التضييق فعل الله الاختباري، أما الإهانة فهي تفسير الإنسان الخاطئ؛ ففصل التعبير بين الواقع والحكم المتوهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص248، تحت عنوان «فائدة استعمال مفردة (قدر) دون (أهانن)»","url":""}]},{"id":"s89-31","number":31,"surah":89,"verses":[15,16],"references":[{"surah":89,"verses":[15,16]}],"verseLabel":"الفجر: 15–16","question":"ماذا ردت ﴿كَلَّا﴾ بعد قول الإنسان ﴿رَبِّي أَكْرَمَنِ﴾ و﴿رَبِّي أَهَانَنِ﴾؟","answer":"ردت جعل الغنى معيار الكرامة والفقر معيار الهوان؛ فالميزان هو الإيمان والعمل، والنعمة والضيق كلاهما امتحان.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص251، تحت عنوان «براعة مجيء أداة ﴿كلا﴾»","url":""}]},{"id":"s89-12","number":12,"surah":89,"verses":[17,18,19,20],"references":[{"surah":89,"verses":[17,18,19,20]}],"verseLabel":"الفجر: 17–20","question":"لماذا قال ﴿لَا تُكْرِمُونَ الْيَتِيمَ﴾ لا «لا تطعمونه»؟","answer":"لأن حق اليتيم أوسع من النفقة؛ يشمل صيانة كرامته وحفظ ماله ورعايته، فالإكرام يجمع الحقوق المادية والمعنوية.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص253، تحت عنوان «بلاغة التعبير بمفردة الإكرام دون النفقة أو الإطعام»","url":""}]},{"id":"s89-32","number":32,"surah":89,"verses":[17,18,19,20],"references":[{"surah":89,"verses":[17,18,19,20]}],"verseLabel":"الفجر: 17–20","question":"ماذا يكشف قوله ﴿وَلَا تَحَاضُّونَ عَلَى طَعَامِ الْمِسْكِينِ﴾؟","answer":"يكشف أن المجتمع لم يترك الإطعام فقط، بل فقد روح التواصي والتكافل؛ فلا يحث بعضهم بعضًا على سد حاجة الضعيف.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص255، تحت عنوان «بلاغة استعمال مفردة الحض»","url":""}]},{"id":"s89-33","number":33,"surah":89,"verses":[17,18,19,20],"references":[{"surah":89,"verses":[17,18,19,20]}],"verseLabel":"الفجر: 17–20","question":"ما سر ترتيب إهمال اليتيم والمسكين وأكل التراث وحب المال؟","answer":"بدأ بحقوق الأضعف، ثم كشف الاعتداء على المال، وختم بالدافع الباطن وهو الحب الشديد؛ فانتقل من المظاهر إلى أصلها النفسي.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص259، تحت عنوان «براعة ترتيب المعطوفات بالذكر»","url":""}]},{"id":"s89-34","number":34,"surah":89,"verses":[17,18,19,20],"references":[{"surah":89,"verses":[17,18,19,20]}],"verseLabel":"الفجر: 17–20","question":"ما الكناية في ﴿وَتُحِبُّونَ الْمَالَ حُبًّا جَمًّا﴾؟","answer":"تكشف شدة التعلق بالمال حتى يحمل على منع الحقوق وأكل الميراث، فالمذموم الحب المستولي لا أصل حب المال.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص262، تحت عنوان «بلاغة الكناية ودلالتها»","url":""}]},{"id":"s89-13","number":13,"surah":89,"verses":[19],"references":[{"surah":89,"verses":[19]}],"verseLabel":"الفجر: 19","question":"ماذا يصور ﴿أَكْلًا لَمًّا﴾؟","answer":"يصور جمع الميراث وأكله بنهم من غير تمييز بين حلال وحرام ولا مراعاة حقوق الضعفاء، فكأن صاحبه يضم كل شيء إلى نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص260–261، تحت عنوان «بلاغة استعمال مفردة ﴿لمًّا﴾»","url":""}]},{"id":"s89-14","number":14,"surah":89,"verses":[21],"references":[{"surah":89,"verses":[21]}],"verseLabel":"الفجر: 21","question":"ماذا تصور كلمة ﴿دُكَّتِ﴾ في مشهد القيامة؟","answer":"تصور تحطيم المرتفعات ودق الأرض حتى تستوي، فتزول معالم القوة والثبات التي ألفها الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص269، تحت عنوان «نكتة استعمال مفردة ﴿دكت﴾»","url":""}]},{"id":"s89-35","number":35,"surah":89,"verses":[21],"references":[{"surah":89,"verses":[21]}],"verseLabel":"الفجر: 21","question":"ماذا أفاد تكرار ﴿دَكًّا دَكًّا﴾؟","answer":"أفاد استمرار الدك وتتابعه واستيعابه أجزاء الأرض، مع توكيد وقوع الهول وشدته.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص270–271، تحت عنوان «فائدة تكرار لفظ ﴿دكًّا دكًّا﴾، واحتمالاتها الدلالية»","url":""}]},{"id":"s89-15","number":15,"surah":89,"verses":[22],"references":[{"surah":89,"verses":[22]}],"verseLabel":"الفجر: 22","question":"كيف يفهم قوله ﴿وَجَاءَ رَبُّكَ﴾؟","answer":"يؤمن بما أخبر الله به على ما يليق بجلاله من غير تكييف ولا تشبيه، وفي السياق ظهور سلطان الله للفصل بين العباد.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص271–272، تحت عنوان «بلاغة إسناد المجيء إلى لفظ الربوبية»","url":""}]},{"id":"s89-36","number":36,"surah":89,"verses":[22],"references":[{"surah":89,"verses":[22]}],"verseLabel":"الفجر: 22","question":"ماذا يفيد لفظ ﴿الْمَلَكُ﴾ في مشهد القيامة؟","answer":"هو اسم جنس يعم الملائكة، فيستحضر حضور جموعهم كلها بأمر الله في يوم الفصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص272، تحت عنوان «معنى تعريف لفظ (الملك)»","url":""}]},{"id":"s89-37","number":37,"surah":89,"verses":[22],"references":[{"surah":89,"verses":[22]}],"verseLabel":"الفجر: 22","question":"ماذا يصور قوله ﴿وَالْمَلَكُ صَفًّا صَفًّا﴾؟","answer":"يصور اصطفاف الملائكة صفوفًا متعددة منتظمة، فيزيد المشهد هيبة ونظامًا وعظمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص273، تحت عنوان «دلالة تركيب ﴿صفًّا صفًّا﴾»","url":""}]},{"id":"s89-16","number":16,"surah":89,"verses":[23,24],"references":[{"surah":89,"verses":[23,24]}],"verseLabel":"الفجر: 23–24","question":"كيف يتذكر الإنسان يومئذ ثم لا تنفعه الذكرى؟","answer":"يتذكر حقيقة ما ضيع فيورثه ذلك الحسرة، لكن زمن العمل قد انتهى؛ فالمنفي نفع الذكرى لا وقوعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص277، تحت عنوان «بلاغة الاستفهام وغرضه في نفي التذكر بعد إثباته»","url":""}]},{"id":"s89-38","number":38,"surah":89,"verses":[23,24],"references":[{"surah":89,"verses":[23,24]}],"verseLabel":"الفجر: 23–24","question":"ماذا يكشف قوله ﴿يَا لَيْتَنِي قَدَّمْتُ﴾؟","answer":"يكشف ندمًا بالغًا وتمنيًا مستحيلًا للعودة، حين يرى أن ما قدمه في الدنيا هو زاده الحقيقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص280، تحت عنوان «بلاغة تركيب ﴿يا ليتني﴾»","url":""}]},{"id":"s89-39","number":39,"surah":89,"verses":[23,24],"references":[{"surah":89,"verses":[23,24]}],"verseLabel":"الفجر: 23–24","question":"لماذا قال ﴿قَدَّمْتُ لِحَيَاتِي﴾ لا «لآخرتي»؟","answer":"لأن الآخرة هي الحياة الباقية الجديرة باسم الحياة، أما الدنيا فمرحلة عابرة ينبغي أن تكون إعدادًا لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص281، تحت عنوان «براعة استعمال مفردة (حياتي) دون (آخرتي)»","url":""}]},{"id":"s89-17","number":17,"surah":89,"verses":[27,28,29,30],"references":[{"surah":89,"verses":[27,28,29,30]}],"verseLabel":"الفجر: 27–30","question":"لماذا وصفت النفس المؤمنة بأنها ﴿الْمُطْمَئِنَّةُ﴾؟","answer":"لثباتها بالإيمان وسكونها إلى وعد الله بعد اضطراب النفوس، فالوصف يجمع الأمن واليقين والرضا.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص293، تحت عنوان «بلاغة التعبير بمفردة ﴿المطمئنة﴾ دون مقارباتها»","url":""}]},{"id":"s89-40","number":40,"surah":89,"verses":[27,28,29,30],"references":[{"surah":89,"verses":[27,28,29,30]}],"verseLabel":"الفجر: 27–30","question":"ماذا يجمع وصف النفس بأنها ﴿رَاضِيَةً مَرْضِيَّةً﴾؟","answer":"يجمع رضاها بما أعطاها الله ورضا الله عنها؛ فالتبادل بين اسم الفاعل والمفعول يكمل كرامتها من الجهتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص295–296، تحت عنوان «بلاغة التعبير بصيغتي اسم الفاعل والمفعول»","url":""}]},{"id":"s89-41","number":41,"surah":89,"verses":[27,28,29,30],"references":[{"surah":89,"verses":[27,28,29,30]}],"verseLabel":"الفجر: 27–30","question":"لماذا قُدِّم ﴿فَادْخُلِي فِي عِبَادِي﴾ على ﴿وَادْخُلِي جَنَّتِي﴾؟","answer":"لأن شرف الانتساب إلى عباد الله الصالحين ورفقتهم كرامة تسبق كرامة المكان، ثم يكتمل النعيم بدخول الجنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص298، تحت عنوان «نكتة تقديم الأمر بالدخول في العباد على دخول الجنة»","url":""}]},{"id":"s89-42","number":42,"surah":89,"verses":[15],"references":[{"surah":89,"verses":[15]}],"verseLabel":"الفجر: 15","question":"ما سر التعبير بـ«أكرمه» في قوله: ﴿فَأَكْرَمَهُ وَنَعَّمَهُ﴾ دون «كرّمه»؟","answer":"«فعّل» يفيد التكثير والمبالغة غالبًا، فاستُعمل التكريم لما هو أبلغ وأدوم وأعم، أما الإكرام هنا فالمقصود به إكرامه بالمال، ومثله ﴿بَل لَّا تُكْرِمُونَ الْيَتِيمَ﴾.","sources":[{"label":"فاضل السامرائي، بلاغة الكلمة في التعبير القرآني، ص58–59.","url":""}]},{"id":"s89-43","number":43,"surah":89,"verses":[4],"references":[{"surah":89,"verses":[4]}],"verseLabel":"الفجر: 4","question":"ما سر حذف الياء من الفعل في قوله: ﴿وَاللَّيْلِ إِذَا يَسْرِ﴾؟","answer":"الحذف أنسب للفاصلة، وحسّنه المقام أيضًا؛ فقد قال بعده: ﴿لِّذِي حِجْرٍ﴾، والحجر العقل الذي يحبس صاحبه عما لا يليق ويقيد حركته، فحُذف من «يسري» إشارة إلى تقييد حركة الليل فلا يطغى على النهار. وهو مناسب لذكر الطغاة بعده، وللوثاق في آخر السورة ﴿وَلَا يُوثِقُ وَثَاقَهُ أَحَدٌ﴾.","sources":[{"label":"فاضل السامرائي، الجملة العربية تأليفها وأقسامها، ص98–99.","url":""}]},{"id":"s89-44","number":44,"surah":89,"verses":[29],"references":[{"surah":89,"verses":[29]}],"verseLabel":"الفجر: 29","question":"ما سر إثبات الياء في قوله: ﴿فَادْخُلِي فِي عِبَادِي﴾، مع حذفها في قوله: ﴿فَبَشِّرْ عِبَادِ﴾؟","answer":"ما ذُكرت فيه الياء أوسع وأشمل مما حُذفت منه؛ فالعباد في آية الفجر عموم من يدخل الجنة، وفي آية الزمر خُصّوا بمن يتبعون أحسن القول، فزاد البناء لما كثر العباد. وهو مناسب لقوله بعده: ﴿وَادْخُلِي جَنَّتِي﴾؛ فالعباد عباده والجنة جنته.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص164–165.","url":""}]},{"id":"s90-1","number":1,"surah":90,"verses":[1,2],"references":[{"surah":90,"verses":[1,2]}],"verseLabel":"البلد: 1–2","question":"لماذا عُرِّف ﴿الْبَلَدِ﴾ في قسم سورة البلد؟","answer":"للعهد؛ فالمراد البلد المعروف المشاهد، مكة، وبذلك يتجه الذهن إليها مباشرة ويزداد القسم تشريفًا لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص315، تحت عنوان «فائدة تعريف لفظ ﴿البلد﴾»","url":""}]},{"id":"s90-14","number":14,"surah":90,"verses":[1,2],"references":[{"surah":90,"verses":[1,2]}],"verseLabel":"البلد: 1–2","question":"ما الثراء الدلالي الذي تحمله كلمة ﴿حِلٌّ﴾ في قوله ﴿وَأَنْتَ حِلٌّ بِهَذَا الْبَلَدِ﴾؟","answer":"تحتمل كونه ﷺ حالًّا مقيمًا بمكة، وكونها قد أحلت له ساعة الفتح، وكون المشركين استحلوا حرمته فيها؛ فتجتمع في اللفظ صلته بالبلد وكرامته والمفارقة في موقف قومه منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص316–317، تحت عنوان «بلاغة الثراء الدلالي للفظ ﴿حل﴾»","url":""}]},{"id":"s90-15","number":15,"surah":90,"verses":[1,2],"references":[{"surah":90,"verses":[1,2]}],"verseLabel":"البلد: 1–2","question":"ما التعريض في قوله ﴿وَأَنْتَ حِلٌّ بِهَذَا الْبَلَدِ﴾؟","answer":"يعرّض بأهل مكة: يعظمون حرمة بلدهم، ثم يستحلون إيذاء أشرف من حلّ فيه؛ فتكشف الجملة تناقضهم من غير تصريح مباشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص317، تحت عنوان «بلاغة التعريض في قوله: ﴿وأنت حل﴾»","url":""}]},{"id":"s90-2","number":2,"surah":90,"verses":[3],"references":[{"surah":90,"verses":[3]}],"verseLabel":"البلد: 3","question":"لماذا أقسم الله بـ﴿وَالِدٍ﴾ من غير أن يعيّنه؟","answer":"ليتسع اللفظ لكل والد وما في الوالدية من آية التناسل وبقاء النوع، مع احتمال إرادة آدم أو إبراهيم عليهما السلام بحسب السياق؛ فالإبهام يثري دلالة القسم ولا يحصرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص319–320، تحت عنوان «بلاغة القسم بلفظ (والد)»","url":""}]},{"id":"s90-16","number":16,"surah":90,"verses":[3],"references":[{"surah":90,"verses":[3]}],"verseLabel":"البلد: 3","question":"ما فائدة الجمع في القسم بين ﴿وَالِدٍ وَمَا وَلَدَ﴾؟","answer":"ليستوعب أصل النسل وفروعه، ويلفت إلى عجيب استمرار الحياة وتكاثر الخلق؛ فيصبح الوالد والمولود معًا شاهدين على قدرة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص322، تحت عنوان «فائدة الجمع بين الوالد والمولود»","url":""}]},{"id":"s90-3","number":3,"surah":90,"verses":[4],"references":[{"surah":90,"verses":[4]}],"verseLabel":"البلد: 4","question":"ماذا تصور ﴿فِي﴾ في قوله ﴿خَلَقْنَا الْإِنْسَانَ فِي كَبَدٍ﴾؟","answer":"تصور الإنسان محاطًا بالمشقة كأنه داخل ظرف لا ينفك عنه، لا مجرد ملامس لها؛ فتجعل المكابدة بيئة ملازمة لحياته.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص326، تحت عنوان «بلاغة استعمال حرف الظرفية»","url":""}]},{"id":"s90-17","number":17,"surah":90,"verses":[4],"references":[{"surah":90,"verses":[4]}],"verseLabel":"البلد: 4","question":"لماذا اختيرت كلمة ﴿كَبَدٍ﴾ لوصف حياة الإنسان؟","answer":"لأنها تجمع الشدة والمشقة ومعاناة الأمر، وتوحي بمكابدة متصلة منذ الخلق؛ وهي أوجز وأقوى من تفصيل ألوان التعب.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص327، تحت عنوان «نكتة استعمال مفردة ﴿كبد﴾»","url":""}]},{"id":"s90-4","number":4,"surah":90,"verses":[5,6,7],"references":[{"surah":90,"verses":[5,6,7]}],"verseLabel":"البلد: 5–7","question":"ماذا يوبخ الاستفهام في ﴿أَيَحْسَبُ أَنْ لَنْ يَقْدِرَ عَلَيْهِ أَحَدٌ﴾؟","answer":"يوبخ الإنسان المغرور الذي يتصرف كأن قوته تمنع الحساب والعقاب، وينكر عليه هذا الوهم لأن قدرة الله محيطة به.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص332، تحت عنوان «بلاغة الاستفهام في قوله: ﴿أيحسب﴾»","url":""}]},{"id":"s90-18","number":18,"surah":90,"verses":[5,6,7],"references":[{"surah":90,"verses":[5,6,7]}],"verseLabel":"البلد: 5–7","question":"لماذا قال المتفاخر ﴿أَهْلَكْتُ مَالًا﴾ ولم يقل «أنفقت»؟","answer":"لأن ﴿أهلكت﴾ تلائم الإسراف والتبذير فيما لا ينفع، وتفضح أن ما يعده مفخرة هو في الحقيقة إضاعة للمال وإفساد له.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص340، تحت عنوان «بلاغة استعمال مفردة ﴿أهلكت﴾ دون (أفنيت) أو (أنفقت)»","url":""}]},{"id":"s90-19","number":19,"surah":90,"verses":[5,6,7],"references":[{"surah":90,"verses":[5,6,7]}],"verseLabel":"البلد: 5–7","question":"ماذا ينكر الاستفهام في ﴿أَيَحْسَبُ أَنْ لَمْ يَرَهُ أَحَدٌ﴾؟","answer":"ينكر ظنه أن إنفاقه أو تبذيره وخفايا قصده تغيب عن الرقابة؛ فالله يراه ويحاسبه، ولا تنجيه دعوى لا يعلمها الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص342، تحت عنوان «بلاغة جملة الاستفهام ﴿أيحسب﴾»","url":""}]},{"id":"s90-20","number":20,"surah":90,"verses":[5,6,7],"references":[{"surah":90,"verses":[5,6,7]}],"verseLabel":"البلد: 5–7","question":"لماذا عبّر بـ﴿يَرَهُ﴾ في قوله ﴿أَيَحْسَبُ أَنْ لَمْ يَرَهُ أَحَدٌ﴾؟","answer":"لأن الرؤية أبلغ في استحضار المراقبة من مجرد العلم؛ فهي تصور عمله مكشوفًا مشهودًا، وتجعل توهم الخفاء أشد بطلانًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص344، تحت عنوان «دلالة استعمال فعل ﴿يره﴾»","url":""}]},{"id":"s90-5","number":5,"surah":90,"verses":[8,9,10],"references":[{"surah":90,"verses":[8,9,10]}],"verseLabel":"البلد: 8–10","question":"لماذا امتن الله بالعينين بدل أن يقول: ألم نجعل له بصرًا؟","answer":"لأن ذكر العينين يستحضر العضوين المحسوسين بما فيهما من دقة الصنعة ومنافع متعددة، أما البصر فيقتصر على قوة الرؤية.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص350، تحت عنوان «بلاغة التعبير بالعينين دون الإبصار أو الرؤية»","url":""}]},{"id":"s90-21","number":21,"surah":90,"verses":[8,9,10],"references":[{"surah":90,"verses":[8,9,10]}],"verseLabel":"البلد: 8–10","question":"لماذا عُطف اللسان والشفتان على العينين في تعداد النعم؟","answer":"لجمع أدوات تلقي المعرفة وأدوات التعبير عنها؛ فبالعينين يبصر الإنسان، وباللسان والشفتين ينطق ويبين ويتواصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص350، تحت عنوان «نكتة عطف ﴿ولسانًا وشفتين﴾ على العينين»","url":""}]},{"id":"s90-22","number":22,"surah":90,"verses":[8,9,10],"references":[{"surah":90,"verses":[8,9,10]}],"verseLabel":"البلد: 8–10","question":"ما مناسبة ذكر الهداية إلى النجدين بعد العينين واللسان والشفتين؟","answer":"لأن الحواس وأدوات البيان تهيئ الإنسان للإدراك، ثم تأتي هداية الله لتعرّفه طريق الخير وطريق الشر؛ فتتكامل آلة المعرفة مع بيان وجهتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص351، تحت عنوان «توجيه عطف الهداية على الحواس»","url":""}]},{"id":"s90-23","number":23,"surah":90,"verses":[8,9,10],"references":[{"surah":90,"verses":[8,9,10]}],"verseLabel":"البلد: 8–10","question":"أي نوع من الهداية يدل عليه قوله ﴿وَهَدَيْنَاهُ النَّجْدَيْنِ﴾؟","answer":"هي هداية الدلالة والبيان: عرّفه الله طريق الخير وطريق الشر ومكّنه من الاختيار، وليست هداية إلجاء تسلبه إرادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص351–352، تحت عنوان «نوع الهداية ودلالتها»","url":""}]},{"id":"s90-6","number":6,"surah":90,"verses":[11],"references":[{"surah":90,"verses":[11]}],"verseLabel":"البلد: 11","question":"ماذا تضيف كلمة ﴿اقْتَحَمَ﴾ إلى اجتياز طريق الخير؟","answer":"تصوره دخولًا بشدة ومكابدة، كمن يلقي نفسه في أمر صعب؛ فتقرر أن الفضائل العظيمة تحتاج مجاهدة للنفس لا أمنية سهلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص359، تحت عنوان «دلالة مفردة ﴿اقتحم﴾»","url":""}]},{"id":"s90-24","number":24,"surah":90,"verses":[11],"references":[{"surah":90,"verses":[11]}],"verseLabel":"البلد: 11","question":"لماذا سُمّيت أعمال البر ﴿الْعَقَبَةَ﴾؟","answer":"شُبهت بالطريق الوعر الصاعد لأن بلوغها يشق على النفس ويحتاج قوة وصبرًا، لكنها الطريق الذي يفضي إلى النجاة والرفعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص361، تحت عنوان «بلاغة الاستعارة في مفردة ﴿العقبة﴾»","url":""}]},{"id":"s90-7","number":7,"surah":90,"verses":[12],"references":[{"surah":90,"verses":[12]}],"verseLabel":"البلد: 12","question":"ما أثر الاستفهامين في ﴿وَمَا أَدْرَاكَ مَا الْعَقَبَةُ﴾؟","answer":"الأول يشوق ويعظم شأن العقبة كأن حقيقتها أبعد من أن تدرك ابتداء، والثاني يطلب بيانها بعد هذا التهويل؛ فيتهيأ السامع لعظمة الجواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص362، تحت عنوان «نكتة الاستفهام بـ (ما) الأولى والثانية»","url":""}]},{"id":"s90-25","number":25,"surah":90,"verses":[12],"references":[{"surah":90,"verses":[12]}],"verseLabel":"البلد: 12","question":"لماذا سأل عن العقبة بعد الإخبار بأن الإنسان لم يقتحمها؟","answer":"ليوقظ فضول السامع إلى معرفة الطريق الذي قصّر فيه، ويحوّل التوبيخ إلى تشويق عملي لمعرفة أعمال النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص363–364، تحت عنوان «بلاغة الاستفهام عن العقبة بعد الإخبار عن نفي اقتحامها»","url":""}]},{"id":"s90-26","number":26,"surah":90,"verses":[12],"references":[{"surah":90,"verses":[12]}],"verseLabel":"البلد: 12","question":"كيف جعل قوله ﴿فَكُّ رَقَبَةٍ﴾ تحرير الإنسان أول صورة لاقتحام العقبة؟","answer":"لأنها جواب سؤال مقدر: ما اقتحام العقبة؟ فجاء الفصل ليبرز أول عمل من أعمالها ويجعله حاضرًا في الذهن كجواب حاسم.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص364، تحت عنوان «جمال الفصل في جملة ﴿فك رقبة﴾»","url":""}]},{"id":"s90-8","number":8,"surah":90,"verses":[13,14,15,16],"references":[{"surah":90,"verses":[13,14,15,16]}],"verseLabel":"البلد: 13–16","question":"لماذا قُدِّم فك الرقبة على إطعام المحتاج؟","answer":"لأن تحرير الإنسان من الرق أعظم أثرًا وأدوم نفعًا، وفيه إنقاذ لحريته كلها؛ ثم جاء الإطعام إنقاذًا من ألم الجوع العارض.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص366، تحت عنوان «نكتة تقديم فك الرقبة على الإطعام»","url":""}]},{"id":"s90-27","number":27,"surah":90,"verses":[13,14,15,16],"references":[{"surah":90,"verses":[13,14,15,16]}],"verseLabel":"البلد: 13–16","question":"ماذا تصور ﴿فِي﴾ في قوله ﴿إِطْعَامٌ فِي يَوْمٍ ذِي مَسْغَبَةٍ﴾؟","answer":"تصور الإطعام واقعًا في قلب زمن المجاعة ومحيطًا بظرفها الشديد؛ فيظهر أن البذل جاء حين يعز الطعام وتشتد الحاجة إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص368، تحت عنوان «بلاغة حرف ﴿في﴾»","url":""}]},{"id":"s90-28","number":28,"surah":90,"verses":[13,14,15,16],"references":[{"surah":90,"verses":[13,14,15,16]}],"verseLabel":"البلد: 13–16","question":"لماذا وُصف اليوم نفسه بأنه ﴿ذِي مَسْغَبَةٍ﴾؟","answer":"للمبالغة في شيوع الجوع حتى كأنه صار صفة لليوم كله، لا حالة فرد واحد؛ وبذلك تعظم قيمة من يطعم في ذلك الظرف.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص369، تحت عنوان «دلالة الوصف بـ﴿ذي مسغبة﴾»","url":""}]},{"id":"s90-9","number":9,"surah":90,"verses":[15,16],"references":[{"surah":90,"verses":[15,16]}],"verseLabel":"البلد: 15–16","question":"لماذا خُص اليتيم ﴿ذَا مَقْرَبَةٍ﴾ بالإطعام؟","answer":"لأن اجتماع اليتم والقرابة يضاعف حقه: حاجته تستدعي الرحمة، وقرابته تستدعي الصلة؛ فيكون إطعامه صدقة وصلة رحم معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص371–372، تحت عنوان «غرض التعبير بقوله: ﴿ذا مقربة﴾»","url":""}]},{"id":"s90-29","number":29,"surah":90,"verses":[15,16],"references":[{"surah":90,"verses":[15,16]}],"verseLabel":"البلد: 15–16","question":"ما الصورة التي ترسمها كناية ﴿ذَا مَتْرَبَةٍ﴾ للمسكين؟","answer":"ترسمه من شدة الفقر كأنه لصق بالتراب أو لا يملك ما يقيه منه؛ فهي كناية محسوسة عن غاية البؤس والحاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص373، تحت عنوان «بلاغة الكناية في قوله: ﴿ذا متربة﴾»","url":""}]},{"id":"s90-10","number":10,"surah":90,"verses":[17],"references":[{"surah":90,"verses":[17]}],"verseLabel":"البلد: 17","question":"ماذا تفيد ﴿ثُمَّ﴾ في قوله ﴿ثُمَّ كَانَ مِنَ الَّذِينَ آمَنُوا﴾ بعد أعمال البر؟","answer":"تفيد التراخي في الرتبة لا اشتراط تأخر الإيمان زمنًا؛ فالإيمان أساس قبول تلك الأعمال وأرفع منزلة، ولذلك رُقّي إليه بعد تعدادها.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص375–376، تحت عنوان «نوع ﴿ثم﴾ ودلالتها البيانية»","url":""}]},{"id":"s90-11","number":11,"surah":90,"verses":[17],"references":[{"surah":90,"verses":[17]}],"verseLabel":"البلد: 17","question":"لماذا لا يكتفي أهل الميمنة بصبر أنفسهم ورحمتها، بل ﴿تَوَاصَوْا﴾ بهما؟","answer":"لأن بناء المجتمع المؤمن لا يقوم بوصية من طرف واحد؛ بل يوصي بعضهم بعضًا، فيثبت الجميع على الخير ويتعاونون عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص380، تحت عنوان «بلاغة استعمال صيغة التفاعل»","url":""}]},{"id":"s90-30","number":30,"surah":90,"verses":[17],"references":[{"surah":90,"verses":[17]}],"verseLabel":"البلد: 17","question":"لماذا جُمعت المرحمة مع الصبر في صفات أصحاب الميمنة؟","answer":"لأن الصبر يضبط النفس أمام الشدة، والمرحمة تتجه إلى الخلق بالعطف والإحسان؛ فاجتمعت قوة الثبات ورقة القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص381، تحت عنوان «نكتة عطف (المرحمة) على (الصبر)»","url":""}]},{"id":"s90-31","number":31,"surah":90,"verses":[17],"references":[{"surah":90,"verses":[17]}],"verseLabel":"البلد: 17","question":"لماذا تكرر ﴿وَتَوَاصَوْا﴾ مع الصبر والمرحمة؟","answer":"لإبراز أن كل خصلة منهما مقصودة بتواص مستقل متجدد، فلا تُجعل الرحمة تابعة للصبر ولا يكتفى بإحداهما عن الأخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص381–382، تحت عنوان «دلالة تكرار فعل ﴿وتواصوا﴾»","url":""}]},{"id":"s90-12","number":12,"surah":90,"verses":[18,19,20],"references":[{"surah":90,"verses":[18,19,20]}],"verseLabel":"البلد: 18–20","question":"ما أثر الطباق بين ﴿الْمَيْمَنَةِ﴾ و﴿الْمَشْأَمَةِ﴾ في تصوير مصير الفريقين؟","answer":"يجمع الضدين في مقابلة حادة تستحضر كرامة أهل اليمين ويمنهم في مقابل شؤم أهل الشمال ومهانتهم، فيبرز افتراق المصيرين من لفظي الاسمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص397، تحت عنوان «بديع محسن الطباق بين الميمنة والمشأمة»","url":""}]},{"id":"s90-13","number":13,"surah":90,"verses":[20],"references":[{"surah":90,"verses":[20]}],"verseLabel":"البلد: 20","question":"ما الصورة في قوله ﴿عَلَيْهِمْ نَارٌ مُؤْصَدَةٌ﴾؟","answer":"صُورت النار كأنها غطاء أو بناء مطبق عليهم من كل جهة، فدل حرف ﴿على﴾ على الإحاطة والاستعلاء وشدة تمكن العذاب منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص400، تحت عنوان «بلاغة المجاز في الآية»","url":""}]},{"id":"s90-32","number":32,"surah":90,"verses":[20],"references":[{"surah":90,"verses":[20]}],"verseLabel":"البلد: 20","question":"ماذا تضيف ﴿مُؤْصَدَةٌ﴾ على معنى «مغلقة»؟","answer":"تدل على إغلاق محكم بأبواب عظيمة موصدة، فلا منفذ ولا مهرب؛ فهي أقوى تصويرًا للحبس واليأس من النجاة من مجرد الإغلاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص402، تحت عنوان «المؤصدة والمغلقة»","url":""}]},{"id":"s90-33","number":33,"surah":90,"verses":[11],"references":[{"surah":90,"verses":[11]}],"verseLabel":"البلد: 11","question":"ما دلالة «لا» في قوله: ﴿فَلَا اقْتَحَمَ الْعَقَبَةَ﴾ دون «ما اقتحم» أو «لم يقتحم»؟","answer":"جمع التعبير معانيَ مرادةً معًا: المضي أي لم يقتحمها، والاستقبال أي لا يقتحمها ما دام على حاله، والدعاء عليه بألا يقتحمها، والاستفهام المراد به التوبيخ والحض أي: أفلا اقتحم. ولو قال «ما اقتحم» أو «لم يقتحم» لم يُفد إلا الإخبار عن الماضي.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص266–270.","url":""}]},{"id":"s90-34","number":34,"surah":90,"verses":[18,19],"references":[{"surah":90,"verses":[18,19]}],"verseLabel":"البلد: 18، 19","question":"ما سر التعبير بـ«الميمنة» و«المشأمة» دون «أصحاب اليمين» و«أصحاب الشمال»؟","answer":"جمع اللفظان معانيَ مرادةً معًا: جهة اليمين والشمال، وإيتاء الصحائف باليمين والشمال، واليُمن والشؤم على أنفسهم وغيرهم، ولو قال «أصحاب اليمين» لأعطى معنى واحدًا. وفيه تناسب لفظي ببناء «مَفْعَلة» في العمل والوصف والجزاء: مسغبة، مقربة، متربة، مرحمة.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص276–278.","url":""}]},{"id":"s90-35","number":35,"surah":90,"verses":[19],"references":[{"surah":90,"verses":[19]}],"verseLabel":"البلد: 19","question":"ما سر المجيء بضمير الفصل في قوله: ﴿هُمْ أَصْحَابُ الْمَشْأَمَةِ﴾ دون آية المؤمنين؟","answer":"المؤمنون المذكورون من أصحاب الميمنة لا على جهة القصر، فمن أصحاب الميمنة من لم يتواصَ بصبر ولا مرحمة، أما الذين كفروا فهم أصحاب المشأمة حصرًا ما بقوا على كفرهم، فجيء بالضمير لإفادة الحصر. وفي «روح المعاني» نحو هذا.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص278.","url":""}]},{"id":"s90-36","number":36,"surah":90,"verses":[20],"references":[{"surah":90,"verses":[20]}],"verseLabel":"البلد: 20","question":"ما سر الاكتفاء بـ﴿مُّؤْصَدَةٌ﴾ هنا دون زيادة ﴿فِي عَمَدٍ مُّمَدَّدَةٍ﴾ كما في سورة الهمزة، وما سر ذكر جزاء الكافرين دون المؤمنين؟","answer":"توسّع في الهمزة في صفات المعذّب فتوسّع في عذابه، وذاك جمع المال واستوثق من حفظه فاستُوثق من غلق النار عليه، وهذا أهلك المال، ولم يُذكر في البلد إلا الكفر. واقتُصر على جزاء الكافرين لأن ذكر الجحيم هو المناسب لخلق الإنسان في كبد، وفي «روح المعاني» نحو هذا.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص280–283.","url":""}]},{"id":"s90-38","number":38,"surah":90,"verses":[1],"references":[{"surah":90,"verses":[1]}],"verseLabel":"البلد: 1","question":"ما سر عدم وصف البلد بـ«الأمين» هنا كما في سورة التين؟","answer":"لما جرى ذكر المكابدة في هذا البلد وما استُحلّ فيه من الحرمات وما أصاب الرسول صلى الله عليه وسلم من المشقة، لم يناسب ذلك ذكر الأمن، ولا يناسبه معنى إحلال القتال يوم الفتح. وجو السورة كله في المكابدة حتى إنه لم يذكر فيها جزاء المؤمنين.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص247–248.","url":""}]},{"id":"s90-39","number":39,"surah":90,"verses":[1,2],"references":[{"surah":90,"verses":[1,2]}],"verseLabel":"البلد: 1–2","question":"ما سر تكرير ﴿بِهَذَا الْبَلَدِ﴾ في الآيتين دون الاكتفاء بالضمير «وأنت حِلّ به»؟","answer":"العرب إذا عُنيت بلفظ كررته، والتكرار هنا لتعظيم بلد الله الحرام؛ أي: وأنت تلقى العنت والأذى بهذا البلد الذي يأمن فيه الخائف والوحش والطير، فأي انتهاك لحرمته! وفي «ملاك التأويل» نحو هذا، وفي «درة التنزيل» أن البلد الأول محرّم والثاني محلّل للنبي يوم الفتح.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص248–251.","url":""}]},{"id":"s90-37","number":37,"surah":90,"verses":[2],"references":[{"surah":90,"verses":[2]}],"verseLabel":"البلد: 2","question":"ما سر التعبير بـ«حِلّ» في قوله: ﴿وَأَنتَ حِلٌّ بِهَذَا الْبَلَدِ﴾ دون «حالّ» أو «مقيم»؟","answer":"جمعت «حِلّ» معانيَ مرادةً معًا: الحالّ المقيم يبلغ رسالة ربه، والمُستحَلّ الذي استُحلّت حرمته وأُريد قتله، والحلال الذي أُحلّ له القتال فيه يوم الفتح، والبريء المتحرج من آثامهم. فجمعت اسم الفاعل واسم المفعول والمصدر، ولو قال «حالّ» أو «مقيم» لقَصَر الكلام على معنى واحد، وهي في كل معانيها مرتبطة بـ﴿فِي كَبَدٍ﴾.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص243–247، 255–256.","url":""}]},{"id":"s90-40","number":40,"surah":90,"verses":[3],"references":[{"surah":90,"verses":[3]}],"verseLabel":"البلد: 3","question":"ما سر التعبير بـ«ما» دون «مَن» في قوله: ﴿وَوَالِدٍ وَمَا وَلَدَ﴾؟","answer":"«ما» أعمّ من «مَن»؛ تقع لذوات غير العاقل ولصفات العاقل، والمراد كل والد وولده من العقلاء وغيرهم. ولفظها يوحي بالسعة لانتهائه بحرف الإطلاق الألف، بخلاف «مَن» المنتهية بالنون الساكنة. والولادة مشقة ومكابدة، فارتباطها بجواب القسم ظاهر.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص251–253.","url":""}]},{"id":"s90-41","number":41,"surah":90,"verses":[10],"references":[{"surah":90,"verses":[10]}],"verseLabel":"البلد: 10","question":"ما سر اختيار «النجدين» في قوله: ﴿وَهَدَيْنَاهُ النَّجْدَيْنِ﴾ دون «السبيل» أو «الصراط»؟","answer":"النجد الطريق العالي المرتفع، وفي سلوكه مشقة لما فيه من صعود، فهو مناسب للمكابدة التي خُلق الإنسان فيها ولاقتحام العقبة. وذكر نجدين لا نجدًا واحدًا مناسب لجو الاجتماع في السورة.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص261، 263–264.","url":""}]},{"id":"s90-42","number":42,"surah":90,"verses":[11],"references":[{"surah":90,"verses":[11]}],"verseLabel":"البلد: 11","question":"ما سر التعبير بالاقتحام والعقبة في قوله: ﴿فَلَا اقْتَحَمَ الْعَقَبَةَ﴾؟","answer":"العقبة استعارة للأعمال الصالحة الشاقة، وذكرها بعد النجدين اختيار بديع لأن العقبة تقع في النجاد غالبًا، وهذا التوجيه منقول عن «روح المعاني». والاقتحام الدخول بشدة ومخاطرة، فلم يعبّر بالاجتياز ونحوه ليدل على وعورة العقبة، وكلاهما مناسب لـ﴿فِي كَبَدٍ﴾.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص264–266.","url":""}]},{"id":"s90-43","number":43,"surah":90,"verses":[13,16],"references":[{"surah":90,"verses":[13,16]}],"verseLabel":"البلد: 13، 16","question":"ما سر العطف بـ«أو» وتقديم فك الرقبة في قوله: ﴿فَكُّ رَقَبَةٍ أَوْ إِطْعَامٌ فِي يَوْمٍ ذِي مَسْغَبَةٍ﴾؟","answer":"لو عطف بالواو لأفاد أنه لا يقتحم العقبة إلا بها جميعًا، والمراد التنويع على سبيل الاجتماع أو الانفراد. وقُدّم فك الرقاب إشارة إلى عظم الحرية في الإسلام. والمسغبة الجوع العام لا الفردي، فللإطعام فيه شأن ليس له والطعام موفور.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص271–272.","url":""}]},{"id":"s90-44","number":44,"surah":90,"verses":[20],"references":[{"surah":90,"verses":[20]}],"verseLabel":"البلد: 20","question":"ما سر تقديم «عليهم» واختيار الهمز في قوله: ﴿عَلَيْهِمْ نَارٌ مُّؤْصَدَةٌ﴾؟","answer":"التقديم مناسب للفاصلة، وهو مع ذلك يفيد الحصر؛ فالنار مؤصدة على الكافرين لا يخرجون منها، أما عصاة المؤمنين فقد يخرجون. والهمزة حرف ثقيل شديد أثقل من الواو، فهي أنسب لثقل ذلك اليوم وشدته ولجو المكابدة في السورة.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص279–280.","url":""}]},{"id":"s91-1","number":1,"surah":91,"verses":[1,2,3,4,5,6,7],"references":[{"surah":91,"verses":[1,2,3,4,5,6,7]}],"verseLabel":"الشمس: 1–7","question":"لماذا أُخّر القسم بالنفس بعد الشمس والقمر والليل والنهار والسماء والأرض؟","answer":"تدرجت الأقسام من الآيات المحسوسة الكبرى في الكون إلى أعجب ما في الإنسان، وهو النفس، لتنتقل الدلالة من العالم الخارجي إلى موضع التكليف الداخلي. كما قرب تأخير النفس ذكرَها من الحديث عن فجورها وتقواها وتزكيتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص438، تحت عنوان «سر تأخير القسم بالنفس وما سواها»","url":""}]},{"id":"s91-13","number":13,"surah":91,"verses":[1,2,3,4,5,6,7],"references":[{"surah":91,"verses":[1,2,3,4,5,6,7]}],"verseLabel":"الشمس: 1–7","question":"كيف تمهّد الأقسام الكونية لجوابها ﴿قَدْ أَفْلَحَ مَنْ زَكَّاهَا﴾؟","answer":"تقيم الأقسام دلائل القدرة والحكمة والنظام في الكون، ثم تجعل إصلاح النفس ثمرة عملية للإيمان بمن أبدع ذلك كله. فمن أيقن بقدرة الخالق وتدبيره عرف أن فلاحه في تزكية نفسه، وأن إهمالها ليس خارجًا عن الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص443، تحت عنوان «سر التناسب بين الأقسام وجوابها»","url":""}]},{"id":"s91-2","number":2,"surah":91,"verses":[1,2],"references":[{"surah":91,"verses":[1,2]}],"verseLabel":"الشمس: 1–2","question":"لماذا أقسم بالشمس و﴿ضُحَاهَا﴾ لا بمجرد ضوئها؟","answer":"الضحى يستحضر وقت ارتفاع الشمس وكمال إشراقها وانتشار نورها وحرارتها، لا الضوء منفردًا. وفي هذا الوقت تظهر آثارها في الحياة والحركة والنماء، فيكون القسم أوسع دلالة على النعمة والقدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص420، تحت عنوان «سر التعبير بقوله: ﴿وضحاها﴾ دون (وضوئها)»","url":""}]},{"id":"s91-14","number":14,"surah":91,"verses":[1,2],"references":[{"surah":91,"verses":[1,2]}],"verseLabel":"الشمس: 1–2","question":"لماذا قُيّد القسم بالقمر بقوله ﴿إِذَا تَلَاهَا﴾؟","answer":"لأن تلو القمر للشمس يظهر في تعاقبهما وفي ظهوره بعدها، كما يلمح إلى أن نوره تابع لنورها. فيجمع القيد بين انتظام الحركة واتصال النور، ويجعل تعاقبهما آية مشاهدة على دقة التدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص422–423، تحت عنوان «سر تقييد القسم بالقمر بـ﴿إذا تلاها﴾»","url":""}]},{"id":"s91-3","number":3,"surah":91,"verses":[3,4],"references":[{"surah":91,"verses":[3,4]}],"verseLabel":"الشمس: 3–4","question":"كيف يصور قوله ﴿وَالنَّهَارِ إِذَا جَلَّاهَا﴾ انكشاف الشمس؟","answer":"تصور تجلية قوية واسعة تكشف الشمس وما تنيره كشفًا بالغًا، حتى يملأ ضياؤها الآفاق وتظهر به الأشياء. فالتضعيف لا يصف مجرد ظهور، بل حدثًا كونيًا عظيم الأثر والامتداد.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص425، تحت عنوان «نكتة صيغة التضعيف في ﴿جلاها﴾»","url":""}]},{"id":"s91-15","number":15,"surah":91,"verses":[3,4],"references":[{"surah":91,"verses":[3,4]}],"verseLabel":"الشمس: 3–4","question":"لماذا جاء غشيان الليل بالمضارع في ﴿إِذَا يَغْشَاهَا﴾؟","answer":"يستحضر المضارع تغطية الليل وهي تتجدد شيئًا فشيئًا، كأن الظلام يمتد أمام السامع الآن. وبذلك يقابل مشهدُ الستر المتكرر تجليةَ النهار، ويبرز انتظام الدورة اليومية.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص427–428، تحت عنوان «سر التعبير بالفعل ﴿يغشاها﴾ مضارعًا»","url":""}]},{"id":"s91-4","number":4,"surah":91,"verses":[5,6],"references":[{"surah":91,"verses":[5,6]}],"verseLabel":"الشمس: 5–6","question":"لماذا قيل ﴿وَالسَّمَاءِ وَمَا بَنَاهَا﴾ بـ«ما» لا «من»؟","answer":"تحتمل ﴿ما﴾ أن يكون القسم بفعل البناء المحكم، وأن يراد بها الذي بنى السماء على طريق التفخيم. فيجتمع تعظيم الخالق مع استحضار عظمة الصنعة، ويظل اللفظ أوسع من تعيين أحد الوجهين وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص431–432، تحت عنوان «سر التعبير بـ (ما)»","url":""}]},{"id":"s91-5","number":5,"surah":91,"verses":[7],"references":[{"surah":91,"verses":[7]}],"verseLabel":"الشمس: 7","question":"ما الذي تعنيه تسوية النفس في قوله ﴿وَنَفْسٍ وَمَا سَوَّاهَا﴾؟","answer":"تعني إحكام خلق النفس وتهيئة قواها الجسدية والعقلية والروحية في تناسق يمكنها من الفهم والاختيار. فالتسوية ليست مجرد إيجاد، بل تقويم دقيق منح الإنسان أدوات التكليف والمسؤولية.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص437–438، تحت عنوان «دلالة التعبير بالفعل ﴿سواها﴾ ماضيًا مضعفًا»","url":""}]},{"id":"s91-6","number":6,"surah":91,"verses":[8],"references":[{"surah":91,"verses":[8]}],"verseLabel":"الشمس: 8","question":"هل يعني ﴿فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَاهَا﴾ أن الإنسان مجبور على أحد الطريقين؟","answer":"لا؛ فالإلهام هنا تعريف النفس بطريقي الخير والشر وإيداع القدرة على تمييزهما، مع ما تبينه الرسل والشرائع. إنه إقامة للحجة وتمكين من الاختيار، لا أمر بالفجور ولا إجبار عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص439، تحت عنوان «بلاغة التعبير بالإلهام في قوله: ﴿فألهمها﴾»","url":""}]},{"id":"s91-16","number":16,"surah":91,"verses":[8],"references":[{"surah":91,"verses":[8]}],"verseLabel":"الشمس: 8","question":"ماذا تفيد إضافة الفجور والتقوى إلى النفس في ﴿فُجُورَهَا وَتَقْوَاهَا﴾؟","answer":"تربط الإضافة الطريقين باختيار النفس وكسبها؛ فقد عُرِّفت بهما ومُنحت القدرة على سلوك أحدهما. وبذلك تثبت مسؤوليتها عن الفجور أو التقوى، ولا يبقى لها أن تنسب اختيارها إلى الجبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص440، تحت عنوان «دلالة الإضافة في ﴿فجورها وتقواها﴾»","url":""}]},{"id":"s91-7","number":7,"surah":91,"verses":[9,10],"references":[{"surah":91,"verses":[9,10]}],"verseLabel":"الشمس: 9–10","question":"كيف تكون تزكية النفس طريقًا إلى الفلاح؟","answer":"تزكية النفس تجمع تطهيرها من الرذائل وتنميتها بالعلم النافع والعمل الصالح. فهي لا تقتصر على إزالة الشر، بل ترتقي بالإنسان في الإيمان والأخلاق؛ ولذلك جعلت الآية الفلاح ثمرة محققة لمن زكاها.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص445، تحت عنوان «بلاغة التعبير بفعل التزكية ماضيًا مضعفًا»","url":""}]},{"id":"s91-8","number":8,"surah":91,"verses":[10],"references":[{"surah":91,"verses":[10]}],"verseLabel":"الشمس: 10","question":"لماذا اختيرت ﴿دَسَّاهَا﴾؟","answer":"أصل التدسية الدس والإخفاء، واستعملت لتصوير النفس حين يذلها صاحبها بالقبائح ويحجب فضائلها بالرذائل. فالصورة تبين ما تحدثه المعصية من نقص النفس وإخماد خيرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص447، تحت عنوان «بلاغة التعبير بالتدسية»","url":""}]},{"id":"s91-9","number":9,"surah":91,"verses":[11,12],"references":[{"surah":91,"verses":[11,12]}],"verseLabel":"الشمس: 11–12","question":"ماذا يصور قوله ﴿إِذِ انْبَعَثَ أَشْقَاهَا﴾ في خروج عاقر الناقة؟","answer":"يصور خروجه مندفعًا بنشاط وحرص إلى الجريمة، كأنه وثب لها ولم يقع فيها عارضًا. ويكشف هذا الاندفاع أن الشقاء استولى عليه حتى سارع إلى تنفيذ ما أراده قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص461، تحت عنوان «بلاغة التعبير بالانبعاث مادة وصيغة»","url":""}]},{"id":"s91-17","number":17,"surah":91,"verses":[11,12],"references":[{"surah":91,"verses":[11,12]}],"verseLabel":"الشمس: 11–12","question":"لماذا أُسند عقر الناقة إلى ثمود كلها مع أن المباشر رجل واحد؟","answer":"لأن القوم رضوا بالفعل وحرضوا عليه ومكّنوا فاعله، فصار جرمه تعبيرًا عن موقف الجماعة لا تصرفًا معزولًا. وإسناد العقر إليهم جميعًا يقرر أن الرضا بالجريمة والمشاركة في صنع مناخها يحملان تبعتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص469–470، تحت عنوان «وجه إسناد العقر للجميع والفاعل واحد منهم»","url":""}]},{"id":"s91-10","number":10,"surah":91,"verses":[13],"references":[{"surah":91,"verses":[13]}],"verseLabel":"الشمس: 13","question":"لماذا حذّرهم صالح من ﴿سُقْيَاهَا﴾ لا من «شرابها»؟","answer":"السقيا هنا نصيب الناقة المقرر من الماء في يومها، لا مجرد شرب عابر. فاللفظ يحذرهم من الاعتداء على حق معلوم رتبه الله لها، ويبين أن منعها الماء كان نقضًا للعهد قبل أن يكون حرمانًا من الشراب.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص466، تحت عنوان «سر التعبير بـ﴿وسقياها﴾ دون شرابها»","url":""}]},{"id":"s91-11","number":11,"surah":91,"verses":[14],"references":[{"surah":91,"verses":[14]}],"verseLabel":"الشمس: 14","question":"ما الصورة التي يرسمها لفظ ﴿فَدَمْدَمَ عَلَيْهِمْ﴾؟","answer":"يرسم عذابًا مطبقًا شديدًا يحيط بالقوم ويستأصلهم، وتوحي أصوات اللفظ بتتابع القهر وثقله. فليس الهلاك إصابة عابرة، بل عقوبة ساحقة سوّت بينهم ولم تُبق منهم أحدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص470، تحت عنوان «سر التعبير بالدمدمة»","url":""}]},{"id":"s91-18","number":18,"surah":91,"verses":[14],"references":[{"surah":91,"verses":[14]}],"verseLabel":"الشمس: 14","question":"لماذا صُرّح بقوله ﴿بِذَنْبِهِمْ﴾ مع أن السياق دل على سبب هلاكهم؟","answer":"لإثبات أن العقوبة ثمرة جنايتهم لا ظلمًا وقع بهم، ولتثبيت صورة الذنب في ذهن السامع تحذيرًا من مثله. فالتصريح يربط الهلاك بالمسؤولية ربطًا لا يدع مجالًا لفصل النتيجة عن سببها.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص472، تحت عنوان «سر التصريح بالذنب مع دلالة الفاء عليه»","url":""}]},{"id":"s91-12","number":12,"surah":91,"verses":[15],"references":[{"surah":91,"verses":[15]}],"verseLabel":"الشمس: 15","question":"ماذا تكشف كناية ﴿وَلَا يَخَافُ عُقْبَاهَا﴾ عن قدرة الله؟","answer":"تكشف أن حكم الله نافذ لا يخشى معه تبعة إهلاك الظالمين، بخلاف البشر الذين يحسبون عواقب أفعالهم خوفًا من مقاومة أو مؤاخذة. فهي كناية عن كمال القدرة والعزة والعدل في إنزال العقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص475، تحت عنوان «بلاغة الكناية في قوله: ﴿ولا يخاف عقباها﴾»","url":""}]},{"id":"s91-19","number":19,"surah":91,"verses":[7,11],"references":[{"surah":91,"verses":[7,11]}],"verseLabel":"الشمس: 7، 11","question":"ما سر تقييد القسم بالنفس المكلفة في الشمس وتمثيل الجواب بثمود، مع إطلاقهما في سورة الليل؟","answer":"قيّد القسم في الشمس بـ﴿وَنَفْسٍ وَمَا سَوَّاهَا فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَاهَا﴾ أي بالنفوس العاقلة المكلفة، فكان الجواب ومثاله مقيدًا بأمر واحد هو قوم ثمود؛ وأطلق في الليل ﴿وَمَا خَلَقَ الذَّكَرَ وَالْأُنثَى﴾ فأطلق الجواب لكل من أعطى ومن بخل، فناسب بين القسم والجواب في الموضعين.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص127.","url":""}]},{"id":"s91-20","number":20,"surah":91,"verses":[7],"references":[{"surah":91,"verses":[7]}],"verseLabel":"الشمس: 7","question":"ما دلالة «ما» في قوله: ﴿وَنَفْسٍ وَمَا سَوَّاهَا﴾ والذي سوّاها هو الله؟","answer":"«ما» تكون لذوات غير العقلاء ولصفات العقلاء، كقوله: ﴿فَانكِحُوا مَا طَابَ لَكُم﴾، فالتعبير بها هنا وقع على صفة المسوّي سبحانه.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص195؛ على طريق التفسير البياني، ج1، ص203.","url":""}]},{"id":"s92-1","number":1,"surah":92,"verses":[1,2,3],"references":[{"surah":92,"verses":[1,2,3]}],"verseLabel":"الليل: 1–3","question":"ما أثر المقابلة بين الليل والنهار والذكر والأنثى في مطلع السورة؟","answer":"تجمع أزواجًا متقابلة في الكون والخلق، فتهيئ لتقابل سعي الناس ومصائرهم بين اليسر والعسر.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص497، تحت عنوان «براعة المقابلة في الآيتين»","url":""}]},{"id":"s92-15","number":15,"surah":92,"verses":[1,2,3],"references":[{"surah":92,"verses":[1,2,3]}],"verseLabel":"الليل: 1–3","question":"كيف لاءم جواب القسم ﴿إِنَّ سَعْيَكُمْ لَشَتَّى﴾ ما أقسم الله به؟","answer":"كما اختلف الليل والنهار والذكر والأنثى، اختلفت أعمال البشر وغاياتهم؛ فجاء الجواب من جنس التقابل في المقسم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص501، تحت عنوان «بلاغة ملاءمة جواب القسم للمقسم به»","url":""}]},{"id":"s92-16","number":16,"surah":92,"verses":[1,2,3],"references":[{"surah":92,"verses":[1,2,3]}],"verseLabel":"الليل: 1–3","question":"لماذا أجمل قوله ﴿إِنَّ سَعْيَكُمْ لَشَتَّى﴾ قبل تفصيل الفريقين؟","answer":"ليثبت القاعدة العامة أولًا ويشوق إلى معرفة وجوه الاختلاف، ثم يبين طريق العطاء والتقوى وطريق البخل والاستغناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص504، تحت عنوان «بلاغة الإجمال في ﴿إن سعيكم لشتى﴾»","url":""}]},{"id":"s92-2","number":2,"surah":92,"verses":[4],"references":[{"surah":92,"verses":[4]}],"verseLabel":"الليل: 4","question":"لماذا قيل ﴿لَشَتَّى﴾ لا «لمختلف»؟","answer":"لأن ﴿شتى﴾ تصور تفرقًا شديدًا في الأعمال والنيات والغايات، لا مجرد اختلاف يسير.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص504، تحت عنوان «سر التعبير بقوله: ﴿لشتى﴾ دون (لمختلف) ونحوه»","url":""}]},{"id":"s92-3","number":3,"surah":92,"verses":[5,6,7],"references":[{"surah":92,"verses":[5,6,7]}],"verseLabel":"الليل: 5–7","question":"لماذا قُدِّم الإعطاء على التقوى؟","answer":"لأنه برهان عملي ظاهر على مخالفة شح النفس، ثم ذكرت التقوى الأعم التي تضبط سائر العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص510، تحت عنوان «نكتة تقديم الإعطاء على الاتقاء»","url":""}]},{"id":"s92-17","number":17,"surah":92,"verses":[5,6,7],"references":[{"surah":92,"verses":[5,6,7]}],"verseLabel":"الليل: 5–7","question":"لماذا أُخّر التصديق بالحسنى مع أنه أصل العمل؟","answer":"لإبراز أثر الإيمان في السلوك أولًا، ثم ختم بذكر الأصل الذي يمنح الأعمال قيمتها وقبولها.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص511، تحت عنوان «سر تأخير التصديق بالحسنى عن الاتقاء»","url":""}]},{"id":"s92-18","number":18,"surah":92,"verses":[5,6,7],"references":[{"surah":92,"verses":[5,6,7]}],"verseLabel":"الليل: 5–7","question":"لماذا اقتصرت صفات الناجي على الإعطاء والتقوى والتصديق؟","answer":"لأنها تجمع عمل المال، وكف النفس والبدن، وعقيدة القلب؛ فهي أصول واسعة تنتظم وجوه الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص513، تحت عنوان «سر الاقتصار على هذه الطاعات دون غيرها»","url":""}]},{"id":"s92-4","number":4,"surah":92,"verses":[7],"references":[{"surah":92,"verses":[7]}],"verseLabel":"الليل: 7","question":"كيف ييسّر الله صاحب التقوى ﴿لِلْيُسْرَى﴾؟","answer":"يوفقه للطاعة حتى تسهل عليه ويستمر فيها، فيقوده عمل الخير إلى مزيد من الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص514، تحت عنوان «بالغة التعبير بالتيسير»","url":""}]},{"id":"s92-19","number":19,"surah":92,"verses":[7],"references":[{"surah":92,"verses":[7]}],"verseLabel":"الليل: 7","question":"ما الذي تشملـه ﴿الْيُسْرَى﴾؟","answer":"تشمل خصلة الطاعة والحال الميسرة وعاقبتها من النعيم والجنة؛ فالتيسير يجمع الطريق والغاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص515، تحت عنوان «دلالة تعريف اليسرى»","url":""}]},{"id":"s92-5","number":5,"surah":92,"verses":[8,9,10],"references":[{"surah":92,"verses":[8,9,10]}],"verseLabel":"الليل: 8–10","question":"كيف قابلت الآيات بين صفات الفريقين وبين اليسرى والعسرى؟","answer":"يقابل «أعطى» بـ«بخل»، و«اتقى» بـ«استغنى»، و«صدق» بـ«كذب»، و«اليسرى» بـ«العسرى». فالتناظر يوضح تضاد الأعمال ومآلاتها، وذكر الطريقين متقابلين يزيد كل واحد منهما بيانًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص530–531، تحت عنوان «بلاغة الطباق والمقابلة في الآيات»","url":""}]},{"id":"s92-6","number":6,"surah":92,"verses":[8],"references":[{"surah":92,"verses":[8]}],"verseLabel":"الليل: 8","question":"لماذا قيل ﴿وَاسْتَغْنَى﴾ لا «كان غنيًا»؟","answer":"لأن المذموم توهم الاستغناء عن هدى الله ورحمته والاكتفاء بالدنيا، لا مجرد امتلاك المال.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص523، تحت عنوان «بلاغة التعبير بالاستغناء»","url":""}]},{"id":"s92-20","number":20,"surah":92,"verses":[8],"references":[{"surah":92,"verses":[8]}],"verseLabel":"الليل: 8","question":"ما المفارقة بين ﴿وَاسْتَغْنَى﴾ و﴿وَاتَّقَى﴾؟","answer":"المتقي يشعر بافتقاره إلى الله فيراقبه، أما المستغني فيتوهم الاكتفاء فيعرض؛ فتقابل الكلمتان أصل الطريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص523–524، تحت عنوان «سر مقابلة ﴿واستغنى﴾ بـ﴿واتقى﴾»","url":""}]},{"id":"s92-7","number":7,"surah":92,"verses":[11],"references":[{"surah":92,"verses":[11]}],"verseLabel":"الليل: 11","question":"ماذا يفيد قوله ﴿وَمَا يُغْنِي عَنْهُ مَالُهُ﴾؟","answer":"يحتمل النفي أو الاستفهام التوبيخي، وفي الوجهين يسقط وهم اعتماد البخيل على المال.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص532، تحت عنوان «دلالة (ما) في ﴿وما يغني﴾»","url":""}]},{"id":"s92-21","number":21,"surah":92,"verses":[11],"references":[{"surah":92,"verses":[11]}],"verseLabel":"الليل: 11","question":"ماذا يصور قوله ﴿إِذَا تَرَدَّى﴾؟","answer":"يصور هلاكه أو سقوطه في النار من علو، فيقلب ما ظنه رفعة بالمال إلى سقوط لا ينقذه منه شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص533، تحت عنوان «بلاغة التعبير بالتردي»","url":""}]},{"id":"s92-22","number":22,"surah":92,"verses":[11],"references":[{"surah":92,"verses":[11]}],"verseLabel":"الليل: 11","question":"لماذا قُيّد عجز المال بوقت التردي؟","answer":"لأن ساعة الهلاك تكشف الحقيقة التي حجبها الغرور: المال نافع في حدود الدنيا ولا يدفع الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص534، تحت عنوان «براعة تقييد عدم الإغناء بوقت التردي»","url":""}]},{"id":"s92-8","number":8,"surah":92,"verses":[12,13],"references":[{"surah":92,"verses":[12,13]}],"verseLabel":"الليل: 12–13","question":"ماذا أفاد تقديم ﴿عَلَيْنَا﴾ في ﴿إِنَّ عَلَيْنَا لَلْهُدَى﴾؟","answer":"أفاد التزام الله تفضلًا ببيان طريق الهدى لعباده، فلا يتركهم بلا دلالة وحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص538، تحت عنوان «بلاغة تقديم ﴿علينا﴾»","url":""}]},{"id":"s92-23","number":23,"surah":92,"verses":[12,13],"references":[{"surah":92,"verses":[12,13]}],"verseLabel":"الليل: 12–13","question":"لماذا عُطف ﴿وَإِنَّ لَنَا لَلْآخِرَةَ وَالْأُولَى﴾ على بيان الهدى؟","answer":"ليصل بيان الطريق بملك الجزاء؛ فالذي هدى يملك الدنيا والآخرة ويحاسب على الاستجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص539، تحت عنوان «دلالة عطف ﴿وإن لنا للآخرة والأولى﴾»","url":""}]},{"id":"s92-9","number":9,"surah":92,"verses":[14],"references":[{"surah":92,"verses":[14]}],"verseLabel":"الليل: 14","question":"ماذا تصور كلمة ﴿تَلَظَّى﴾؟","answer":"تصور نارًا شديدة اللهب يتجدد اتقادها ويعلو لظاها، فيعظم وقع الإنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص546، تحت عنوان «بلاغة التعبير بمفردة التلظي»","url":""}]},{"id":"s92-10","number":10,"surah":92,"verses":[15,16],"references":[{"surah":92,"verses":[15,16]}],"verseLabel":"الليل: 15–16","question":"لماذا وُصف مستحق النار بأنه ﴿الْأَشْقَى﴾؟","answer":"للدلالة على بلوغه الغاية في الشقاء بسبب كفره وإعراضه، فهو أشد الناس ملازمة لأسباب العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص547–548، تحت عنوان «دلالة التعبير بصيغة أفعل التفضيل»","url":""}]},{"id":"s92-24","number":24,"surah":92,"verses":[15,16],"references":[{"surah":92,"verses":[15,16]}],"verseLabel":"الليل: 15–16","question":"كيف نفهم القصر في ﴿لَا يَصْلَاهَا إِلَّا الْأَشْقَى﴾؟","answer":"يتجه إلى الصلي الملازم والخلود، أو إلى نار مخصوصة بأهل هذا الوصف، فلا ينفي كل دخول عمن سواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص548، تحت عنوان «دلالة أسلوب القصر»","url":""}]},{"id":"s92-25","number":25,"surah":92,"verses":[15,16],"references":[{"surah":92,"verses":[15,16]}],"verseLabel":"الليل: 15–16","question":"لماذا جُمِع بين ﴿كَذَّبَ﴾ و﴿تَوَلَّى﴾؟","answer":"ليجمع فساد الاعتقاد وفساد العمل: أنكر الحق بقلبه ولسانه ثم أعرض عن الاستجابة له.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص550، تحت عنوان «توجيه تخصيص الوصفين بالذكر»","url":""}]},{"id":"s92-11","number":11,"surah":92,"verses":[17,18],"references":[{"surah":92,"verses":[17,18]}],"verseLabel":"الليل: 17–18","question":"لماذا قيل إن الأتقى يؤتي ماله ﴿يَتَزَكَّى﴾؟","answer":"لأن عطاؤه يقصد تطهير النفس من الشح والرياء وتنمية المال والأجر بالخير، لا مجرد التخلص من ذنب.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص558، تحت عنوان «بلاغة التعبير بمفردة التزكية دون التطهر»","url":""}]},{"id":"s92-12","number":12,"surah":92,"verses":[19,20],"references":[{"surah":92,"verses":[19,20]}],"verseLabel":"الليل: 19–20","question":"لماذا نُفي أن تكون عند المنفق نعمة لأحد تجزى؟","answer":"للاحتراس من فهم عطائه مكافأةً لمصلحة سابقة؛ فهو لا يشتري ولاءً ولا يرد دينًا بشريًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص560، تحت عنوان «بلاغة التكميل والاحتراس»","url":""}]},{"id":"s92-26","number":26,"surah":92,"verses":[19,20],"references":[{"surah":92,"verses":[19,20]}],"verseLabel":"الليل: 19–20","question":"كيف حصر قوله ﴿إِلَّا ابْتِغَاءَ وَجْهِ رَبِّهِ الْأَعْلَى﴾ غاية الإنفاق؟","answer":"استثنى طلب رضا الله وحده من كل غرض، فنفى الرياء وتبادل المنافع وأثبت الإخلاص الخالص.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص563، تحت عنوان «دلالة الاستثناء ونوعه»","url":""}]},{"id":"s92-13","number":13,"surah":92,"verses":[20],"references":[{"surah":92,"verses":[20]}],"verseLabel":"الليل: 20","question":"لماذا قال ﴿وَجْهِ رَبِّهِ﴾؟","answer":"لأن عنوان الربوبية يذكره بإحسان الله وتربيته، فيكون الإنفاق شكرًا وطلبًا لرضاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص564، تحت عنوان «سر إيثار عنوان الربوبية»","url":""}]},{"id":"s92-27","number":27,"surah":92,"verses":[20],"references":[{"surah":92,"verses":[20]}],"verseLabel":"الليل: 20","question":"ماذا يضيف وصف الرب بأنه ﴿الْأَعْلَى﴾؟","answer":"يبيّن عظمة من يقصده المتصدق، فيصغر أمام رضاه ثناء الناس ومكافآتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص564، تحت عنوان «بلاغة التخصيص بوصف ﴿الأعلى﴾»","url":""}]},{"id":"s92-14","number":14,"surah":92,"verses":[21],"references":[{"surah":92,"verses":[21]}],"verseLabel":"الليل: 21","question":"لماذا قيل ﴿وَلَسَوْفَ يَرْضَى﴾ بـ«سوف»؟","answer":"لتأكيد وعد آتٍ عظيم يمتد أثره، وفيها تشويق إلى جزاء كامل يبلغه الله إياه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص565، تحت عنوان «دلالة استعمال (سوف) دون السين»","url":""}]},{"id":"s92-28","number":28,"surah":92,"verses":[21],"references":[{"surah":92,"verses":[21]}],"verseLabel":"الليل: 21","question":"ما سعة الرضا الموعود في قوله ﴿وَلَسَوْفَ يَرْضَى﴾؟","answer":"ليفتح معنى العطاء ولا يحصره في نعيم معين، فيشمل كل ما يحقق الرضا ويعظم الوعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص566، تحت عنوان «نكتة حذف متعلق فعل ﴿يرضى﴾»","url":""}]},{"id":"s92-29","number":29,"surah":92,"verses":[4],"references":[{"surah":92,"verses":[4]}],"verseLabel":"الليل: 4","question":"ما سر القسم والتوكيد وإضافة السعي إلى المخاطبين في قوله: ﴿إِنَّ سَعْيَكُمْ لَشَتَّى﴾ مع أن اختلاف السعي أمر مشاهد؟","answer":"المُقسَم عليه ليس السعي المشاهد في التجارة والزراعة، بل ما بيّنه التفصيل بعده من عاقبة من أعطى واتقى ومن بخل واستغنى، وهذا ينكره أكثر الناس فاستحق القسم والتوكيد. وأضاف السعي إلى المكلفين ولم يقل «إن السعي» لئلا يدخل سعي غير المكلفين من الحيوان.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص126.","url":""}]},{"id":"s92-30","number":30,"surah":92,"verses":[5,6],"references":[{"surah":92,"verses":[5,6]}],"verseLabel":"الليل: 5، 6","question":"ما سر ترتيب الصفات في قوله: ﴿فَأَمَّا مَنْ أَعْطَى وَاتَّقَى وَصَدَّقَ بِالْحُسْنَى﴾؟","answer":"قدّم العطاء لأن جو السورة شائع فيه المال وإعطاؤه أو البخل به، ثم ترقّى من المفضول إلى الأفضل ومن الأخص إلى الأعمّ؛ فكل معطٍ في سبيل الله متقٍ، وكل متقٍ مصدّق بالحسنى. ورتّبها كذلك بحسب قربها من السعي؛ فالعطاء أظهر السعي، والاتقاء فيه سعي وترك، والتصديق اعتقاد قلبي.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص129–131.","url":""}]},{"id":"s92-31","number":31,"surah":92,"verses":[5,10],"references":[{"surah":92,"verses":[5,10]}],"verseLabel":"الليل: 5، 10","question":"ما سر إطلاق «أعطى» و«اتقى» وحذف موصوف «الحسنى» و«اليسرى» و«العسرى»؟","answer":"أطلق العطاء فلم يذكر معطًى ولا نوعًا ولا مقدارًا، والراجح أنه إعطاء المال لمقابلته بالبخل وذكر المال بعده، وأطلق الاتقاء ليشمل كل ما ينبغي اتقاؤه. والحسنى واليسرى والعسرى صفات حُذف موصوفها لقصد الإطلاق، فالتيسير لليسرى عام في كل خير في الدنيا والآخرة.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص127–129، 131، 134.","url":""}]},{"id":"s92-32","number":32,"surah":92,"verses":[14],"references":[{"surah":92,"verses":[14]}],"verseLabel":"الليل: 14","question":"ما سر التعبير بالماضي وترك التوكيد وتنكير النار في قوله: ﴿فَأَنذَرْتُكُمْ نَارًا تَلَظَّى﴾؟","answer":"عبّر بالماضي لأنه أنذرهم بأمر واحد أخبرهم به فتمّ، بخلاف ﴿أُنذِرُكُم بِالْوَحْيِ﴾ لأن الوحي مستمر. ولم يؤكده كما أكده في النبأ لأن الإنذار في الليل لم يرد إلا هنا، وفي النبأ تكرر في أولها ووسطها وآخرها. ونكّر النار ليعلمنا أن النار بكل أقسامها تستحق الإنذار، ولو عرّفها لظُنّ أن التحذير واقع على نار بعينها.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص142–144.","url":""}]},{"id":"s92-33","number":33,"surah":92,"verses":[1,2],"references":[{"surah":92,"verses":[1,2]}],"verseLabel":"الليل: 1–2","question":"ما سر مجيء المضارع مع الليل والماضي مع النهار في قوله: ﴿وَاللَّيْلِ إِذَا يَغْشَى وَالنَّهَارِ إِذَا تَجَلَّى﴾؟","answer":"الليل يغشى شيئًا بعد شيء، أما النهار فإذا طلعت الشمس ظهر وتجلّى وهلةً واحدة. وأطلق الغشيان والتجلي هنا فلم يذكر المفعول كما ذكره في الشمس ﴿يَغْشَاهَا﴾ و﴿جَلَّاهَا﴾، لأن العموم خطّ شائع في سورة الليل.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص124، 126–127، 147.","url":""}]},{"id":"s92-34","number":34,"surah":92,"verses":[3],"references":[{"surah":92,"verses":[3]}],"verseLabel":"الليل: 3","question":"ما سر الترتيب في القسم، وما سر عدم ذكر «الزوجين» في قوله: ﴿وَمَا خَلَقَ الذَّكَرَ وَالْأُنثَى﴾؟","answer":"بدأ بالليل لأنه أسبق ثم النهار، ثم خلق الذكر والأنثى وهو متأخر عنهما، وقدّم الذكر لأن آدم أسبق من حواء. ولم يذكر «الزوجين» كما في القيامة والنجم لأنه أقسم هنا وأوجز، ولأن من معاني الزوج النظير والمؤتلف، والمراد هنا الافتراق والتباعد بدليل ﴿إِنَّ سَعْيَكُمْ لَشَتَّى﴾.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص125.","url":""}]},{"id":"s92-35","number":35,"surah":92,"verses":[11],"references":[{"surah":92,"verses":[11]}],"verseLabel":"الليل: 11","question":"ما دلالة «ما» و«تردّى» في قوله: ﴿وَمَا يُغْنِي عَنْهُ مَالُهُ إِذَا تَرَدَّى﴾؟","answer":"يجوز أن تكون «ما» استفهامية أي: أيّ شيء يغني عنه ماله، وأن تكون نافية، والمعنيان مرادان. و«تردّى» تحتمل الهلاك والسقوط في القبر والسقوط في جهنم، وكلها مرادة، وهذا من التوسع في المعنى.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص134.","url":""}]},{"id":"s92-36","number":36,"surah":92,"verses":[13],"references":[{"surah":92,"verses":[13]}],"verseLabel":"الليل: 13","question":"ما سر توكيد قوله: ﴿وَإِنَّ لَنَا لَلْآخِرَةَ وَالْأُولَى﴾ مع مجيئها غير مؤكدة في النجم، وما سر تقديم الآخرة؟","answer":"وردت في الليل في سياق امتلاك الأموال والتصرف فيها من عطاء وبخل واستغناء، ويشيع فيها ذكر الآخرة، فناسب توكيد الملك بخلاف آية النجم. وقدّم الآخرة لتقدّم طالبها وهو من أعطى واتقى، وأخّر الأولى لتأخّر طالبها وهو من بخل واستغنى.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص138–139.","url":""}]},{"id":"s92-37","number":37,"surah":92,"verses":[15,17],"references":[{"surah":92,"verses":[15,17]}],"verseLabel":"الليل: 15، 17","question":"ما سر القصر في ﴿لَا يَصْلَاهَا إِلَّا الْأَشْقَى﴾ دون ﴿وَسَيُجَنَّبُهَا الْأَتْقَى﴾، وما سر بناء «سيُجنّبها» للمجهول؟","answer":"لم يقل «ولا يجنّبها إلا الأتقى» لأن غير الأتقى قد يُجنّبها أو يردها ورودًا خفيفًا، أما الأتقى فيُجنّبها تجنيبًا كاملًا. وبناه للمجهول لأن تجنّب النار ليس إليه بل إلى ربه، ولمناسبة جو الإطلاق في السورة. والتجنيب مباعدة فلا يذوقها، بخلاف النجاة التي قد تكون بعد الوقوع.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص144–146.","url":""}]},{"id":"s92-38","number":38,"surah":92,"verses":[18],"references":[{"surah":92,"verses":[18]}],"verseLabel":"الليل: 18","question":"ما سر إضافة المال إليه في قوله: ﴿الَّذِي يُؤْتِي مَالَهُ يَتَزَكَّى﴾؟","answer":"لم يقل «يؤتي المال» ليدل على أنه يؤتي ثمرة كدّه هو، وأنه يعطي ماله كله، فهو أعلى من «أعطى» الذي يحتمل القليل والكثير، كما أن «الأتقى» أعلى من «اتقى»، فكان جزاؤه أعلى: التجنيب والرضا.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص144.","url":""}]},{"id":"s92-39","number":39,"surah":92,"verses":[21],"references":[{"surah":92,"verses":[21]}],"verseLabel":"الليل: 21","question":"ما سر إطلاق الفاعل في ﴿وَلَسَوْفَ يَرْضَى﴾ بما يحتمل رضا الأتقى بثوابه ورضا ربّه عنه؟","answer":"يحتمل أن الأتقى سيرضى بثوابه في الآخرة، ويحتمل أن ربه سيرضى عنه، والمعنيان مرادان معًا، وهو من خط العموم والإطلاق الشائع في السورة.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص144–145، 148.","url":""}]},{"id":"s93-1","number":1,"surah":93,"verses":[1,2],"references":[{"surah":93,"verses":[1,2]}],"verseLabel":"الضحى: 1–2","question":"لماذا أقسم الله بالضحى في سورة تسلية النبي؟","answer":"لأن الضحى وقت انتشار النور والحركة، فيناسب إشراق الوحي بعد فتوره وبشارة انكشاف الوحشة. فالمشهد الكوني يمهد لعودة الأنس والرجاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص578–579، تحت عنوان «مناسبة القسم بالضحى لموضوع السورة»","url":""}]},{"id":"s93-14","number":14,"surah":93,"verses":[1,2],"references":[{"surah":93,"verses":[1,2]}],"verseLabel":"الضحى: 1–2","question":"لماذا قُرن الضحى بالليل إذا سجى؟","answer":"لأن سكون الليل بعد إشراق النهار لا يعني انقطاع النور إلى الأبد، بل هو طور يعقبه الضياء؛ فكذلك فتور الوحي سكون مؤقت لا هجر.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص580، تحت عنوان «نكتة القسم بالليل»","url":""}]},{"id":"s93-15","number":15,"surah":93,"verses":[1,2],"references":[{"surah":93,"verses":[1,2]}],"verseLabel":"الضحى: 1–2","question":"كيف يطابق ﴿مَا وَدَّعَكَ رَبُّكَ﴾ القسم بالضحى والليل؟","answer":"كما يتعاقب النور والسكون دون أن يلغي أحدهما الآخر، يتعاقب نزول الوحي وفترته دون أن يكون ذلك توديعًا أو بغضًا. فالقسم يحول الكون إلى دليل تسلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص582–583، تحت عنوان «مناسبة جواب القسم للقسم»","url":""}]},{"id":"s93-2","number":2,"surah":93,"verses":[2],"references":[{"surah":93,"verses":[2]}],"verseLabel":"الضحى: 2","question":"ماذا يصور اختيار ﴿سَجَى﴾ لوصف الليل؟","answer":"يصور الليل إذا سكن واشتد ستره واطمأن ما فيه، كأنه كائن هادئ يحتضن العالم. فاللفظ يحمل السكون والامتداد لا مجرد حلول الظلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص582، تحت عنوان «دلالة التعبير بمفردة ﴿سجى﴾»","url":""}]},{"id":"s93-3","number":3,"surah":93,"verses":[3],"references":[{"surah":93,"verses":[3]}],"verseLabel":"الضحى: 3","question":"لماذا قيل ﴿مَا وَدَّعَكَ رَبُّكَ﴾ لا «ما تركك»؟","answer":"لأن التوديع يفترض مفارقة من كان قريبًا مصاحبًا، فنفيه أبلغ في تثبيت دوام العناية؛ لم تقع مفارقة أصلًا حتى يكون فتور الوحي وداعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص583، تحت عنوان «بلاغة الاستعارة ودلالتها»","url":""}]},{"id":"s93-16","number":16,"surah":93,"verses":[3],"references":[{"surah":93,"verses":[3]}],"verseLabel":"الضحى: 3","question":"لماذا قيل ﴿وَمَا قَلَى﴾ دون «وما أبغض»؟","answer":"لأن القلى بغض شديد يفضي إلى الهجر، فنفيه يزيل أقصى ما خافه القلب. كما جاء اللفظ موجزًا لطيفًا بلا إعادة ضمير الخطاب في مقام المواساة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص584، تحت عنوان «بلاغة التعبير بمفردة القلى دون البغض»","url":""}]},{"id":"s93-4","number":4,"surah":93,"verses":[3],"references":[{"surah":93,"verses":[3]}],"verseLabel":"الضحى: 3","question":"لماذا حُذف مفعول ﴿قَلَى﴾؟","answer":"حذف المفعول لدلالة ما سبق عليه، وفي ذلك إيجاز ومراعاة للفاصلة. وتذكر الموسوعة أيضًا أن تركه يبالغ في نفي وقوع القلى، فيتوجه النفي إلى الحدث نفسه دون تقييده بالمفعول المذكور.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص585، تحت عنوان «نكتة حذف مفعول فعل ﴿قلى﴾»","url":""}]},{"id":"s93-5","number":5,"surah":93,"verses":[4],"references":[{"surah":93,"verses":[4]}],"verseLabel":"الضحى: 4","question":"ما المقابلة التي يصنعها قوله ﴿الْآخِرَةُ خَيْرٌ لَكَ مِنَ الْأُولَى﴾ بين مرحلتي حياة النبي ﷺ؟","answer":"ليتسع المعنى لكل حال متأخرة للنبي قياسًا بما قبلها، مع دخول الآخرة والدنيا أولًا؛ فكل ما يستقبله من نصر وكمال وثواب خير مما مضى.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص588–589، تحت عنوان «بلاغة المجاز بحذف الموصوف»","url":""}]},{"id":"s93-6","number":6,"surah":93,"verses":[5],"references":[{"surah":93,"verses":[5]}],"verseLabel":"الضحى: 5","question":"ماذا يحقق الجمع بين اللام و﴿سَوْفَ﴾ في وعد العطاء؟","answer":"يجمع توكيد وقوع الوعد مع فتح أفق المستقبل؛ فالعطاء آت يقينًا وإن امتد زمن تحققه، وفي ذلك تثبيت للقلب وصبر على الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص591، تحت عنوان «بلاغة الجمع بين اللام و(سوف)»","url":""}]},{"id":"s93-17","number":17,"surah":93,"verses":[5],"references":[{"surah":93,"verses":[5]}],"verseLabel":"الضحى: 5","question":"ما الذي يوحي به ترك عطاء الله لنبيه مفتوحًا في قوله ﴿وَلَسَوْفَ يُعْطِيكَ رَبُّكَ﴾؟","answer":"ليعم كل عطاء يرضيه في الدنيا والآخرة من النصر والشفاعة والكرامة، فلا يحد الوعد بنعمة واحدة ولا بمقدار ضيق.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص592، تحت عنوان «نكتة حذف المفعول الثاني»","url":""}]},{"id":"s93-18","number":18,"surah":93,"verses":[5],"references":[{"surah":93,"verses":[5]}],"verseLabel":"الضحى: 5","question":"لماذا تكرر وصف ﴿رَبُّكَ﴾ في سياق التسلية؟","answer":"ليجدد معنى الرعاية والتربية والقرب؛ فالذي لم يودعه هو نفسه الذي يتولى مستقبله ويعطيه حتى يرضى.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص593، تحت عنوان «نكتة تكرار عنوان الربوبية»","url":""}]},{"id":"s93-19","number":19,"surah":93,"verses":[5],"references":[{"surah":93,"verses":[5]}],"verseLabel":"الضحى: 5","question":"كيف يصل العطاء الإلهي بالنهاية المطمئنة ﴿فَتَرْضَى﴾؟","answer":"تفيد أن الرضا ثمرة مباشرة للعطاء الإلهي، وأن العطاء سيكون بالغًا الغاية التي تسكن بها نفس النبي وتطمئن.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص593، تحت عنوان «نوع الفاء ودلالتها»","url":""}]},{"id":"s93-7","number":7,"surah":93,"verses":[6,7,8],"references":[{"surah":93,"verses":[6,7,8]}],"verseLabel":"الضحى: 6–8","question":"لماذا انتقلت السورة من وعد المستقبل إلى تذكير النبي بنعم الماضي؟","answer":"لتجعل التجربة السابقة دليلًا على الوعد الآتي: من رعاه يتيمًا وهداه وأغناه لن يتركه فيما يستقبل. فالماضي شاهد عملي على دوام العناية.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص597–598، تحت عنوان «علة فصل ﴿ألم يجدك يتيمًا﴾ عما قبله»","url":""}]},{"id":"s93-20","number":20,"surah":93,"verses":[6,7,8],"references":[{"surah":93,"verses":[6,7,8]}],"verseLabel":"الضحى: 6–8","question":"ماذا يضيف التعبير بأن الله ﴿فَآوَى﴾ النبي يتيمًا؟","answer":"يصور نقله من فقد المأوى والحماية إلى كنف آمن جمع له الرعاية والمحبة، فالإيواء أوسع من مجرد إيجاد مسكن.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص599، تحت عنوان «بلاغة التعبير بمفردة الإيواء»","url":""}]},{"id":"s93-8","number":8,"surah":93,"verses":[7],"references":[{"surah":93,"verses":[7]}],"verseLabel":"الضحى: 7","question":"كيف نفهم وصف النبي قبل الوحي بأنه ﴿ضَالًّا﴾؟","answer":"ليس ضلال كفر أو انحراف، بل عدم معرفة تفاصيل الوحي والطريق المرسوم للرسالة مع طلب الحق؛ فهداه الله بالنبوة والكتاب إلى ما لم يكن يعلمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص600–601، تحت عنوان «دلالة التعبير بمفردة الضلال»","url":""}]},{"id":"s93-9","number":9,"surah":93,"verses":[8],"references":[{"surah":93,"verses":[8]}],"verseLabel":"الضحى: 8","question":"ما نوع الغنى في ﴿وَوَجَدَكَ عَائِلًا فَأَغْنَى﴾؟","answer":"هو رفع حاجة النبي بما يسره الله من الكفاية والقناعة وأسباب الرزق، لا وعدًا بالترف المجرد. فالإغناء يحرره من ذل السؤال ويهيئه لمهمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص602–603، تحت عنوان «بلاغة التعبير بمفردة الإغناء»","url":""}]},{"id":"s93-10","number":10,"surah":93,"verses":[9,10,11],"references":[{"surah":93,"verses":[9,10,11]}],"verseLabel":"الضحى: 9–11","question":"كيف قابلت الأوامر النعم الثلاث؟","answer":"على تفسير السائل بطالب العلم يكون اللف والنشر مرتبًا: الإيواء يقابله النهي عن قهر اليتيم، والهداية يقابلها عدم نهر طالب العلم، والإغناء يقابله التحديث بالنعمة شكرًا. وعلى تفسير السائل بطالب المال تختلف صلة الطرفين الأخيرين، فيقابل الإغناءَ عدمُ نهره، والهدايةَ التحديثُ بنعمة الدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص611–612، تحت عنوان «بلاغة بديع اللف والنشر»","url":""}]},{"id":"s93-11","number":11,"surah":93,"verses":[9],"references":[{"surah":93,"verses":[9]}],"verseLabel":"الضحى: 9","question":"لماذا اختير النهي ﴿فَلَا تَقْهَرْ﴾ في حق اليتيم؟","answer":"لأن القهر يجمع الغلبة والإذلال وسلب الحق ممن لا ناصر له، فالنهي لا يمنع الضرب وحده بل كل استضعاف يكسر نفس اليتيم أو يأكل حقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص608، تحت عنوان «بلاغة اختيار مفردة القهر»","url":""}]},{"id":"s93-12","number":12,"surah":93,"verses":[10],"references":[{"surah":93,"verses":[10]}],"verseLabel":"الضحى: 10","question":"من يشمله لفظ ﴿السَّائِلَ﴾ في سورة الضحى؟","answer":"يشمل طالب المال وطالب العلم والهداية وكل من أقبل يسأل حاجة مشروعة؛ فالتعريف للجنس يوسع الوصية ولا يحصرها في فقير واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص608، تحت عنوان «نكتة تعريف لفظ ﴿السائل﴾»","url":""}]},{"id":"s93-21","number":21,"surah":93,"verses":[10],"references":[{"surah":93,"verses":[10]}],"verseLabel":"الضحى: 10","question":"ماذا يطلب النهي ﴿فَلَا تَنْهَرْ﴾ وراء مجرد إعطاء السائل؟","answer":"يطلب صون كرامته بالرفق والجواب الحسن، حتى إن تعذر العطاء؛ فلا يجتمع رد الحاجة مع زجر يؤذي النفس ويذلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص609، تحت عنوان «دلالة النهي في ﴿فلا تنهر﴾»","url":""}]},{"id":"s93-13","number":13,"surah":93,"verses":[11],"references":[{"surah":93,"verses":[11]}],"verseLabel":"الضحى: 11","question":"ماذا يضبط قول الله ﴿بِنِعْمَةِ رَبِّكَ﴾ عند الحديث عن النعم؟","answer":"ينسب النعمة إلى ربها فيمنع المباهاة والاستقلال بها؛ فالمتحدث شاهد فضل الله لا معجب بنفسه، ويربط العطاء بالشكر والعبودية.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص610، تحت عنوان «نوع الإضافة ودلالتها»","url":""}]},{"id":"s93-22","number":22,"surah":93,"verses":[11],"references":[{"surah":93,"verses":[11]}],"verseLabel":"الضحى: 11","question":"ما الغرض من الأمر ﴿فَحَدِّثْ﴾ بالنعمة؟","answer":"الغرض شكر المنعم وإظهار أثر فضله وبعث الرجاء في الناس، لا طلب السمعة؛ فيكون الكلام عبادة حين تصح النية ويؤمن الحسد والرياء.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص610، تحت عنوان «غرض الأمر ودلالته»","url":""}]},{"id":"s93-23","number":23,"surah":93,"verses":[11],"references":[{"surah":93,"verses":[11]}],"verseLabel":"الضحى: 11","question":"لماذا اختير ﴿فَحَدِّثْ﴾ لا «فأخبر»؟","answer":"لأن التحديث يدل على تكرار ذكر النعمة وتفصيل أثرها بما يحيي الشكر وينفع السامع، أما الإخبار فقد يقع مرة بلا استحضار ولا امتنان.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص610–611، تحت عنوان «نكتة اختيار التحديث دون الإخبار»","url":""}]},{"id":"s93-24","number":24,"surah":93,"verses":[6,8],"references":[{"surah":93,"verses":[6,8]}],"verseLabel":"الضحى: 6، 8","question":"ما سر ترتيب النعم الثلاث: الإيواء ثم الهداية ثم الغنى؟","answer":"هو الترتيب الطبيعي في الحياة؛ فاليتيم من هو دون البلوغ، فإذا بلغ احتاج إلى الهدى لأن البلوغ مناط التكليف، وجمع المال ينبغي أن يكون مبنيًّا على الهداية الربانية. وكل نعمة منها مرتبطة بالقسم؛ فاليتم والضلال والعيلة ليل وظلمة، والإيواء والهدى والغنى نور.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص117–118.","url":""}]},{"id":"s93-25","number":25,"surah":93,"verses":[6,8],"references":[{"surah":93,"verses":[6,8]}],"verseLabel":"الضحى: 6، 8","question":"ما سر حذف المفعول في «فآوى» و«فهدى» و«فأغنى»؟","answer":"حُذف لظهور المراد ورعاية الفاصلة وسعة الكرم معًا؛ فلو قال «فآواك» لكان الإيواء منحصرًا به، والمراد أنه آواه وآوى به ولأجله خلقًا كثيرًا، وهداه وهدى به، وأغناه وأغنى به. والقول بسعة الكرم في «روح المعاني» نحوه.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص117–118.","url":""}]},{"id":"s93-26","number":26,"surah":93,"verses":[9,11],"references":[{"surah":93,"verses":[9,11]}],"verseLabel":"الضحى: 9، 11","question":"ما سر ترتيب الوصايا الثلاث مع أنها لا تقابل النعم على النسق نفسه؟","answer":"هو الترتيب الأمثل؛ فاليتيم أولًا بإزاء اليتم، والسائل يشمل سائل العلم فيقابل الهداية، وسائل المال فيقابل الغنى، ثم التحديث بالنعمة بعدها لأن التحديث يكون بعد وقوعها، ولأن الداعية يتحلى بالخلق الحسن قبل أن يتصدى للدعوة. وفي «البحر المحيط» و«روح المعاني» توجيهات لهذا الترتيب.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص120–122.","url":""}]},{"id":"s93-27","number":27,"surah":93,"verses":[1,2],"references":[{"surah":93,"verses":[1,2]}],"verseLabel":"الضحى: 1–2","question":"ما سر تقديم الضحى على الليل، والتعبير بـ«سجى» دون «يغشى» أو «يسر» في قوله: ﴿وَالضُّحَى وَاللَّيْلِ إِذَا سَجَى﴾؟","answer":"الضحى يمثل نور الوحي، والليل إذا سجى يمثل انقطاعه، فقُدّم الضحى وهو ما سبق من نور الوحي على مدة انقطاعه. ومعنى «سجى» سكن وركد، وهو إشارة إلى سكون الوحي وانقطاعه، في حين تدل «يغشى» و«يسري» على الحركة. ورمز الضحى والليل إلى الوحي وانقطاعه منقول عن «التفسير الكبير» و«التبيان في أقسام القرآن».","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص110–111.","url":""}]},{"id":"s93-28","number":28,"surah":93,"verses":[4],"references":[{"surah":93,"verses":[4]}],"verseLabel":"الضحى: 4","question":"ما سر التعبير بـ«الأولى» دون «الدنيا» في قوله: ﴿وَلَلْآخِرَةُ خَيْرٌ لَّكَ مِنَ الْأُولَى﴾؟","answer":"لو قال «من الدنيا» لكان نصًّا على أن الآخرة ما يقابل الحياة الدنيا، وإنما قال «الأولى» ليعمّ الآخرة جميعًا: ما يستقبله من عمره في الدنيا وما بعد الموت، فكان أعمّ وأدلّ على الإكرام والبشرى.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص113–114.","url":""}]},{"id":"s93-29","number":29,"surah":93,"verses":[5],"references":[{"surah":93,"verses":[5]}],"verseLabel":"الضحى: 5","question":"ما سر التعبير بـ«سوف» دون السين، وإطلاق العطاء والرضا في قوله: ﴿وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَى﴾؟","answer":"لما كانت «الآخرة» قبلها تشمل المستقبل كله جاء بـ«سوف» وهو الحرف كله، فالسين جزء منه، وأكّد باللام كما أكّد ﴿وَلَلْآخِرَةُ﴾. ولم يذكر ما يعطيه ولا زمن العطاء ولا ما يرضى به ليشمل كل خير في كل وقت، وذكر المعطي «ربك» لأن العطاء على قدر المعطي.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص114–115.","url":""}]},{"id":"s93-30","number":30,"surah":93,"verses":[11],"references":[{"surah":93,"verses":[11]}],"verseLabel":"الضحى: 11","question":"ما سر التعبير بـ«فحدّث» دون «فخبّر» في قوله: ﴿وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ﴾؟","answer":"التحديث يقتضي التكرار والإشاعة بخلاف التخبير، ليكون ذلك حديثًا عنده يعيده مرة بعد أخرى. والنعمة هنا عامة في الدين والدنيا. وهذا التوجيه منقول عن «التفسير الكبير».","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص119–120.","url":""}]},{"id":"s94-1","number":1,"surah":94,"verses":[1],"references":[{"surah":94,"verses":[1]}],"verseLabel":"الشرح: 1","question":"ماذا يحقق الاستفهام في ﴿أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ﴾؟","answer":"يقرر نعمة معلومة ويحمل المخاطب على الإقرار بها؛ فيتحول السؤال إلى تذكير مؤنس بعناية الله وتثبيت للقلب أمام مشقة الدعوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص622، تحت عنوان «بلاغة الاستفهام ودلالته»","url":""}]},{"id":"s94-10","number":10,"surah":94,"verses":[1],"references":[{"surah":94,"verses":[1]}],"verseLabel":"الشرح: 1","question":"ما الصورة في ﴿نَشْرَحْ لَكَ صَدْرَكَ﴾؟","answer":"شُبهت تهيئة النفس لقبول الهدى والطمأنينة بتوسيع الشيء بعد ضيقه؛ فتجعل الاستعارة انفساح القلب للنور معنى محسوسًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص622–623، تحت عنوان «بلاغة الاستعارة باستعمال مفردة الشرح»","url":""}]},{"id":"s94-2","number":2,"surah":94,"verses":[1],"references":[{"surah":94,"verses":[1]}],"verseLabel":"الشرح: 1","question":"ما دلالة تقديم ﴿لَكَ﴾؟","answer":"تقديم «لك» يعتني بمنفعة الشرح العائدة إلى النبي ﷺ، ويسارع بإدخال السرور عليه والتشويق إلى ما يأتي بعدها. فهو إبراز للعناية به قبل تفصيل النعمة ومحلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص624، تحت عنوان «غرض تقديم ﴿لك﴾ ودلالته»","url":""}]},{"id":"s94-3","number":3,"surah":94,"verses":[2,3],"references":[{"surah":94,"verses":[2,3]}],"verseLabel":"الشرح: 2–3","question":"ماذا توحي كلمة ﴿وَضَعْنَا﴾ في قوله ﴿وَوَضَعْنَا عَنْكَ وِزْرَكَ﴾؟","answer":"تصور إزالة العبء وتخفيف ثقله، كما يوضع الحمل عن الظهر؛ فتقرب معنى التفريج والعناية بصورة حركة محسوسة تامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص626، تحت عنوان «بلاغة التعبير بمفردة الوضع»","url":""}]},{"id":"s94-11","number":11,"surah":94,"verses":[2,3],"references":[{"surah":94,"verses":[2,3]}],"verseLabel":"الشرح: 2–3","question":"كيف تجسد عبارة ﴿الَّذِي أَنْقَضَ ظَهْرَكَ﴾ شدة الوزر؟","answer":"تمثل المعنى بحمل بالغ الثقل حتى يُسمع للظهر منه نقيض؛ فتجعل شدة المعاناة النفسية مشهدًا محسوسًا، ثم يظهر عظم نعمة إزالتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص628–629، تحت عنوان «بلاغة الاستعارة التمثيلية»","url":""}]},{"id":"s94-4","number":4,"surah":94,"verses":[4],"references":[{"surah":94,"verses":[4]}],"verseLabel":"الشرح: 4","question":"ما الصورة في قوله ﴿وَرَفَعْنَا لَكَ ذِكْرَكَ﴾؟","answer":"شُبه علو منزلة النبي ﷺ وشرفه بالارتفاع المكاني؛ فالرفعة المعنوية تبدو كشيء عال ظاهر لا يخفى.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص629، تحت عنوان «بلاغة الاستعارة في لفظ الرفع»","url":""}]},{"id":"s94-12","number":12,"surah":94,"verses":[4],"references":[{"surah":94,"verses":[4]}],"verseLabel":"الشرح: 4","question":"ماذا يراد بـ﴿ذِكْرَكَ﴾ في قوله ﴿وَرَفَعْنَا لَكَ ذِكْرَكَ﴾؟","answer":"يراد شرفه وصيته الحسن وانتشار الثناء عليه، لا مجرد التلفظ باسمه؛ فصار الذكر كناية عن منزلة راسخة في القلوب والألسنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص630، تحت عنوان «بلاغة الاستعارة في لفظ الذكر»","url":""}]},{"id":"s94-5","number":5,"surah":94,"verses":[5,6],"references":[{"surah":94,"verses":[5,6]}],"verseLabel":"الشرح: 5–6","question":"لماذا فُصل الوعد ﴿إِنَّ مَعَ الْعُسْرِ يُسْرًا﴾ عما قبله؟","answer":"لأنه يأتي جوابًا عما قد يثيره ذكر أعباء الرسالة من سؤال عن مخرج الشدة؛ فاستؤنف الوعد ليقرر أن العسر مصحوب باليسر ويثبت القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص636، تحت عنوان «علة فصل ﴿إن مع العسر يسرًا﴾ عما قبله»","url":""}]},{"id":"s94-13","number":13,"surah":94,"verses":[5,6],"references":[{"surah":94,"verses":[5,6]}],"verseLabel":"الشرح: 5–6","question":"ما سر تكرار ﴿الْعُسْرِ﴾ معرفة و﴿يُسْرًا﴾ نكرة؟","answer":"تعريف العسر يعيد العسر نفسه، أما تنكير اليسر فيفتح معنى التجدد والتعدد؛ فيوحي بأن العسر الواحد لا يغلب ألوان اليسر، مع تأكيد الوعد بتكرار الجملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص636–637، تحت عنوان «نكتة إعادة العسر معرفًا واليسر منكرًا»","url":""}]},{"id":"s94-6","number":6,"surah":94,"verses":[5,6],"references":[{"surah":94,"verses":[5,6]}],"verseLabel":"الشرح: 5–6","question":"ما سرّ التعبير بـ﴿مَعَ الْعُسْرِ﴾ دون «بعد العسر»؟","answer":"تصور المعية اليسرَ قريبًا من العسر كأنه مصاحب له، فتقوي الوعد بقرب الفرج. وتوجه الموسوعة ذلك إلى استعارة تقرب حصول اليسر عقب العسر حتى لا يتوهم طول الفصل بينهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص634، تحت عنوان «بلاغة استعمال المعية وفائدتها»","url":""}]},{"id":"s94-7","number":7,"surah":94,"verses":[7],"references":[{"surah":94,"verses":[7]}],"verseLabel":"الشرح: 7","question":"لماذا لم يحدد القرآن الشيء الذي يفرغ منه النبي ﷺ في ﴿فَإِذَا فَرَغْتَ فَانْصَبْ﴾؟","answer":"ليعم كل شغل نافع؛ فكلما أتم عملًا شرع في عبادة أو عمل آخر، فلا يتحول الفراغ إلى بطالة وانقطاع عن الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص640–641، تحت عنوان «نكتة حذف متعلق ﴿فرغت﴾»","url":""}]},{"id":"s94-14","number":14,"surah":94,"verses":[7],"references":[{"surah":94,"verses":[7]}],"verseLabel":"الشرح: 7","question":"لماذا قيل ﴿فَانْصَبْ﴾ ولم يقل «فاتعب»؟","answer":"لأن النصب يوحي ببذل الجهد عن رغبة وقصد في العبادة، أما التعب فقد يكون عارضًا بلا اختيار؛ فاللفظ يحث على اجتهاد مقصود.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص641، تحت عنوان «بلاغة التعبير بالنصب دون التعب»","url":""}]},{"id":"s94-8","number":8,"surah":94,"verses":[8],"references":[{"surah":94,"verses":[8]}],"verseLabel":"الشرح: 8","question":"لماذا قُدِّم ﴿وَإِلَى رَبِّكَ﴾ على ﴿فَارْغَبْ﴾؟","answer":"لقصر الرغبة والتوجه على الله وحده؛ فلا تُصرف غاية القلب وطلبه إلى غير ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص642، تحت عنوان «غرض تقديم ﴿وإلى ربك﴾»","url":""}]},{"id":"s94-9","number":9,"surah":94,"verses":[7,8],"references":[{"surah":94,"verses":[7,8]}],"verseLabel":"الشرح: 7–8","question":"كيف يرد ختام سورة الشرح على أولها؟","answer":"بدأت السورة بنعم شرح الصدر ووضع الوزر ورفع الذكر، ثم ختمت بالأمر بالعمل والرغبة إلى الله؛ فكأن شكر تلك العناية دوام العبادة والافتقار إلى المنعم وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص643، تحت عنوان «رد ختام السورة على أولها»","url":""}]},{"id":"s94-15","number":15,"surah":94,"verses":[5,6],"references":[{"surah":94,"verses":[5,6]}],"verseLabel":"الشرح: 5–6","question":"ما سر تكرير الجملة في قوله: ﴿فَإِنَّ مَعَ الْعُسْرِ يُسْرًا إِنَّ مَعَ الْعُسْرِ يُسْرًا﴾؟","answer":"التكرير هنا لتقوية الحكم وتمكينه في نفوس المؤمنين وتطمينهم به، وليس لرفع غفلة السامع أو دفع ظن الغلط كما ذكر الرضي، إذ لا يُراد من التكرير في كلام الله شيء من ذلك.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج4، ص153–154؛ النحو العربي أحكام ومعان، ج2، ص292.","url":""}]},{"id":"s95-1","number":1,"surah":95,"verses":[1,2,3],"references":[{"surah":95,"verses":[1,2,3]}],"verseLabel":"التين: 1–3","question":"هل المقصود بالتين والزيتون الثمرتان أم موضعاهما؟","answer":"يحتمل اللفظ الحقيقة في الثمرتين لما فيهما من منافع، ويحتمل المجاز عن الأرض المباركة التي اشتهرت بهما وارتبطت برسالات الأنبياء؛ واتساع الاحتمال يجمع نعمة الرزق وشرف المكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص655–656، تحت عنوان «تفصيل الاستدلال بين الحقيقة والمجاز»","url":""}]},{"id":"s95-10","number":10,"surah":95,"verses":[1,2,3],"references":[{"surah":95,"verses":[1,2,3]}],"verseLabel":"التين: 1–3","question":"ما الجامع بين التين والزيتون وطور سينين والبلد الأمين في القسم؟","answer":"تجمع خيرات الخلق ومواطن الوحي والنبوات، فتنتقل من آثار الرحمة في الرزق إلى أماكن تجلي الهداية، تمهيدًا للحديث عن تكريم الإنسان ومسؤوليته.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص654، تحت عنوان «براعة الاستهلال في السورة بالمقسمات الأربعة»","url":""}]},{"id":"s95-2","number":2,"surah":95,"verses":[2],"references":[{"surah":95,"verses":[2]}],"verseLabel":"التين: 2","question":"لماذا أُقسم بـ﴿طُورِ سِينِينَ﴾؟","answer":"لأنه الجبل الذي كلم الله عنده موسى ونزلت فيه الرسالة، فصار شاهدًا على تشريف الإنسان بالوحي وعلى صلة السورة بمواطن النبوات.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص659، تحت عنوان «سر اختيار المقسم به ﴿وطور سينين﴾»","url":""}]},{"id":"s95-3","number":3,"surah":95,"verses":[3],"references":[{"surah":95,"verses":[3]}],"verseLabel":"التين: 3","question":"لماذا عُدل عن اسم مكة إلى وصفها بـ﴿الْبَلَدِ الْأَمِينِ﴾؟","answer":"لإبراز نعمة الأمن الملازمة لها وحرمة من دخلها، حتى صُوّر البلد نفسه أمينًا لكثرة ما يؤمّن أهله وزائريه. فالوصف أنسب بالقسم وبالامتنان من مجرد الاسم.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص664–665، تحت عنوان «سر العدول عن (مكة) إلى التوصيف بـ﴿الأمين﴾»","url":""}]},{"id":"s95-4","number":4,"surah":95,"verses":[4],"references":[{"surah":95,"verses":[4]}],"verseLabel":"التين: 4","question":"ما معنى ﴿فِي أَحْسَنِ تَقْوِيمٍ﴾؟","answer":"يشمل حسن التقويم اعتدال الخلقة وما خص به الإنسان من العقل والاستعداد للتمييز. فالتفضيل ينوه بإتقان تكوينه ظاهرًا وباطنًا، ولا ينحصر في جمال الصورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص671–672، تحت عنوان «دلالة اسم التفضيل ﴿أحسن﴾ مادة وصيغة»","url":""}]},{"id":"s95-5","number":5,"surah":95,"verses":[5],"references":[{"surah":95,"verses":[5]}],"verseLabel":"التين: 5","question":"ما سرّ التعبير بقوله تعالى ﴿ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ﴾؟","answer":"تختلف دلالة «ثم» باختلاف تفسير الرد: فعلى تفسيره بأرذل العمر تفيد التراخي الزمني بعد الشباب والقوة، ولا تجعل الشيخوخة عقوبة على فساد الإنسان. وعلى تفسيره بالسقوط الأخلاقي أو بدركات النار يكون التراخي رتبيًا يبرز بُعد حال الانحطاط عن حسن التقويم.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص673–674، تحت عنوان «دلالة ﴿ثم﴾ والغرض منها»","url":""}]},{"id":"s95-6","number":6,"surah":95,"verses":[6],"references":[{"surah":95,"verses":[6]}],"verseLabel":"التين: 6","question":"كيف يُظهر قوله ﴿فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ﴾ أن الجزاء ثمرة مباشرة للإيمان والعمل؟","answer":"تربط الفاء الجزاء بما قبلها وتفرعه عليه، فيظهر الأجر نتيجة للإيمان والعمل الصالح، كما يقوي هذا الربط ما في الموصول من معنى الشرط.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص685–686، تحت عنوان «نكتة التعبير بـ(الفاء) في ﴿فلهم﴾»","url":""}]},{"id":"s95-7","number":7,"surah":95,"verses":[6],"references":[{"surah":95,"verses":[6]}],"verseLabel":"التين: 6","question":"ما دلالة ﴿غَيْرُ مَمْنُونٍ﴾؟","answer":"تفيد أجرًا غير مقطوع يدوم ولا ينفد، وتحتمل أيضًا عطاءً لا يلحقه المنّ المؤذي؛ فيجتمع دوام الجزاء مع تنزهه عن الأذى.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص687، تحت عنوان «سر التعبير باسم المفعول ﴿ممنون﴾ مادة وصيغة»","url":""}]},{"id":"s95-8","number":8,"surah":95,"verses":[7],"references":[{"surah":95,"verses":[7]}],"verseLabel":"التين: 7","question":"إلى من يتجه الخطاب في ﴿فَمَا يُكَذِّبُكَ بَعْدُ بِالدِّينِ﴾؟","answer":"يحتمل أن يتجه إلى الإنسان المكذب: فما الذي يحملك بعد هذه الحجج على إنكار الجزاء؟ ويحتمل أن يتجه إلى النبي تثبيتًا: فمن يقدر أن يكذبك بعد وضوح الدليل؟ والسياق يحتمل المعنيين المتساندين.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص692، تحت عنوان «تحديد المخاطب بـ(الكاف) في ﴿يكذبك﴾»","url":""}]},{"id":"s95-11","number":11,"surah":95,"verses":[7],"references":[{"surah":95,"verses":[7]}],"verseLabel":"التين: 7","question":"ما الذي ينكره السؤال ﴿فَمَا يُكَذِّبُكَ بَعْدُ بِالدِّينِ﴾؟","answer":"ينكر بقاء التكذيب بالجزاء بعد دلائل خلق الإنسان وتقلبه والتمييز بين الإيمان والكفر؛ فلا يبقى عذر عقلي لإنكار الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص689–690، تحت عنوان «دلالة (ما) الاستفهامية والغرض منها»","url":""}]},{"id":"s95-9","number":9,"surah":95,"verses":[8],"references":[{"surah":95,"verses":[8]}],"verseLabel":"التين: 8","question":"لماذا خُتمت سورة التين بالسؤال ﴿أَلَيْسَ اللَّهُ بِأَحْكَمِ الْحَاكِمِينَ﴾؟","answer":"ليقرر الجواب الذي لا يمكن إنكاره: بلى، هو أحكم الحاكمين؛ ومن كمال حكمه ألا يسوي بين المؤمن والمكذب ولا يترك الإنسان بلا بعث وجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص695، تحت عنوان «دلالة الاستفهام بـ(الهمزة) في ﴿أليس﴾»","url":""}]},{"id":"s95-12","number":12,"surah":95,"verses":[8],"references":[{"surah":95,"verses":[8]}],"verseLabel":"التين: 8","question":"ماذا يضيف وصف الله بأنه ﴿أَحْكَمُ الْحَاكِمِينَ﴾؟","answer":"يثبت بلوغ حكمه الغاية في العدل والإتقان ووضع كل جزاء موضعه، وأن حكم البشر مهما بلغ لا يساوي حكمه ولا يخرج عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص697، تحت عنوان «دلالة اسم التفضيل (أحكم) مادة وصيغة»","url":""}]},{"id":"s95-13","number":13,"surah":95,"verses":[1,3],"references":[{"surah":95,"verses":[1,3]}],"verseLabel":"التين: 1، 3","question":"ما سر ترتيب المقسَم به في قوله: ﴿وَالتِّينِ وَالزَّيْتُونِ وَطُورِ سِينِينَ وَهَذَا الْبَلَدِ الْأَمِينِ﴾؟","answer":"تدرّج من الفاضل إلى الأفضل: من التين إلى الزيتون الشجرة المباركة، إلى طور سينين حيث كلّم الله موسى، إلى البلد الأمين أفضل البقاع، فختم بموطن الرسالة الخاتمة، ولم تمنعه الفاصلة من تأخير الأفضل. ووضع الطور بجوار الزيتون لأن الزيتون ذُكر بجواره في ﴿وَشَجَرَةً تَخْرُجُ مِن طُورِ سَيْنَاءَ﴾. والقول بأنها مواطن الرسالات الثلاث منقول عن «التبيان في أقسام القرآن».","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص345–347؛ الجملة العربية تأليفها وأقسامها، ص50.","url":""}]},{"id":"s95-14","number":14,"surah":95,"verses":[3],"references":[{"surah":95,"verses":[3]}],"verseLabel":"التين: 3","question":"ما سر وصف البلد بـ«الأمين» دون «الآمن» الذي ورد في مواطن أخرى؟","answer":"جمع «الأمين» معنييِ الأمن والأمانة، ومعنييِ اسم الفاعل واسم المفعول؛ فهو آمن ومأمون وأمين. ومن حيث الأمانة: نزل بالرسالة الروح الأمين فأدّاها إلى الصادق الأمين في البلد الأمين.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص347–349.","url":""}]},{"id":"s95-15","number":15,"surah":95,"verses":[4,5],"references":[{"surah":95,"verses":[4,5]}],"verseLabel":"التين: 4–5","question":"ما سر إسناد الخلق والردّ إلى الله في قوله: ﴿لَقَدْ خَلَقْنَا الْإِنسَانَ فِي أَحْسَنِ تَقْوِيمٍ ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ﴾؟","answer":"أسند الخلق إلى نفسه لأنه مقام بيان عظيم قدرته والتفضل، بخلاف ﴿وَخُلِقَ الْإِنسَانُ ضَعِيفًا﴾، وليُعلم أن واضع المنهج للإنسان هو خالقه. وأسند الردّ إليه أيضًا لبيان أن بيده البداية والنهاية، ولو قال «ثم رُدّ» لفُهم أن هناك رادًّا غيره يفسد خلقته.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص350–351.","url":""}]},{"id":"s95-16","number":16,"surah":95,"verses":[6],"references":[{"surah":95,"verses":[6]}],"verseLabel":"التين: 6","question":"ما سر الاقتصار في الاستثناء على الإيمان والعمل الصالح دون التواصي كما في سورة العصر؟","answer":"الإيمان والعمل الصالح يمنعان من الردّ أسفل سافلين، ولكن لا يمنعان من الخسران الذي يفوت من لم يتواصَ بالحق والصبر؛ فلما ذكر الخُسر في العصر ضيّق الاستثناء، ولما ذكر أسفل سافلين هنا وسّعه. وهذا التوجيه منقول عن «التبيان في أقسام القرآن».","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص352–353.","url":""}]},{"id":"s95-17","number":17,"surah":95,"verses":[6],"references":[{"surah":95,"verses":[6]}],"verseLabel":"التين: 6","question":"ما سر التعبير بـ﴿غَيْرُ مَمْنُونٍ﴾ وزيادة الفاء في ﴿فَلَهُمْ أَجْرٌ﴾؟","answer":"«غير ممنون» تجمع معنيين مرادين: غير منقطع، وغير منغّص بالمنّة، ولو قال «غير مقطوع» لأفاد معنى دون آخر. وزاد الفاء هنا دون الانشقاق لأنه بدأ التين بتكريم الإنسان فناسب تأكيد استمرار أجره، وأوجز في الانشقاق في ذكر المؤمنين فحذفها.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص353–354.","url":""}]},{"id":"s95-18","number":18,"surah":95,"verses":[7],"references":[{"surah":95,"verses":[7]}],"verseLabel":"التين: 7","question":"ما سر اختيار كلمة «الدين» دون «الجزاء» في قوله: ﴿فَمَا يُكَذِّبُكَ بَعْدُ بِالدِّينِ﴾؟","answer":"لما تقدّم ذكر مواطن الرسالات ناسب ذكر «الدين»، فجمعت الكلمة معنى الدين ومعنى الجزاء؛ أي: أيّ شيء يجعلك مكذبًا بصحة الدين وبالجزاء بعد هذه الأدلة، ولو قال «بالجزاء» لم يجمع المعنيين.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص355.","url":""}]},{"id":"s96-1","number":1,"surah":96,"verses":[1],"references":[{"surah":96,"verses":[1]}],"verseLabel":"العلق: 1","question":"لماذا افتتحت الرسالة المحمدية بالأمر بالقراءة؟","answer":"لإعلان أن العلم والقراءة أساس هذه الرسالة، وأن بعثة النبي ﷺ تبدأ بإخراج الناس من الجهل إلى نور الوحي والمعرفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص710، تحت عنوان «نكتة الابتداء بالأمر بالقراءة»","url":""}]},{"id":"s96-16","number":16,"surah":96,"verses":[1],"references":[{"surah":96,"verses":[1]}],"verseLabel":"العلق: 1","question":"كيف يوجّه قوله ﴿بِاسْمِ رَبِّكَ﴾ فعل القراءة؟","answer":"يوجّه القارئ إلى أن يستعين بربه ويجعل قراءته مصاحبة لذكره، فلا تكون المعرفة منفصلة عن هدايته وعونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص714، تحت عنوان «دلالة (الباء) والغرض منها»","url":""}]},{"id":"s96-2","number":2,"surah":96,"verses":[1],"references":[{"surah":96,"verses":[1]}],"verseLabel":"العلق: 1","question":"لماذا قيل ﴿رَبِّكَ﴾ بدل الاسم العلم «الله»؟","answer":"لأن اسم الرب يستحضر التربية والرعاية والإنعام، فيطمئن النبي ﷺ إلى أن الذي يكلفه بالقراءة هو الذي تولاه ورباه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص716، تحت عنوان «سر التعبير بلفظ (الرب) بدل الاسم العلم (الله)»","url":""}]},{"id":"s96-3","number":3,"surah":96,"verses":[1,2],"references":[{"surah":96,"verses":[1,2]}],"verseLabel":"العلق: 1–2","question":"ماذا أفاد إطلاق قوله ﴿الَّذِي خَلَقَ﴾ من غير ذكر للمخلوق؟","answer":"أفاد عموم الخلق كله، فاستدل بالكون على قدرة الرب من غير أن يحصر فعل الخلق في مخلوق بعينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص719–720، تحت عنوان «دلالة حذف المتعلق لجملة الصلة»","url":""}]},{"id":"s96-17","number":17,"surah":96,"verses":[1,2],"references":[{"surah":96,"verses":[1,2]}],"verseLabel":"العلق: 1–2","question":"لماذا خُص الإنسان بالذكر بعد تعميم الخلق؟","answer":"لتنبيهه إلى أصل خلقه القريب، وإقامة الحجة عليه بما يشاهده في نفسه بعد الدليل العام في سائر المخلوقات.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص722، تحت عنوان «دلالة تقييد فعل الخلق الثاني بـ﴿الإنسان﴾»","url":""}]},{"id":"s96-4","number":4,"surah":96,"verses":[2],"references":[{"surah":96,"verses":[2]}],"verseLabel":"العلق: 2","question":"كيف يجمع قوله ﴿خَلَقَ الْإِنْسَانَ مِنْ عَلَقٍ﴾ بين تذكير الإنسان بضعفه وتنبيهه إلى قدرته على العلم؟","answer":"يرده إلى أصل ضعيف بدأت منه نشأته، ثم يلفت إلى ما صنعه الله به من أطوار حتى صار إنسانًا كامل القوى قابلًا للعلم والكتابة. فالمسافة بين العلق والإنسان العاقل دليل قدرة الخالق، وداعية إلى التواضع والإيمان بالبعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص722–723، تحت عنوان «دلالة ﴿من﴾ الجارة والغرض منها»","url":""}]},{"id":"s96-5","number":5,"surah":96,"verses":[3],"references":[{"surah":96,"verses":[3]}],"verseLabel":"العلق: 3","question":"لماذا تكرر الأمر ﴿اقْرَأْ﴾ في مطلع السورة؟","answer":"لتثبيت الأمر وتعظيم شأن القراءة والعلم، ولإيناس النبي ﷺ بعد رهبة اللقاء الأول حتى يمضي في تلقي الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص724–725، تحت عنوان «دلالة تكرار الأمر بالقراءة»","url":""}]},{"id":"s96-18","number":18,"surah":96,"verses":[3],"references":[{"surah":96,"verses":[3]}],"verseLabel":"العلق: 3","question":"ماذا يبعث وصف الرب بأنه ﴿الْأَكْرَمُ﴾ في نفس المأمور بالقراءة؟","answer":"يبعث الثقة بأن الرب سيمنحه من فضله علمًا فوق ما يعرف، فكرمه لا يقف عند الخلق بل يمتد إلى التعليم والهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص726–727، تحت عنوان «دلالة النعت باسم التفضيل في ﴿الأكرم﴾»","url":""}]},{"id":"s96-6","number":6,"surah":96,"verses":[4,5],"references":[{"surah":96,"verses":[4,5]}],"verseLabel":"العلق: 4–5","question":"لماذا خُص القلم بالذكر؟","answer":"القلم وسيلة تدوين العلم وحفظه ونقله إلى الغائبين والأجيال اللاحقة. فذكره في مقام الامتنان بالتعليم يبين نعمة الكتابة وأثرها في بقاء المعارف وانتشارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص729، تحت عنوان «دلالة جملة الصلة الفعلية ﴿علم بالقلم﴾»","url":""}]},{"id":"s96-7","number":7,"surah":96,"verses":[5],"references":[{"surah":96,"verses":[5]}],"verseLabel":"العلق: 5","question":"ماذا يشمل قوله ﴿عَلَّمَ الْإِنْسَانَ مَا لَمْ يَعْلَمْ﴾؟","answer":"يشمل كل ما أفاضه الله على الإنسان من معارف الوحي والعقل والتجربة؛ فجاءت ﴿ما﴾ عامة لتستوعب أبواب التعليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص733–734، تحت عنوان «نكتة التعبير بـ﴿ما﴾»","url":""}]},{"id":"s96-8","number":8,"surah":96,"verses":[6,7],"references":[{"surah":96,"verses":[6,7]}],"verseLabel":"العلق: 6–7","question":"كيف تكشف الآيات سبب طغيان الإنسان بعد ذكر نعمة التعليم؟","answer":"تكشف أن العلم والنعم قد ينقلبان طغيانًا حين يرى الإنسان نفسه مستغنيًا عن ربه؛ فالعلة ليست في النعمة بل في وهم الاستغناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص741–742، تحت عنوان «دلالة ﴿أن﴾ وتعلقها بـ(اللام) والغرض منهما»","url":""}]},{"id":"s96-9","number":9,"surah":96,"verses":[7],"references":[{"surah":96,"verses":[7]}],"verseLabel":"العلق: 7","question":"ماذا يكشف التعبير ﴿أَنْ رَآهُ اسْتَغْنَى﴾ عن منشأ الطغيان؟","answer":"يكشف أنه يبدأ من حكم داخلي واهم: يتصور الإنسان نفسه مكتفيًا بما عنده، فيغفل عن افتقاره الدائم إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص742–743، تحت عنوان «دلالة فعل (الرؤية) مادة وصيغة»","url":""}]},{"id":"s96-10","number":10,"surah":96,"verses":[8],"references":[{"surah":96,"verses":[8]}],"verseLabel":"العلق: 8","question":"ماذا أفاد تقديم ﴿إِلَى رَبِّكَ﴾ في قوله ﴿إِنَّ إِلَى رَبِّكَ الرُّجْعَى﴾؟","answer":"أفاد حصر الرجوع والمصير إلى الله وحده، فيبطل وهم الاستغناء ويجعل الطاغي أمام حقيقة الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص747، تحت عنوان «سر تقديم الجار والمجرور ﴿إلى ربك﴾»","url":""}]},{"id":"s96-11","number":11,"surah":96,"verses":[9,10],"references":[{"surah":96,"verses":[9,10]}],"verseLabel":"العلق: 9–10","question":"لماذا صيغ التعجب ﴿أَرَأَيْتَ الَّذِي يَنْهَى عَبْدًا إِذَا صَلَّى﴾؟","answer":"الاستفهام يدعو إلى التعجب من حال الناهي عن الصلاة واستنكار فعله: كيف يمنع عبدًا من طاعة ربه؟ وعرض الفعل في صورة مشهد منظور يجعل قبحه أقرب إلى الإدراك.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص752–753، تحت عنوان «دلالة همزة الاستفهام في ﴿أرأيت﴾»","url":""}]},{"id":"s96-12","number":12,"surah":96,"verses":[11,12,13,14],"references":[{"surah":96,"verses":[11,12,13,14]}],"verseLabel":"العلق: 11–14","question":"لماذا تكرر ﴿أَرَأَيْتَ﴾ في مشهد الذي ينهى عبدًا إذا صلى؟","answer":"لتجديد التعجيب والتوبيخ عند كل احتمال، وحمل السامع على تأمل قبح النهي سواء كان المصلي على الهدى أم كان الناهي مكذبًا متوليًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص761، تحت عنوان «دلالة تكرار ﴿أرأيت﴾ الثانية»","url":""}]},{"id":"s96-19","number":19,"surah":96,"verses":[11,12,13,14],"references":[{"surah":96,"verses":[11,12,13,14]}],"verseLabel":"العلق: 11–14","question":"ما أثر ختام المحاجة بقوله ﴿أَلَمْ يَعْلَمْ بِأَنَّ اللَّهَ يَرَى﴾؟","answer":"يضع الناهي تحت رقابة الله المباشرة، فيصير علم الله بفعله أبلغ زاجر ووعيد بعد كشف ضلال موقفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص770، تحت عنوان «دلالة (همزة) الاستفهام في ﴿ألم﴾»","url":""}]},{"id":"s96-13","number":13,"surah":96,"verses":[15,16],"references":[{"surah":96,"verses":[15,16]}],"verseLabel":"العلق: 15–16","question":"ماذا يصور الوعيد ﴿لَنَسْفَعًا بِالنَّاصِيَةِ﴾؟","answer":"يصور أخذًا شديدًا عنيفًا من مقدم الرأس، فيجسد إذلال الطاغية واقتياده قسرًا إلى العقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص780، تحت عنوان «دلالة فعل (السفع) مادة وصيغة»","url":""}]},{"id":"s96-20","number":20,"surah":96,"verses":[15,16],"references":[{"surah":96,"verses":[15,16]}],"verseLabel":"العلق: 15–16","question":"لماذا عُلّق السفع بالناصية؟","answer":"لأن الأخذ بمقدم الرأس أبلغ في الإهانة والتمكن من المأخوذ، فيقلب كبرياءه ذلًا ظاهرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص784، تحت عنوان «دلالة الكناية في ﴿لنسفعًا بالناصية﴾»","url":""}]},{"id":"s96-21","number":21,"surah":96,"verses":[15,16],"references":[{"surah":96,"verses":[15,16]}],"verseLabel":"العلق: 15–16","question":"كيف وُصفت الناصية بأنها ﴿كَاذِبَةٍ خَاطِئَةٍ﴾ مع أن الكذب والخطأ لصاحبها؟","answer":"نُسب إليها وصف صاحبها تصويرًا لتمكن الكذب والخطيئة منه، حتى كأن موضع قيادته وتدبيره قد صار هو الكاذب الخاطئ.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص788، تحت عنوان «دلالة المجاز العقلي أو الاستعارة المكنية في ﴿كاذبة خاطئة﴾»","url":""}]},{"id":"s96-14","number":14,"surah":96,"verses":[17,18],"references":[{"surah":96,"verses":[17,18]}],"verseLabel":"العلق: 17–18","question":"ما الذي يصوره قوله ﴿فَلْيَدْعُ نَادِيَهُ﴾؟","answer":"يتحداه أن يستنصر بأهل مجلسه وعشيرته الذين يعتز بهم، كاشفًا عجز السند البشري أمام أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص792، تحت عنوان «دقة اختيار لفظ (النادي)»","url":""}]},{"id":"s96-22","number":22,"surah":96,"verses":[17,18],"references":[{"surah":96,"verses":[17,18]}],"verseLabel":"العلق: 17–18","question":"ما أثر المقابلة بين ﴿نَادِيَهُ﴾ و﴿الزَّبَانِيَةَ﴾؟","answer":"تقابل أنصار الطاغية المحدودين بملائكة العذاب الأقوياء، فتُظهر سخف تهديده وحتمية انكسار قوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص797، تحت عنوان «دلالة التقابل بين ﴿ناديه﴾ و﴿الزبانية﴾»","url":""}]},{"id":"s96-15","number":15,"surah":96,"verses":[19],"references":[{"surah":96,"verses":[19]}],"verseLabel":"العلق: 19","question":"لماذا جاء ﴿لَا تُطِعْهُ﴾ خلاصةً بعد عرض طغيان الناهي؟","answer":"ليحوّل المحاجة والوعيد إلى موقف عملي حاسم: الثبات على العبادة ورفض سلطان الطاغية.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص799، تحت عنوان «دلالة الفذلكة في ﴿لا تطعه﴾»","url":""}]},{"id":"s96-23","number":23,"surah":96,"verses":[19],"references":[{"surah":96,"verses":[19]}],"verseLabel":"العلق: 19","question":"لماذا أعقب النهي عن طاعة الطاغية بالأمر ﴿وَاسْجُدْ﴾؟","answer":"لأن الرد العملي على من ينهى عن الصلاة هو المضي فيها، والسجود أظهر معاني الخضوع لله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص801، تحت عنوان «دلالة العطف بـ(الواو) في ﴿واسجد﴾»","url":""}]},{"id":"s96-24","number":24,"surah":96,"verses":[19],"references":[{"surah":96,"verses":[19]}],"verseLabel":"العلق: 19","question":"ماذا يضيف الأمر ﴿وَاقْتَرِبْ﴾ بعد السجود؟","answer":"يبين أن السجود ليس حركة مجردة، بل طريق إلى القرب من الله بالطاعة والعبادة، وهو غاية تناقض طغيان المستغني.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص803، تحت عنوان «دلالة (الواو) في ﴿واقترب﴾»","url":""}]},{"id":"s96-25","number":25,"surah":96,"verses":[15,16],"references":[{"surah":96,"verses":[15,16]}],"verseLabel":"العلق: 15–16","question":"ما سر إبدال النكرة الموصوفة من المعرفة في قوله: ﴿لَنَسْفَعًا بِالنَّاصِيَةِ نَاصِيَةٍ كَاذِبَةٍ خَاطِئَةٍ﴾؟","answer":"جاء بالبدل لبيان صفة الناصية المسفوعة، فجمع بين تعيينها ووصفها؛ ولا يحسن إبدال النكرة من المعرفة إلا إذا كانت موصوفة، كما هنا.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج3، ص205؛ النحو العربي أحكام ومعان، ج2، ص298.","url":""}]},{"id":"s97-1","number":1,"surah":97,"verses":[1],"references":[{"surah":97,"verses":[1]}],"verseLabel":"القدر: 1","question":"لماذا قال ﴿أَنْزَلْنَاهُ﴾ قبل أن يذكر القرآن صراحة؟","answer":"لأن القرآن حاضر في أذهان المخاطبين مشهور بينهم، فكأن ذكره لا يحتاج إلى اسم يسبقه. والإضمار قبل الذكر يلفت إلى علو شأنه ووضوح مرجعه، ويهيئ السامع لتلقي خبر الليلة التي نزل فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص20، تحت عنوان «سر الإضمار قبل الذكر في ﴿أنزلناه﴾»","url":""}]},{"id":"s97-11","number":11,"surah":97,"verses":[1],"references":[{"surah":97,"verses":[1]}],"verseLabel":"القدر: 1","question":"هل يدل ضمير الجمع في ﴿إِنَّا أَنْزَلْنَاهُ﴾ على تعدد المُنزِل؟","answer":"لا؛ فهو جمع التعظيم في كلام الله، يبرز جلال المتكلم وعظمة فعل الإنزال. والمنزِل هو الله وحده، أما الملائكة فتنفذ أمره؛ فلا يدل الأسلوب على تعدد الآلهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص17، تحت عنوان «سر التعبير عن المسند إليه بضمير الجمع»","url":""}]},{"id":"s97-2","number":2,"surah":97,"verses":[1],"references":[{"surah":97,"verses":[1]}],"verseLabel":"القدر: 1","question":"ما سرّ التعبير بقوله تعالى ﴿فِي لَيْلَةِ الْقَدْرِ﴾ ووقوع ابتداء الإنزال ليلًا؟","answer":"تذكر الموسوعة أن تخصيص الليل يناسب ما فيه من هدوء وسكون وقلة شواغل، وما يتهيأ فيه من خشوع وتضرع وتدبر. ففي تعيينه تنويه بوقت ابتداء الإنزال.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص21–22، تحت عنوان «سر اختيار الإنزال في (الليل)»","url":""}]},{"id":"s97-3","number":3,"surah":97,"verses":[1],"references":[{"surah":97,"verses":[1]}],"verseLabel":"القدر: 1","question":"لماذا سميت ﴿لَيْلَةُ الْقَدْرِ﴾ بهذا الاسم؟","answer":"يجمع اسم القدر معاني الشرف والعظمة والتقدير، وقيل التضييق لكثرة نزول الملائكة فيها. وأظهر هذه المعاني أنها ليلة عظيمة الشأن يُقدّر فيها من الأمر ما شاء الله، فلا يلزم أن تحمل التسمية على وجه واحد فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص22، تحت عنوان «سر التعبير بلفظ ﴿القدر﴾ معرفًا بـ(أل)»","url":""}]},{"id":"s97-4","number":4,"surah":97,"verses":[4],"references":[{"surah":97,"verses":[4]}],"verseLabel":"القدر: 4، النبأ 38","question":"لماذا اختصت ليلة القدر بتنزل الملائكة فيها؟","answer":"لشرف هذه الليلة وعظمتها؛ فقد استحقت أن تتنزل فيها الملائكة، وفي تخصيصها بذلك تنويه بالقرآن الكريم وإعلاء لشأنه، لأنها الليلة التي نزل فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص35، تحت عنوان «دلالة الجار والمجرور ﴿فيها﴾»","url":""}]},{"id":"s97-5","number":5,"surah":97,"verses":[2],"references":[{"surah":97,"verses":[2]}],"verseLabel":"القدر: 2","question":"لماذا جاء ﴿وَمَا أَدْرَاكَ مَا لَيْلَةُ الْقَدْرِ﴾؟","answer":"الاستفهام للتعظيم والتشويق إلى بيان فضل الليلة، وفيه تنبيه إلى أن مبلغ شرفها لا يستقل المخاطب بإدراكه حتى يعرفه الله به.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص23–24، تحت عنوان «نكتة الاستفهام بـ(ما) والغرض منها»","url":""}]},{"id":"s97-6","number":6,"surah":97,"verses":[3],"references":[{"surah":97,"verses":[3]}],"verseLabel":"القدر: 3","question":"ما وجه كون ليلة القدر ﴿خَيْرًا مِنْ أَلْفِ شَهْرٍ﴾؟","answer":"فضل العبادة والعمل الصالح فيها يزيد على فضل ذلك في ألف شهر لا تكون فيها ليلة القدر. فالتعبير لا يقرر مجرد المساواة، بل يثبت زيادة لا يحيط السامع بمقدارها ويبرز بركة الزمن الذي شرفه نزول القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص27، تحت عنوان «جهة الأفضلية في اسم التفضيل ﴿خير﴾»","url":""}]},{"id":"s97-12","number":12,"surah":97,"verses":[3],"references":[{"surah":97,"verses":[3]}],"verseLabel":"القدر: 3","question":"لماذا ضُرب المثل بألف شهر في بيان فضل ليلة القدر؟","answer":"الألف من أكبر الأعداد المألوفة في خطاب العرب، فاستعمل لإبراز كثرة بالغة ومدة تتجاوز عمرًا طويلًا. وليس المقصود حصر فضل الليلة عند حد حسابي، بل تقريب عظمته بما يملأ النفس دهشة ورغبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص28، تحت عنوان «نكتة التعبير بالعدد المفضل عليه ﴿ألف﴾»","url":""}]},{"id":"s97-7","number":7,"surah":97,"verses":[4],"references":[{"surah":97,"verses":[4]}],"verseLabel":"القدر: 4","question":"ما الذي يكشفه نزول الملائكة جميعًا في ليلة القدر عن شرفها؟","answer":"يكشف عظمة الليلة ورفعة شأنها؛ فتعريف ﴿الملائكة﴾ يفيد استغراق جموعهم، ويصورهم يتنزلون فيها أفواجًا متتابعة، حتى يكون الحضور الملائكي العام علامة على فضلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص33، تحت عنوان «دلالة التعريف في ﴿الملائكة﴾»","url":""}]},{"id":"s97-8","number":8,"surah":97,"verses":[4],"references":[{"surah":97,"verses":[4]}],"verseLabel":"القدر: 4","question":"ما سرّ التعبير بـ﴿مِنْ كُلِّ أَمْرٍ﴾؟","answer":"تذكر الموسوعة لـ«من» وجوهًا، منها الملابسة بمعنى الباء، والسببية أو التعليل: أي يتنزلون بما أذن الله فيه، أو لأجل ما قضاه من الأمور. فالمعنى يربط تنزلهم بالإذن والتدبير الإلهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص37–38، تحت عنوان «دلالة ﴿من﴾ والغرض منها»","url":""}]},{"id":"s97-9","number":9,"surah":97,"verses":[5],"references":[{"surah":97,"verses":[5]}],"verseLabel":"القدر: 5","question":"لماذا وُصفت ليلة القدر بالمصدر ﴿سَلَامٌ﴾ لا بقولٍ مثل «سالمة»؟","answer":"الإخبار بالمصدر يبالغ في سلامتها حتى كأن الليلة نفسها سلام لا مجرد زمن يقع فيه السلام. فهي مملوءة بالخير والطمأنينة وتنزل الملائكة، وبعيدة عن الشر بما أذن الله فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص40–41، تحت عنوان «دلالة الإخبار بالمصدر عن (الليلة)»","url":""}]},{"id":"s97-13","number":13,"surah":97,"verses":[5],"references":[{"surah":97,"verses":[5]}],"verseLabel":"القدر: 5","question":"ما الذي يفيده تقديم ﴿سَلَامٌ﴾ في قوله ﴿سَلَامٌ هِيَ﴾؟","answer":"يبرز التقديم السلامة بوصفها السمة المميزة لليلة، ويفيد الاختصاص والتوكيد: هي سلام وخير على وجه عظيم. وبذلك تتقدم بشارة الأمن قبل الإشارة إلى امتدادها حتى الفجر.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص41–42، تحت عنوان «دلالة تقديم المسند في ﴿سلام هي﴾»","url":""}]},{"id":"s97-10","number":10,"surah":97,"verses":[5],"references":[{"surah":97,"verses":[5]}],"verseLabel":"القدر: 5","question":"ما دلالة ﴿حَتَّى مَطْلَعِ الْفَجْرِ﴾؟","answer":"«حتى» تبين غاية السلام أو التنزل إلى طلوع الفجر، أو غايتهما معًا على أوجه التعلق. ففيها بيان امتداد الفضل خلال أجزاء الليلة، لا اختصاصه بساعة منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص42، تحت عنوان «سر التعبير بالحرف ﴿حتى﴾ والغرض منه»","url":""}]},{"id":"s98-1","number":1,"surah":98,"verses":[1],"references":[{"surah":98,"verses":[1]}],"verseLabel":"البينة: 1","question":"لماذا أجمل الكافرين ثم فصلهم إلى أهل الكتاب والمشركين؟","answer":"لإثارة الانتباه أولًا إلى وصف الكفر الجامع، ثم بيان الصنفين اللذين تحقق فيهما: من ينتسبون إلى كتاب ومن يعبدون الأوثان، فتتضح الحجة مع اختلاف الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص58، تحت عنوان «دلالة الإجمال والتفصيل بذكر (الحال)»","url":""}]},{"id":"s98-2","number":2,"surah":98,"verses":[1],"references":[{"surah":98,"verses":[1]}],"verseLabel":"البينة: 1","question":"ما الصورة في التعبير عن ترك الكفر بـ﴿مُنْفَكِّينَ﴾؟","answer":"يصوّر الكفر شيئًا التصقوا به، وتركه انفكاكًا بعد شدة ارتباط؛ فيكشف رسوخ ما كانوا عليه وصعوبة إقلاعهم عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص61–62، تحت عنوان «دلالة الاستعارة في ﴿منفكين﴾»","url":""}]},{"id":"s98-12","number":12,"surah":98,"verses":[1],"references":[{"surah":98,"verses":[1]}],"verseLabel":"البينة: 1","question":"لماذا جعلوا مجيء البينة غاية لانفكاكهم عما هم عليه؟","answer":"يحكي ادعاءهم أنهم لن يتركوا معتقدهم حتى تأتيهم الحجة المنتظرة، ثم يفضح تناقضهم حين جاءت البينة فاستمر كثير منهم في الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص63، تحت عنوان «دلالة ﴿حتى﴾ والغرض منها»","url":""}]},{"id":"s98-3","number":3,"surah":98,"verses":[2,3],"references":[{"surah":98,"verses":[2,3]}],"verseLabel":"البينة: 2–3","question":"لماذا فصل قوله ﴿رَسُولٌ مِنَ اللَّهِ﴾ بعد ذكر البينة؟","answer":"جاء جوابًا عن سؤال يثيره إبهام البينة: ما هذه البينة؟ فإذا بها رسول من الله، فيجمع الأسلوب التشويق والبيان وتعظيم شأن الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص67، تحت عنوان «نكتة الفصل ﴿رسول من الله﴾»","url":""}]},{"id":"s98-4","number":4,"surah":98,"verses":[2],"references":[{"surah":98,"verses":[2]}],"verseLabel":"البينة: 2","question":"ماذا يفيد وصف الصحف بأنها ﴿مُطَهَّرَةٌ﴾؟","answer":"يفيد المبالغة في تنزيه ما تحمله من الوحي عن الباطل والتحريف والتناقض، حتى صارت الطهارة وصفًا ثابتًا لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص72، تحت عنوان «دلالة النعت باسم المفعول ﴿مطهرة﴾»","url":""}]},{"id":"s98-13","number":13,"surah":98,"verses":[2],"references":[{"surah":98,"verses":[2]}],"verseLabel":"البينة: 2","question":"كيف نُسبت الطهارة إلى الصحف مع أن المقصود ما فيها؟","answer":"أُسندت الطهارة إلى الوعاء والمراد الوحي الذي يحتويه، مبالغةً في شمول التنزه للصحف ومضمونها جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص73، تحت عنوان «دلالة المجاز العقلي في ﴿صحفًا مطهرة﴾»","url":""}]},{"id":"s98-5","number":5,"surah":98,"verses":[3],"references":[{"surah":98,"verses":[3]}],"verseLabel":"البينة: 3","question":"لماذا جمع ﴿كُتُبٌ﴾ في قوله ﴿فِيهَا كُتُبٌ قَيِّمَةٌ﴾؟","answer":"للدلالة على كثرة ما في تلك الصحف من الأحكام والقواعد والشرائع وتنوعها، مع اجتماعها في القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص77، تحت عنوان «سر الجمع ودلالته في ﴿كتب﴾»","url":""}]},{"id":"s98-14","number":14,"surah":98,"verses":[3],"references":[{"surah":98,"verses":[3]}],"verseLabel":"البينة: 3","question":"لماذا عُبر عن الأحكام والقضايا بلفظ ﴿كُتُبٌ﴾؟","answer":"لأنها أمور مكتوبة مثبتة في الصحف؛ فأطلق اسم المكتوب على الأحكام نفسها، إيذانًا بثبوتها وتقريرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص77، تحت عنوان «دلالة المجاز المرسل أو الاستعارة في ﴿كتب﴾»","url":""}]},{"id":"s98-15","number":15,"surah":98,"verses":[3],"references":[{"surah":98,"verses":[3]}],"verseLabel":"البينة: 3","question":"ماذا يفيد وصف الكتب بأنها ﴿قَيِّمَةٌ﴾؟","answer":"يفيد أنها مستقيمة عادلة، تقوم بالحق وتهدي إليه، لا زيغ فيها ولا اعوجاج ولا تحريف.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص78، تحت عنوان «نكتة النعت بـ﴿قيمة﴾»","url":""}]},{"id":"s98-6","number":6,"surah":98,"verses":[4],"references":[{"surah":98,"verses":[4]}],"verseLabel":"البينة: 4","question":"ماذا يكشف الحصر في أنهم لم يتفرقوا إلا من بعد ما جاءتهم البينة؟","answer":"يكشف شناعة موقفهم؛ فقد كان المنتظر أن تجمعهم الحجة، فإذا ظهورها نفسه يعقبه اختلافهم وكفرهم، فتقوم عليهم الحجة من حيث طلبوا الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص86–87، تحت عنوان «دلالة ﴿إلا﴾ والغرض منها»","url":""}]},{"id":"s98-7","number":7,"surah":98,"verses":[5],"references":[{"surah":98,"verses":[5]}],"verseLabel":"البينة: 5","question":"لماذا رُتبت الأوامر: الإخلاص ثم الصلاة ثم الزكاة؟","answer":"لأن الإخلاص أصل قبول كل عبادة، ثم جاءت الصلاة لأنها أعظم العبادات البدنية وأدومها، ثم الزكاة لأنها عبادة مالية تكمل صلاح الفرد والمجتمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص100–101، تحت عنوان «سر ترتيب الأوامر الثلاثة المتقدمة»","url":""}]},{"id":"s98-8","number":8,"surah":98,"verses":[6,7,8],"references":[{"surah":98,"verses":[6,7,8]}],"verseLabel":"البينة: 6–8","question":"ماذا تكشف المقابلة بين شر البرية وخير البرية؟","answer":"تجعل اختلاف الطريقين مرئيًا في المآل: كفر وعذاب مقيم في جانب، وإيمان وعمل صالح ونعيم ورضوان في الجانب الآخر؛ فيظهر أن الجزاء ثمرة الاعتقاد والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص123–124، تحت عنوان «دلالة التقابل بين صورتي الوعيد والوعد»","url":""}]},{"id":"s98-16","number":16,"surah":98,"verses":[6,7,8],"references":[{"surah":98,"verses":[6,7,8]}],"verseLabel":"البينة: 6–8","question":"لماذا رُتب تكريم المؤمنين من الجزاء إلى الجنات ثم الخلود والرضوان؟","answer":"بدأ بالحكم العام أنهم خير البرية، ثم فُصل الجزاء بالجنات، وأُمن انقطاعه بالخلود، وخُتم برضا الله عنهم وهو ذروة التكريم.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص141، تحت عنوان «سر ترتيب تكريم المؤمنين في صورة الوعد»","url":""}]},{"id":"s98-9","number":9,"surah":98,"verses":[7],"references":[{"surah":98,"verses":[7]}],"verseLabel":"البينة: 7","question":"ما سرّ التعبير بقوله تعالى ﴿أُولَئِكَ هُمْ خَيْرُ الْبَرِيَّةِ﴾ بضمير الفصل؟","answer":"ضمير الفصل يؤكد الحكم ويختص بالخيرية المذكورة أهل الإيمان والعمل الصالح. فهو يقوي الثناء عليهم ويربطه بما وصفوا به من اعتقاد وعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص123، تحت عنوان «دلالة الإتيان بالضمير ﴿هم﴾»","url":""}]},{"id":"s98-10","number":10,"surah":98,"verses":[8],"references":[{"surah":98,"verses":[8]}],"verseLabel":"البينة: 8","question":"ما دلالة تقديم رضا الله في ﴿رَضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ﴾؟","answer":"قُدِّم رضا الله لأن المقام مقام الجزاء والمكافأة، ورضاه هو سبب الإكرام. ثم ذُكر رضاهم بما منحهم من النعيم؛ فكان رضاهم ثمرةً تابعة لرضاه عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص136، تحت عنوان «دلالة تقديم رضا الله على رضاهم»","url":""}]},{"id":"s98-11","number":11,"surah":98,"verses":[8],"references":[{"surah":98,"verses":[8]}],"verseLabel":"البينة: 8","question":"ماذا يضيف ختام الوعد بقوله ﴿ذَلِكَ لِمَنْ خَشِيَ رَبَّهُ﴾؟","answer":"يعمم الوعد لكل من حقق الخشية، ويربط الجزاء بعلته: معرفة عظمة الله التي تبعث على الإيمان والعمل الصالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص137–138، تحت عنوان «دلالة التذييل في الآية»","url":""}]},{"id":"s98-17","number":17,"surah":98,"verses":[8],"references":[{"surah":98,"verses":[8]}],"verseLabel":"البينة: 8","question":"لماذا قيل ﴿خَشِيَ رَبَّهُ﴾ لا خشي الله؟","answer":"ليستحضر مع الهيبة معنى الربوبية: الملك والتدبير والتربية والرعاية، فتجتمع الخشية من الجلال مع معرفة فضل الرب على عبده.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص140، تحت عنوان «سر التعبير عن الذات الجليلة بلفظ (الرب)»","url":""}]},{"id":"s98-18","number":18,"surah":98,"verses":[6,8],"references":[{"surah":98,"verses":[6,8]}],"verseLabel":"البينة: 6، 8","question":"ما سر ذكر «أبدًا» في خلود المؤمنين دون خلود الكافرين في سورة البينة؟","answer":"من خطّ التعبير القرآني أنه إذا بسط وفصّل في وصف أحد الفريقين أو جزائه ذكر «الأبد»، وإن أوجز لم يذكره. وفي البينة أوجز في الكافرين فلم يزد على أنهم في نار جهنم خالدين فيها وأنهم شر البرية، وتوسّع في المؤمنين فذكر جنات عدن تجري من تحتها الأنهار ورضا الله عنهم ورضاهم عنه، فزاد في وصف خلودهم: ﴿خَالِدِينَ فِيهَا أَبَدًا﴾.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص104–105.","url":""}]},{"id":"s98-19","number":19,"surah":98,"verses":[6,7],"references":[{"surah":98,"verses":[6,7]}],"verseLabel":"البينة: 6–7","question":"ما سر إفراد اسم التفضيل في ﴿أُولَٰئِكَ هُمْ شَرُّ الْبَرِيَّةِ﴾ و﴿أُولَٰئِكَ هُمْ خَيْرُ الْبَرِيَّةِ﴾ مع أن المخبر عنه جمع؟","answer":"اسم التفضيل المضاف إلى معرفة تجوز فيه المطابقة والإفراد، وبينهما فرق: فالمطابقة تحتمل مجرد الزيادة في الوصف، وتحتمل التفضيل، وتحتمل أن يراد بها الذات لا الوصف، أما الإفراد فيُقصد به التفضيل تنصيصًا. فلما أفرد «خير» و«شر» دلّ على أن المراد تفضيلهم نصًّا.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج4، ص317.","url":""}]},{"id":"s99-1","number":1,"surah":99,"verses":[1],"references":[{"surah":99,"verses":[1]}],"verseLabel":"الزلزلة: 1","question":"لماذا قيل ﴿زُلْزِلَتِ الْأَرْضُ زِلْزَالَهَا﴾ مع تكرار مادة الزلزلة؟","answer":"لتأكيد وقوع الحدث وتهويل شدته؛ فالمصدر بعد الفعل يصور زلزالًا كاملًا بالغًا غايته، لا حركة عابرة مألوفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص156–157، تحت عنوان «وجه التعبير بالمفعول المطلق ﴿زلزالها﴾»","url":""}]},{"id":"s99-9","number":9,"surah":99,"verses":[1],"references":[{"surah":99,"verses":[1]}],"verseLabel":"الزلزلة: 1","question":"ماذا تفيد إضافة الزلزال إلى الأرض في ﴿زِلْزَالَهَا﴾؟","answer":"تخصصه بالزلزال العظيم المقدر لهذه الأرض يوم القيامة، وتوحي بأنه زلزالها الخاص الذي تستفرغ فيه غاية حركتها، لا واحد من الزلازل المعتادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص157–158، تحت عنوان «نكتة العدول إلى الإضافة في ﴿زلزالها﴾»","url":""}]},{"id":"s99-2","number":2,"surah":99,"verses":[2],"references":[{"surah":99,"verses":[2]}],"verseLabel":"الزلزلة: 2","question":"ما الصورة في ﴿وَأَخْرَجَتِ الْأَرْضُ أَثْقَالَهَا﴾؟","answer":"صور ما في باطن الأرض من أموات وكنوز كالأحمال التي تثقلها، فإذا أخرجتها خفت منها. وتبرز الصورة تبدل حال الأرض وظهور ما كان مستورًا في جوفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص164، تحت عنوان «بلاغة الاستعارة التصريحية في ﴿أثقالها﴾»","url":""}]},{"id":"s99-3","number":3,"surah":99,"verses":[3],"references":[{"surah":99,"verses":[3]}],"verseLabel":"الزلزلة: 3","question":"ما سرّ التعبير في قول الإنسان ﴿مَا لَهَا﴾؟","answer":"الاستفهام يعبر عن الدهشة والتعجب من زلزال الأرض وإخراج أثقالها على وجه لم يعهده الإنسان. فهو سؤال عن شأنها وسبب هذا التحول الهائل، وقد يوجه إلى الاستعظام لا طلب جواب مفصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص166–167، تحت عنوان «بلاغة الاستفهام بـ﴿ما﴾»","url":""}]},{"id":"s99-4","number":4,"surah":99,"verses":[4,5],"references":[{"surah":99,"verses":[4,5]}],"verseLabel":"الزلزلة: 4–5","question":"هل تحدّث الأرض أخبارها حقيقة أم مجازًا؟","answer":"يحتمل أن ينطقها الله حقيقة فتخبر بما عُمل عليها وتشهد على أهله، ويحتمل أن تكون حالها وما يظهر فيها دلالة ناطقة؛ وفي الوجهين تصير الأرض شاهدة لا يخفى عليها ما وقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص174–175، تحت عنوان «دلالة التحديث بين الحقيقة والمجاز»","url":""}]},{"id":"s99-5","number":5,"surah":99,"verses":[6],"references":[{"surah":99,"verses":[6]}],"verseLabel":"الزلزلة: 6","question":"ماذا تصور كلمة ﴿يَصْدُرُ﴾ في مشهد القيامة؟","answer":"تستحضر الناس منصرفين من موقف عظيم إلى مآلهم بعد ورودهم عليه، كما يصدر الوارد عن الماء؛ ويحتمل السياق خروجهم من القبور إلى الموقف، فيبقى اللفظ واسعًا للمشهدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص187، تحت عنوان «سر التعبير بالفعل ﴿يصدر﴾ دلالة وصيغة»","url":""}]},{"id":"s99-10","number":10,"surah":99,"verses":[6],"references":[{"surah":99,"verses":[6]}],"verseLabel":"الزلزلة: 6","question":"لماذا يخرج الناس يومئذ ﴿أَشْتَاتًا﴾؟","answer":"لأنهم يتفرقون جماعات وأفرادًا بحسب أعمالهم ومراتبهم ومصائرهم، فلا تبقى بينهم وحدة الدنيا؛ بل يساق كل فريق إلى ما يوافق حسابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص189–190، تحت عنوان «نكتة التعبير بالحال ﴿أشتاتًا﴾»","url":""}]},{"id":"s99-6","number":6,"surah":99,"verses":[6],"references":[{"surah":99,"verses":[6]}],"verseLabel":"الزلزلة: 6","question":"كيف يُرى العمل في قوله ﴿لِيُرَوْا أَعْمَالَهُمْ﴾؟","answer":"يحتمل أن يروا الأعمال نفسها مصورة ظاهرة، أو يروا جزاءها، كما تحتمل الإراءة معنى الإعلام؛ وكلها تجعل العمل وعاقبته حاضرين لا يغيب منهما شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص191–192، تحت عنوان «دلالة (الإراءة) بين الحقيقة والمجاز الاستعاري»","url":""}]},{"id":"s99-7","number":7,"surah":99,"verses":[7,8],"references":[{"surah":99,"verses":[7,8]}],"verseLabel":"الزلزلة: 7–8","question":"عمَّ تكني عبارة ﴿مِثْقَالَ ذَرَّةٍ﴾؟","answer":"تكني عن أدنى مقدار يمكن أن يستهان به من العمل؛ فتقرر أن ميزان الحساب لا يهمل أصغر خير أو شر.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص199، تحت عنوان «دلالة الكناية في إضافة ﴿مثقال ذرة﴾»","url":""}]},{"id":"s99-11","number":11,"surah":99,"verses":[7,8],"references":[{"surah":99,"verses":[7,8]}],"verseLabel":"الزلزلة: 7–8","question":"لماذا تكرر تركيب ﴿مَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ﴾ في الخير والشر؟","answer":"ليستقل كل جانب بحكم صريح يرسخ في الذهن: لا يضيع خير مهما صغر، ولا يخفى شر مهما دق؛ فيقوى الترغيب والتحذير معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص203، تحت عنوان «سر تكرار جملة: (من يعمل مثقال ذرة)»","url":""}]},{"id":"s99-12","number":12,"surah":99,"verses":[7,8],"references":[{"surah":99,"verses":[7,8]}],"verseLabel":"الزلزلة: 7–8","question":"ما أثر المقابلة بين ذرة الخير وذرة الشر؟","answer":"تجمع طرفي الحساب في ميزان واحد وتبرز عدل الجزاء وشموله؛ فيرجو السامع ثمرة القليل من الخير ويحذر القليل من الشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص203، تحت عنوان «بلاغة المقابلة بين الآيتين»","url":""}]},{"id":"s99-8","number":8,"surah":99,"verses":[7,8],"references":[{"surah":99,"verses":[7,8]}],"verseLabel":"الزلزلة: 7–8","question":"ماذا يضيف التعبير بـ﴿يَرَهُ﴾ إلى جزاء أصغر الأعمال؟","answer":"يجعل العمل أو جزاءه حاضرًا مشهودًا لصاحبه، لا مجرد خبر بعيد؛ فحتى مثقال الذرة سيظهر له ظهورًا لا إنكار معه.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص200، تحت عنوان «سر التعبير بالفعل ﴿يره﴾ دلالة وصيغة»","url":""}]},{"id":"s99-13","number":13,"surah":99,"verses":[7,8],"references":[{"surah":99,"verses":[7,8]}],"verseLabel":"الزلزلة: 7، 8","question":"ما دلالة قوله: ﴿يَرَهُ﴾ في ﴿فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ﴾ دون أن يقول «يُجزَ به» أو «يحاسَب عليه»؟","answer":"رؤية العمل لا تقتضي أن صاحبه سيجازى به، بل إنه سيراه، وقد يغفره له ربه ويستره عليه. فذكر ما هو أيسر وهو الرؤية، ولم يذكر ما هو أعظم كالحساب والجزاء؛ فإذا كان هذا هو الخبر فكيف النبأ؟ وفي ذكر «مثقال ذرة» دلالة على أن ما فوقه داخل في الرؤية من باب أولى.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص243؛ الجملة العربية والمعنى، ص62.","url":""}]},{"id":"s99-14","number":14,"surah":99,"verses":[4],"references":[{"surah":99,"verses":[4]}],"verseLabel":"الزلزلة: 4","question":"ما سر التعبير بـ«أخبارها» في قوله تعالى: ﴿يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا﴾ دون «أنباءها»؟","answer":"النبأ في الاستعمال القرآني لما هو أعظم وأهم، والخبر لما دونه. وزلزلة الأرض من الأخبار بالنسبة إلى ما ذُكر في مواطن أخرى من أحداث الساعة كانفطار السماء وتكوير الشمس وتفجير البحار ونسف الجبال، وهي فوق ذلك مشهد يتكرر في الأرض. فالتعبير بالأخبار تخويف عظيم وإشارة إلى هول ما سيحدث: فإذا كان هذا هو الخبر فكيف النبأ؟!","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص242–243؛ وفي «أسئلة بيانية»، ج1، ص204 نحو هذا.","url":""}]},{"id":"s100-1","number":1,"surah":100,"verses":[1,2,3,4,5],"references":[{"surah":100,"verses":[1,2,3,4,5]}],"verseLabel":"العاديات: 1–5","question":"لماذا افتتحت سورة العاديات بالقسم بالخيل العادية؟","answer":"لأن عدو الخيل يجمع القوة والسرعة والبذل في سبيل المقصد، ويذكّر بنعمة تسخيرها وما تظهره من وفاء وطاعة؛ فيأتي القسم تمهيدًا لتوبيخ الإنسان على جحوده لربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص216، تحت عنوان «نكتة تخصيص الوصف المقسم به»","url":""}]},{"id":"s100-11","number":11,"surah":100,"verses":[1,2,3,4,5],"references":[{"surah":100,"verses":[1,2,3,4,5]}],"verseLabel":"العاديات: 1–5","question":"ما أثر امتداد مشهد القسم في مطلع سورة العاديات قبل مجيء جوابه؟","answer":"يتابع السامع حركة الخيل مرحلة بعد مرحلة: عدوًا وقدحًا وإغارة وإثارة للغبار واقتحامًا للجمع، فيتشوق إلى جواب القسم، ويشتد وقع المفارقة بين وفاء الخيل وكنود الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص217، تحت عنوان «طول جملة فعل القسم»","url":""}]},{"id":"s100-2","number":2,"surah":100,"verses":[1],"references":[{"surah":100,"verses":[1]}],"verseLabel":"العاديات: 1","question":"ماذا تصوّر كلمة ﴿ضَبْحًا﴾ في مشهد العاديات؟","answer":"تصوّر صوت أنفاس الخيل المتردد من شدة العدو، وجيء بالمصدر ليؤكد الفعل ويجعل أثر السرعة والقوة مسموعًا في المشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص220، تحت عنوان «دلالة التعبير بالمصدر ﴿ضبحًا﴾»","url":""}]},{"id":"s100-12","number":12,"surah":100,"verses":[1],"references":[{"surah":100,"verses":[1]}],"verseLabel":"العاديات: 1","question":"ما الذي يضيفه تنكير ﴿ضَبْحًا﴾؟","answer":"يفخم ذلك الصوت ويعظّم شأنه، فيوحي بضبح شديد متميز يناسب قوة العدو وهول المشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص221، تحت عنوان «نكتة تنكير ﴿ضبحًا﴾»","url":""}]},{"id":"s100-3","number":3,"surah":100,"verses":[2],"references":[{"surah":100,"verses":[2]}],"verseLabel":"العاديات: 2","question":"لماذا خُصَّ قدح الشرر بالذكر في قوله ﴿فَالْمُورِيَاتِ قَدْحًا﴾؟","answer":"لأنه أثر محسوس من شدة عدو الخيل واصطكاك حوافرها بالحجارة؛ فيحوّل سرعتها وقوتها إلى صورة مضيئة حية تمهّد للإغارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص223، تحت عنوان «دلالة تخصيص وصف (الإيراء) بالذكر»","url":""}]},{"id":"s100-4","number":4,"surah":100,"verses":[3],"references":[{"surah":100,"verses":[3]}],"verseLabel":"العاديات: 3","question":"ما مناسبة الإغارة ﴿صُبْحًا﴾؟","answer":"تقييد الإغارة بالصبح يستحضر وقت المباغتة وأخذ العدو على غرة، حين يغلب السكون والغفلة. وفي هذا التعيين إبراز لشدة وقع الإغارة وتمكن المغيرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص228–229، تحت عنوان «نكتة التعبير بظرف الزمان ﴿صبحًا﴾ منكرًا»","url":""}]},{"id":"s100-5","number":5,"surah":100,"verses":[4,5],"references":[{"surah":100,"verses":[4,5]}],"verseLabel":"العاديات: 4–5","question":"ما أثر الانتقال من أوصاف الخيل إلى الفعل الماضي في ﴿فَأَثَرْنَ بِهِ نَقْعًا﴾؟","answer":"ينقل المشهد من صفات ثابتة إلى أفعال متحققة متتابعة، فيستحضر الإغارة وإثارة الغبار كأنهما تقعان أمام السامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص231، تحت عنوان «بلاغة الالتفات من اسم الفاعل إلى الفعل الماضي»","url":""}]},{"id":"s100-13","number":13,"surah":100,"verses":[4,5],"references":[{"surah":100,"verses":[4,5]}],"verseLabel":"العاديات: 4–5","question":"ماذا تصوّر عبارة ﴿فَوَسَطْنَ بِهِ جَمْعًا﴾؟","answer":"تصوّر الخيل وقد اقتحمت قلب جمع العدو، لا أنها وقفت عند أطرافه؛ فهي كناية عن الجرأة وشدة الإقدام وبلوغ الغاية في الهجوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص237، تحت عنوان «دلالة الكناية في ﴿فوسطن به جمعًا﴾»","url":""}]},{"id":"s100-6","number":6,"surah":100,"verses":[6],"references":[{"surah":100,"verses":[6]}],"verseLabel":"العاديات: 6","question":"لماذا توالت المؤكدات في قوله ﴿إِنَّ الْإِنْسَانَ لِرَبِّهِ لَكَنُودٌ﴾؟","answer":"لتثبيت حقيقة جحود الإنسان وتغليظ التوبيخ عليها، بعد مشهد الخيل المطيعة الباذلة؛ فالمقام يواجه غفلته عن حقيقة ظاهرة لكنه يجادل فيها أو يتناساها.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص241، تحت عنوان «بلاغة توالي التوكيدات»","url":""}]},{"id":"s100-14","number":14,"surah":100,"verses":[6],"references":[{"surah":100,"verses":[6]}],"verseLabel":"العاديات: 6","question":"ما الذي يبلغه وصف الإنسان بأنه ﴿كَنُودٌ﴾؟","answer":"يدل على رسوخ جحوده وكثرته وتكرره؛ فهو لا يغفل عن نعمة واحدة فحسب، بل يشتد منه كفران النعم وتعداد المصائب مع نسيان الإحسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص244، تحت عنوان «دلالة صوغ (كنود) على (فعول)»","url":""}]},{"id":"s100-7","number":7,"surah":100,"verses":[7],"references":[{"surah":100,"verses":[7]}],"verseLabel":"العاديات: 7","question":"من الشاهد على كنود الإنسان في قوله ﴿وَإِنَّهُ عَلَى ذَلِكَ لَشَهِيدٌ﴾؟","answer":"يحتمل أن يعود إلى الإنسان، فهو يشهد على كنوده بما يعرفه من نفسه وما يظهر في عمله؛ ويحتمل أن يعود إلى الله، فيكون وعيدًا بشهادته المحيطة على جحود الإنسان. وكلا الوجهين يقيم الحجة عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص246–247، تحت عنوان «بلاغة عود الضمير في (إنه)»","url":""}]},{"id":"s100-15","number":15,"surah":100,"verses":[7],"references":[{"surah":100,"verses":[7]}],"verseLabel":"العاديات: 7","question":"لماذا عُبّر عن العلم بالجحود بلفظ ﴿شَهِيدٌ﴾؟","answer":"ليصوّر الجحود أمرًا حاضرًا مكشوفًا تقوم عليه الشهادة، لا خاطرًا خفيًا يمكن إنكاره؛ فاللفظ يقوي ثبوت الحجة وظهور الحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص250، تحت عنوان «دلالة الاستعارة التبعية في (شهيد)»","url":""}]},{"id":"s100-8","number":8,"surah":100,"verses":[8],"references":[{"surah":100,"verses":[8]}],"verseLabel":"العاديات: 8","question":"لماذا سمّت الآية المال ﴿الْخَيْرِ﴾ في قوله ﴿لِحُبِّ الْخَيْرِ لَشَدِيدٌ﴾؟","answer":"لما في المال من منافع ولأن الناس يرونه خيرًا محبوبًا؛ فالذم ليس لذات المال، وإنما لما يطغى من التعلق به حتى يشغل عن حق المنعم والإنفاق في وجوه الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص254، تحت عنوان «دلالة العدول عن المال إلى الخير»","url":""}]},{"id":"s100-16","number":16,"surah":100,"verses":[8],"references":[{"surah":100,"verses":[8]}],"verseLabel":"العاديات: 8","question":"ما الذي يكشفه وصف الإنسان بأنه لحب الخير ﴿لَشَدِيدٌ﴾؟","answer":"يكشف أن حب المال قوي راسخ فيه، حتى يصير تعلقًا غالبًا يحمله على الإمساك والغفلة، لا مجرد ميل عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص256، تحت عنوان «دلالة صوغ (شديد) على (فعيل)»","url":""}]},{"id":"s100-9","number":9,"surah":100,"verses":[9,10],"references":[{"surah":100,"verses":[9,10]}],"verseLabel":"العاديات: 9–10","question":"ما التدرج في بعثرة القبور وتحصيل الصدور؟","answer":"تقابل الآيتان إظهار ما في القبور بإظهار ما في الصدور: أجساد مستورة تبعث، ونيات وأعمال باطنة تجمع وتميز للجزاء. فالقبور أوعية الأجساد والصدور أوعية الأسرار، ويجمع المشهدان كشف المستور.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص271–272، تحت عنوان «دلالة التقابل بين ﴿بعثر﴾ و(حصل) و﴿القبور﴾ و﴿الصدور﴾»","url":""}]},{"id":"s100-10","number":10,"surah":100,"verses":[11],"references":[{"surah":100,"verses":[11]}],"verseLabel":"العاديات: 11","question":"لماذا قُيّدت خبرة الله بقوله ﴿يَوْمَئِذٍ﴾ مع أن علمه محيط في كل وقت؟","answer":"ليس المراد أن علمه يبدأ يوم القيامة، بل أن أثر علمه يظهر يومئذ في المحاسبة والجزاء وكشف ما في الصدور؛ فتقديم الظرف يركز القلب على ذلك المآل.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص276–277، تحت عنوان «فائدة القيد ﴿يومئذ﴾ وتقديمه»","url":""}]},{"id":"s100-17","number":17,"surah":100,"verses":[11],"references":[{"surah":100,"verses":[11]}],"verseLabel":"العاديات: 11","question":"ماذا يضيف وصف الله بـ﴿خَبِيرٌ﴾ في ختام سورة العاديات؟","answer":"يؤكد إحاطته الدقيقة بظواهر الأعمال وبواطنها، وأن الجزاء يصدر عن علم تام لا تخفى عليه نية ولا خبيئة؛ ولذلك يختم الوعيد ويوقظ للمحاسبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص278، تحت عنوان «بلاغة الكناية في لفظ (خبير)»","url":""}]},{"id":"s101-1","number":1,"surah":101,"verses":[1,2,3],"references":[{"surah":101,"verses":[1,2,3]}],"verseLabel":"القارعة: 1–3","question":"لماذا تكرر اسم ﴿الْقَارِعَةُ﴾ بدل إعادته بضمير؟","answer":"إعادة الاسم تثبّت الحدث في النفس وتزيد تهويله، فكل مرة يطرق اللفظ السمع من جديد كما تقرع القارعة القلوب. ولو قيل «ما هي» لفات هذا التصوير والتفخيم المتتابع.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص289، تحت عنوان «سر تكرار لفظ ﴿القارعة﴾»","url":""}]},{"id":"s101-2","number":2,"surah":101,"verses":[1],"references":[{"surah":101,"verses":[1]}],"verseLabel":"القارعة: 1","question":"ما دلالة اسم ﴿الْقَارِعَةُ﴾؟","answer":"القرع في الأصل ضرب شديد، ونقل الاسم إلى القيامة لما تحدثه من فزع يقرع القلوب والأسماع. والتأنيث يناسب وصفها بالحادثة العظيمة، مع المبالغة في شدتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص289–290، تحت عنوان «بلاغة المجاز في لفظ ﴿القارعة﴾ وتأنيثها»","url":""}]},{"id":"s101-3","number":3,"surah":101,"verses":[4],"references":[{"surah":101,"verses":[4]}],"verseLabel":"القارعة: 4","question":"لماذا شُبّه الناس يوم القيامة بالفراش؟","answer":"لأن الفراش يجتمع كثيرًا ثم يتحرك في جهات متفرقة بلا انتظام، ضعيفًا مضطربًا يصطدم بعضه ببعض. فتجعل الصورة كثرة الناس وحيرتهم وفقدانهم الاتجاه مشهدًا محسوسًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص297، تحت عنوان «دلالة تعريف (الفراش) وجمعه»","url":""}]},{"id":"s101-9","number":9,"surah":101,"verses":[4],"references":[{"surah":101,"verses":[4]}],"verseLabel":"القارعة: 4","question":"ما الذي يزيده وصف الفراش بأنه ﴿مَبْثُوثٍ﴾؟","answer":"يؤكد أنهم منتشرون متفرقون في كل جهة، كأن قوة هائلة نثرتهم فلم يبق لهم نظام يجمعهم. ويستحضر الوصف اضطراب لحظة البعث واستمرار الحركة والحيرة في أرض المحشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص297–298، تحت عنوان «سر وصف الفراش باسم المفعول (مبثوث)»","url":""}]},{"id":"s101-4","number":4,"surah":101,"verses":[5],"references":[{"surah":101,"verses":[5]}],"verseLabel":"القارعة: 5","question":"ما الذي يضيفه وصف العهن بأنه ﴿الْمَنْفُوشِ﴾؟","answer":"النفش يفكك الصوف ويفرق أجزاؤه حتى يغدو خفيفًا واهيًا، وكذلك تصير الجبال بعد رسوخها. فيبرز الوصف تمام انهيار بنيتها وسهولة تناثرها في ذلك اليوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص300، تحت عنوان «سر وصف (العهن) باسم المفعول (منفوش)»","url":""}]},{"id":"s101-5","number":5,"surah":101,"verses":[6,7,8,9],"references":[{"surah":101,"verses":[6,7,8,9]}],"verseLabel":"القارعة: 6–9","question":"كيف تجعل المقابلة بين ﴿ثَقُلَتْ مَوَازِينُهُ﴾ و﴿خَفَّتْ مَوَازِينُهُ﴾ عدل الجزاء محسوسًا؟","answer":"تجعل الأعمال كأن لها وزنًا يرفع صاحبها أو يهوي به؛ فالثقل يقود إلى عيشة راضية، والخفة إلى الهاوية. ويبرز الطباق تباعد المصيرين وارتباط كل منهما بما قدم الإنسان من عمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص310، تحت عنوان «بلاغة الطباق بين ﴿ثقلت﴾ و﴿خفت﴾»","url":""}]},{"id":"s101-6","number":6,"surah":101,"verses":[7],"references":[{"surah":101,"verses":[7]}],"verseLabel":"القارعة: 7","question":"لماذا وصفت العيشة بأنها ﴿رَاضِيَةٍ﴾؟","answer":"من وجوه التعبير أن «راضية» بمعنى مرضية لصاحبها، أو أن الرضا أسند إلى العيشة مجازًا والمراد أهلها. ويصورها أيضًا كأنها راضية بهم؛ وكل ذلك يبالغ في تمام النعيم والرضا.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص309، تحت عنوان «بلاغة المجاز في وصف الحياة بـ﴿راضية﴾»","url":""}]},{"id":"s101-7","number":7,"surah":101,"verses":[9],"references":[{"surah":101,"verses":[9]}],"verseLabel":"القارعة: 9","question":"ما الصورة في ﴿فَأُمُّهُ هَاوِيَةٌ﴾؟","answer":"على وجه الاستعارة، الأم هي المأوى الذي يرجع إليه، وقد جعل مأواه الهاوية في صورة مفزعة تقابل ما ينتظر من الأم من الحماية. وقيل إن المراد أم رأسه، أي يهوي على رأسه؛ وتذكر الموسوعة الوجهين.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص311، تحت عنوان «بلاغة التعبير بالتركيب ﴿فأمه هاوية﴾ بين التشبيه والاستعارة»","url":""}]},{"id":"s101-8","number":8,"surah":101,"verses":[10,11],"references":[{"surah":101,"verses":[10,11]}],"verseLabel":"القارعة: 10–11","question":"لماذا أعيد سؤال ﴿وَمَا أَدْرَاكَ مَا هِيَهْ﴾ قبل بيان الهاوية؟","answer":"أعيد الاستفهام لتعظيم شأن الهاوية والتشويق إلى معرفة حقيقتها، مع الإيحاء بأن هولها فوق ما يبلغه إدراك المخاطب حتى يأتي البيان من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص315–316، تحت عنوان «سر تكرار الاستفهام ﴿ما﴾»","url":""}]},{"id":"s101-10","number":10,"surah":101,"verses":[1,3],"references":[{"surah":101,"verses":[1,3]}],"verseLabel":"القارعة: 1، 3","question":"ما سر إعادة لفظ «القارعة» في قوله تعالى: ﴿الْقَارِعَةُ * مَا الْقَارِعَةُ * وَمَا أَدْرَاكَ مَا الْقَارِعَةُ﴾؟","answer":"قد يعاد المبتدأ بلفظه، وأكثر ما يقع ذلك في مقام التهويل والتفخيم، كما تقول: زيد ما زيد؟ أي: أي شيء هو، تفخيمًا له. فأعاد لفظ القارعة ولم يأت بالضمير تفخيمًا لأمرها وتهويلًا، وهو من التكرير للتعظيم والتهويل.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج1، ص179؛ لمسات بيانية، ص249.","url":""}]},{"id":"s102-1","number":1,"surah":102,"verses":[1],"references":[{"surah":102,"verses":[1]}],"verseLabel":"التكاثر: 1","question":"ما سرّ التعبير بقوله تعالى ﴿أَلْهَاكُمُ التَّكَاثُرُ﴾ مع عدم ذكر المتكاثَر فيه؟","answer":"حذف المتكاثر به يعمم الذم في كل ما يتباهى به الناس من مال أو جاه أو ولد إذا شغلهم عن طاعة الله. فلا ينحصر التحذير في نوع واحد من حظوظ الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص328–329، تحت عنوان «سر حذف المتكاثر به»","url":""}]},{"id":"s102-2","number":2,"surah":102,"verses":[1],"references":[{"surah":102,"verses":[1]}],"verseLabel":"التكاثر: 1","question":"ماذا يصور اختيار ﴿أَلْهَاكُمُ﴾ بدل «شغلكم»؟","answer":"يصور انصرافًا وغفلةً عما ينبغي الاهتمام به، لا مجرد انشغال محايد؛ وجاء بالماضي إشعارًا بأن هذا اللهو قد وقع واستحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص326، تحت عنوان «سر التعبير بالفعل ﴿ألهاكم﴾ دلالة وصيغة»","url":""}]},{"id":"s102-8","number":8,"surah":102,"verses":[1],"references":[{"surah":102,"verses":[1]}],"verseLabel":"التكاثر: 1","question":"ما الفرق بين التكاثر والكثرة؟","answer":"الكثرة وفرة في العدد، أما التكاثر فيصور تنافس الناس ومباهاتهم بأن يكون بعضهم أكثر من بعض؛ لذلك انصب الذم على التفاخر الملهي لا على مجرد كثرة الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص328، تحت عنوان «سر استعمال مادة التكاثر وصوغها على وزن (تفاعل)»","url":""}]},{"id":"s102-3","number":3,"surah":102,"verses":[2],"references":[{"surah":102,"verses":[2]}],"verseLabel":"التكاثر: 2","question":"ما الصورة في ﴿حَتَّى زُرْتُمُ الْمَقَابِرَ﴾؟","answer":"من وجوه التعبير بلوغ القبور بالموت، وسميت الإقامة فيها زيارة لأنها مؤقتة يعقبها البعث. ومن وجوهه زيارة المقابر للتفاخر بالأموات وعدهم؛ فالصورة تذم امتداد التكاثر حتى هذه الغاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص330–331، تحت عنوان «سر التعبير بالفعل ﴿زرتم﴾ دلالة وصيغة»","url":""}]},{"id":"s102-4","number":4,"surah":102,"verses":[3,4],"references":[{"surah":102,"verses":[3,4]}],"verseLabel":"التكاثر: 3–4","question":"ماذا أضافت ﴿ثُمَّ﴾ إلى الوعيد الثاني في ﴿ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ﴾؟","answer":"رقّت بالتهديد إلى مرتبة أشد، فالوعيد الثاني أعظم وقعًا من الأول، وقيل يميز بين انكشاف العاقبة في القبر ثم عند البعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص337، تحت عنوان «وجه العطف بـ﴿ثم﴾»","url":""}]},{"id":"s102-9","number":9,"surah":102,"verses":[3,4],"references":[{"surah":102,"verses":[3,4]}],"verseLabel":"التكاثر: 3–4","question":"لماذا تكررت جملة ﴿كَلَّا سَوْفَ تَعْلَمُونَ﴾؟","answer":"لتوكيد الزجر وتغليظ التخويف، حتى تستقل كل مرة بتهديد خاص ويتيقن السامع أن ما وُعد به واقع لا محالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص337، تحت عنوان «بلاغة تكرار جملة ﴿كلا سوف تعلمون﴾»","url":""}]},{"id":"s102-5","number":5,"surah":102,"verses":[5],"references":[{"surah":102,"verses":[5]}],"verseLabel":"التكاثر: 5","question":"ما دلالة ﴿لَوْ تَعْلَمُونَ عِلْمَ الْيَقِينِ﴾؟","answer":"حذف جواب «لو» يترك للسامع تقدير أثر اليقين في ترك التكاثر والإلهاء، نحو: لو علمتم لانشغلتم بما ينفعكم. وعدم التصريح به يزيد التهويل ويجعل الذهن يستحضر عظم ما كان ينبغي أن يتغير.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص340–341، تحت عنوان «بلاغة حذف جواب ﴿لو﴾»","url":""}]},{"id":"s102-6","number":6,"surah":102,"verses":[6,7],"references":[{"surah":102,"verses":[6,7]}],"verseLabel":"التكاثر: 6–7","question":"لماذا تكرر الوعيد بالرؤية في ﴿لَتَرَوُنَّ الْجَحِيمَ ثُمَّ لَتَرَوُنَّهَا﴾؟","answer":"لتصعيد الوعيد من عرض الجحيم ومشاهدتها إلى معاينتها ومباشرة عذابها؛ فالتكرار يحقق الخبر ويزيد المشهد تهويلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص345، تحت عنوان «سر تكرار الفعل (لترون)»","url":""}]},{"id":"s102-10","number":10,"surah":102,"verses":[6,7],"references":[{"surah":102,"verses":[6,7]}],"verseLabel":"التكاثر: 6–7","question":"ماذا تفيد إضافة ﴿عَيْنَ﴾ إلى ﴿الْيَقِينِ﴾؟","answer":"تفيد أن الرؤية تبلغ أقصى درجات التحقق: مشاهدةً عيانية لا يبقى معها ظن ولا شبهة، فيتحول الوعيد إلى مشهد محسوس.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص345، تحت عنوان «دلالة تعريف ﴿عين﴾ بالإضافة»","url":""}]},{"id":"s102-7","number":7,"surah":102,"verses":[8],"references":[{"surah":102,"verses":[8]}],"verseLabel":"التكاثر: 8","question":"ما الذي يشمله ﴿النَّعِيمِ﴾ الذي يُسأل عنه الإنسان؟","answer":"يشمل ما أنعم الله به عليه في الدنيا مما يلائمه ويتمتع به، فيسأل عن شكره وصرفه؛ وقيل يتوجه أيضًا إلى نعيم الجنة على وجه التقريع للكافرين والتشريف للمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص348–349، تحت عنوان «دلالة تعريف ﴿النعيم﴾»","url":""}]},{"id":"s102-11","number":11,"surah":102,"verses":[8],"references":[{"surah":102,"verses":[8]}],"verseLabel":"التكاثر: 8","question":"كيف أعاد ختام السورة قارئها إلى مطلعها؟","answer":"افتتحت بذم التكاثر الذي ألهى الناس، وختمت بسؤالهم عن النعيم الذي تكاثروا فيه ولم يشكروه؛ فحوّلت ما عدوه موضع فخر إلى موضع حساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص349، تحت عنوان «بلاغة مناسبة آخر السورة لأولها»","url":""}]},{"id":"s103-1","number":1,"surah":103,"verses":[1],"references":[{"surah":103,"verses":[1]}],"verseLabel":"العصر: 1","question":"لماذا أقسم الله بالعصر؟","answer":"لأن الزمن ميدان عمل الإنسان وربحه وخسرانه، وفي تقلبه وانقضاء أجزائه عبرة تشهد بقدرة الله وتوقظ إلى أن ما فات منه لا يعود.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص359–360، تحت عنوان «نكتة القسم بالعصر»","url":""}]},{"id":"s103-7","number":7,"surah":103,"verses":[1],"references":[{"surah":103,"verses":[1]}],"verseLabel":"العصر: 1","question":"ما المعاني التي يحتملها لفظ ﴿الْعَصْرِ﴾؟","answer":"يحتمل الدهر كله، أو وقت العصر وصلاته، أو عصر النبوة؛ وتجتمع هذه الأوجه في التنويه بزمن تتجلى فيه العبر وتُوزن فيه الأعمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص360–361، تحت عنوان «معنى تعريف لفظ (العصر)»","url":""}]},{"id":"s103-2","number":2,"surah":103,"verses":[2],"references":[{"surah":103,"verses":[2]}],"verseLabel":"العصر: 2","question":"لماذا توالت المؤكدات في ﴿إِنَّ الْإِنْسَانَ لَفِي خُسْرٍ﴾؟","answer":"جاء القسم و﴿إن﴾ واللام والجملة الاسمية لتثبيت حقيقة يغفل عنها الناس: أن العمر ينقص بلا توقف، فلا ينجو صاحبه إلا بالعمل الذي استثنته السورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص363، تحت عنوان «نكتة توالي المؤكدات في جملة جواب القسم»","url":""}]},{"id":"s103-8","number":8,"surah":103,"verses":[2],"references":[{"surah":103,"verses":[2]}],"verseLabel":"العصر: 2","question":"كيف يصور حرف ﴿فِي﴾ إحاطة الخسر بالإنسان؟","answer":"يجعل الخسر كأنه ظرف يحيط بالإنسان من كل جهة، فيصوّر ملازمته له واستغراقه فيه ما لم يحقق صفات النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص365، تحت عنوان «بلاغة استعمال حرف الظرفية: ﴿لفي خسر﴾»","url":""}]},{"id":"s103-3","number":3,"surah":103,"verses":[2],"references":[{"surah":103,"verses":[2]}],"verseLabel":"العصر: 2","question":"لماذا قيل ﴿الْإِنْسَانَ﴾ لا «الناس»؟","answer":"ليتوجه الحكم إلى الجنس من خلال كل فرد؛ فيرى كل إنسان خسرانه الخاص في عمره وعمله، ثم يظهر أن النجاة لا تكون بمجرد الانتماء إلى جماعة بل بتحقق الصفات المذكورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص364–365، تحت عنوان «سر إيثار التعبير بقوله: ﴿الإنسان﴾ دون (الناس)»","url":""}]},{"id":"s103-4","number":4,"surah":103,"verses":[3],"references":[{"surah":103,"verses":[3]}],"verseLabel":"العصر: 3","question":"لماذا رُتب الإيمان ثم العمل الصالح ثم التواصي؟","answer":"لأن الإيمان أصل يحمل على العمل، والعمل الصالح يزكي صاحبه، ثم يتعدى الخير بالتواصي إلى إصلاح الآخرين؛ فتنتقل النجاة من صلاح النفس إلى التعاون على صلاح المجتمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص374–375، تحت عنوان «بلاغة ترتيب المذكور: الإيمان، فالعمل، فالتواصي»","url":""}]},{"id":"s103-5","number":5,"surah":103,"verses":[3],"references":[{"surah":103,"verses":[3]}],"verseLabel":"العصر: 3","question":"ما الفرق بين فعل الخير والتواصي به؟","answer":"العمل الصالح فعل الإنسان للخير، أما التواصي فيفيد المشاركة: يوصي بعضهم بعضًا بالحق ويقبلون الوصية. فينتقل الخير من سلوك الفرد إلى تعاون الجماعة على التذكير والثبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص376–377، تحت عنوان «دلالة التعبير بقوله تعالى: ﴿وتواصوا﴾ من حيث مادته وصيغته»","url":""}]},{"id":"s103-6","number":6,"surah":103,"verses":[3],"references":[{"surah":103,"verses":[3]}],"verseLabel":"العصر: 3","question":"لماذا خُص الحق والصبر بالتواصي؟","answer":"لأن الحق يجمع ما ينبغي معرفته والعمل به، والصبر يحفظ ملازمته أمام الهوى والمشقة والأذى؛ فبهما يستقيم طريق الإصلاح ويستمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص380–381، تحت عنوان «توجيه تخصيص التواصي بالحق والصبر»","url":""}]},{"id":"s103-9","number":9,"surah":103,"verses":[2,3],"references":[{"surah":103,"verses":[2,3]}],"verseLabel":"العصر: 2–3","question":"ما دلالة التعبير بـ«خُسْر» في قوله تعالى: ﴿إِنَّ الْإِنسَانَ لَفِي خُسْرٍ﴾؟","answer":"استعمل القرآن «الخسر» لعموم الخسارة قليلة كانت أو كثيرة، فهو لمطلق الخسارة. وقد ذكر أن الإنسان واقع فيه، ولم يستثن إلا من جمع أربع صفات: الإيمان والعمل الصالح والتواصي بالحق والتواصي بالصبر؛ فمن نقص في صفة أصابه من الخسر بقدر ذلك، والخسارة الكبرى لمن فقدها جميعًا.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص12.","url":""}]},{"id":"s104-1","number":1,"surah":104,"verses":[1],"references":[{"surah":104,"verses":[1]}],"verseLabel":"الهمزة: 1","question":"لماذا قيل ﴿هُمَزَةٍ لُمَزَةٍ﴾ بلا عطف بين الصفتين؟","answer":"لأن الصفتين اجتمعتا في شخص واحد حتى صارتا كأنهما وصف مركب له: يعيب الناس ويحتقرهم بوجوه شتى، خفية وظاهرة. وحذف العطف يقوي تلازم الخصلتين ويشدد الوعيد على من اتخذهما عادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص396–397، تحت عنوان «علة ترك عطف اللمزة على الهمزة»","url":""}]},{"id":"s104-2","number":2,"surah":104,"verses":[1],"references":[{"surah":104,"verses":[1]}],"verseLabel":"الهمزة: 1","question":"لماذا نُكّر ﴿هُمَزَةٍ لُمَزَةٍ﴾ بعد ﴿كُلِّ﴾؟","answer":"دخول «كل» على الوصف المفرد المنكر يوجه الوعيد إلى كل فرد اتصف بالهمز واللمز. فيشمل الحكم الأشخاص على اختلاف أحوالهم، ويقرر أن لكل منهم جزاءه بحسب فعله.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص394، تحت عنوان «غرض استعمال لفظ العموم (كل) دون أن يقال: (ويل للهامزين اللامزين)»","url":""}]},{"id":"s104-3","number":3,"surah":104,"verses":[2],"references":[{"surah":104,"verses":[2]}],"verseLabel":"الهمزة: 2","question":"ماذا يكشف مشهد ﴿جَمَعَ مَالًا وَعَدَّدَهُ﴾ عن صاحبه؟","answer":"يكشف أن المال استولى على نفسه: يجمعه ثم يعود إلى عده مرة بعد مرة، تلذذًا بكثرته واطمئنانًا إليه واستعدادًا للزيادة. فليس الإحصاء حاجة عابرة، بل انشغال مستمر ومباهاة وحرص لا يشبع.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص400، تحت عنوان «بلاغة التصوير للمشهد النفسي في عطف (عدده) على ﴿جمع﴾»","url":""}]},{"id":"s104-4","number":4,"surah":104,"verses":[3],"references":[{"surah":104,"verses":[3]}],"verseLabel":"الهمزة: 3","question":"ما سرّ التعبير بالماضي في ﴿يَحْسَبُ أَنَّ مَالَهُ أَخْلَدَهُ﴾؟","answer":"نزل المستقبل المتوهم منزلة الماضي المحقق، فكأن المال قد حصل له الخلود بالفعل. وفي ذلك تصوير لرسوخ غروره وسخرية من اطمئنانه إلى ما لا يملك له البقاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص406–407، تحت عنوان «نكتة التعبير بصيغة الماضي ﴿أخلده﴾ دون المستقبل»","url":""}]},{"id":"s104-5","number":5,"surah":104,"verses":[4],"references":[{"surah":104,"verses":[4]}],"verseLabel":"الهمزة: 4","question":"لماذا جاء الردع بـ﴿كَلَّا﴾ فجأة بعد ظنه أن ماله يخلده؟","answer":"لتقطع الوهم قطعًا حاسمًا قبل تفصيل العقوبة: المال لا يمنع الموت ولا يهب الخلود. والمفاجأة في ﴿كلا﴾ تهدم ثقته الزائفة وتوقظه على المصير الذي كان جمع المال يحجبه عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص407–408، تحت عنوان «بلاغة الردع المفاجئ بأداة ﴿كلا﴾»","url":""}]},{"id":"s104-10","number":10,"surah":104,"verses":[4],"references":[{"surah":104,"verses":[4]}],"verseLabel":"الهمزة: 4","question":"لماذا قيل ﴿لَيُنْبَذَنَّ﴾ لا «ليدخلن» الحطمة؟","answer":"النبذ طرح الشيء باحتقار ومن غير اعتداد به، فيصور إهانة المتكبر الذي كان يرى لنفسه منزلة بماله. وكما همز الناس ولمزهم يُلقى في النار إلقاء ما لا كرامة له.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص409، تحت عنوان «بلاغة استعمال مفردة النبذ»","url":""}]},{"id":"s104-6","number":6,"surah":104,"verses":[4],"references":[{"surah":104,"verses":[4]}],"verseLabel":"الهمزة: 4","question":"لماذا سميت النار ﴿الْحُطَمَةِ﴾؟","answer":"الحطمة من الحطم، وهو الكسر الشديد، وصيغتها تبالغ في وصف النار بتحطيم ما يلقى فيها. وتناسب مادتها وصيغتها الهمزة اللمزة الذي يكسر أعراض الناس بالطعن، فتبرز مناسبة الجزاء للعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص411–412، تحت عنوان «براعة استعمال مفردة ﴿الحطمة﴾ مادة وصيغة»","url":""}]},{"id":"s104-7","number":7,"surah":104,"verses":[5,6],"references":[{"surah":104,"verses":[5,6]}],"verseLabel":"الهمزة: 5–6","question":"ماذا تضيف نسبة النار إلى الله في قوله ﴿نَارُ اللَّهِ﴾؟","answer":"تضيف تعظيمًا وتهويلًا؛ فهي نار أعدها الله لعقاب من استحقها، لا نارًا من النيران التي يوقدها البشر ويملكون إخمادها. والنسبة إلى الله تستحضر كمال قدرته وشدة ما أعده من الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص417، تحت عنوان «دلالة إضافة لفظ النار إلى الاسم الأحسن ﴿الله﴾ في ﴿نار الله الموقدة﴾»","url":""}]},{"id":"s104-11","number":11,"surah":104,"verses":[5,6],"references":[{"surah":104,"verses":[5,6]}],"verseLabel":"الهمزة: 5–6","question":"لماذا وُصفت نار الله بأنها ﴿الْمُوقَدَةُ﴾ مع أن النار لا تكون إلا موقدة؟","answer":"للدلالة على أنها في اشتعال دائم متجدد لا يخبو ولا ينقطع، وأن إيقادها من الله لا يحتاج إلى وقود البشر. فالوصف لا يكرر معنى النار فقط، بل يؤكد دوام حرها وقوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص417–418، تحت عنوان «بلاغة وصف النار بـ﴿الموقدة﴾، والنار لا تكون إلا موقدة»","url":""}]},{"id":"s104-8","number":8,"surah":104,"verses":[7],"references":[{"surah":104,"verses":[7]}],"verseLabel":"الهمزة: 7","question":"لماذا خُصت ﴿الْأَفْئِدَةِ﴾ باطلاع النار عليها؟","answer":"لأن الأفئدة موضع النيات والمقاصد التي خرج منها الكبر والهمز واللمز وسائر أعمال الفجور. فيطابق العذاب باطن الجريمة؛ فلا تقف النار عند ظاهر الأجساد، بل تنفذ إلى أعمق موضع في الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص421–422، تحت عنوان «بلاغة استعمال الأفئدة دون الصدور أو القلوب»","url":""}]},{"id":"s104-9","number":9,"surah":104,"verses":[8,9],"references":[{"surah":104,"verses":[8,9]}],"verseLabel":"الهمزة: 8–9","question":"ما الصورة التي تضيفها ﴿فِي عَمَدٍ مُمَدَّدَةٍ﴾ إلى إغلاق النار؟","answer":"تحتمل أن تكون عمدًا تمد على الأبواب فتزيدها إحكامًا، أو قيودًا وأعمدة يوثق بها المعذبون؛ وعلى الوجهين تكتمل صورة الحبس الذي لا منفذ منه. فلا يلزم حصر الآية في هيئة واحدة ما دام الجامع تشديد الإطباق.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص426–427، تحت عنوان «التوجيه النحوي والبياني لقوله تعالى: ﴿في عمد ممددة﴾»","url":""}]},{"id":"s104-12","number":12,"surah":104,"verses":[1,8,9],"references":[{"surah":104,"verses":[1,8,9]}],"verseLabel":"الهمزة: 1، 8، 9","question":"ما سر وصف النار بقوله: ﴿إِنَّهَا عَلَيْهِم مُّؤْصَدَةٌ * فِي عَمَدٍ مُّمَدَّدَةٍ﴾ في الهمزة، مع الاقتصار على ﴿عَلَيْهِمْ نَارٌ مُّؤْصَدَةٌ﴾ في البلد؟","answer":"بدأ السورة بقوله: ﴿وَيْلٌ لِّكُلِّ هُمَزَةٍ لُّمَزَةٍ﴾، ورفعُ «الويل» يفيد الثبوت والهلاك الدائم، فناسب ذلك الدلالة على الاستيثاق من غلق الأبواب بمدّ الأعمدة عليها. ثم إن هذا الكافر جمع المال وعدّده وأغلق عليه واستوثق من حفظه، فأُغلقت عليه أبواب جهنم واستوثق منها، والجزاء من جنس العمل؛ أما صاحب البلد فقد أهلك ماله وأنفقه. وتوسّع في صفات المعذَّب هنا فتوسّع في ذكر عذابه.","sources":[{"label":"فاضل السامرائي، لمسات بيانية، ص280–282.","url":""}]},{"id":"s105-1","number":1,"surah":105,"verses":[1],"references":[{"surah":105,"verses":[1]}],"verseLabel":"الفيل: 1","question":"كيف قيل للنبي ﷺ ﴿أَلَمْ تَرَ﴾ حادثة الفيل مع أنه لم يشهدها؟","answer":"الرؤية هنا علمية؛ لكن شهرة الحادثة وتواتر خبرها جعلا العلم بها في قوة المشاهدة، فخوطب بها كأنها منظر حاضر لا مجال للشك فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص442، تحت عنوان «نوع الرؤية في ﴿ألم تر﴾ وغرض التعبير بها»","url":""}]},{"id":"s105-8","number":8,"surah":105,"verses":[1],"references":[{"surah":105,"verses":[1]}],"verseLabel":"الفيل: 1","question":"لماذا توجه السؤال إلى كيفية فعل الله بأصحاب الفيل؟","answer":"للدعوة إلى تأمل هيئة الفعل العجيبة لا مجرد معرفة وقوع الهلاك؛ فقد أبطل الله جيشًا عظيمًا بطير وحجارة على صورة خارقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص442–443، تحت عنوان «دلالة تسليط الاستفهام حول الكيفية»","url":""}]},{"id":"s105-2","number":2,"surah":105,"verses":[1],"references":[{"surah":105,"verses":[1]}],"verseLabel":"الفيل: 1","question":"لماذا قيل ﴿فَعَلَ رَبُّكَ﴾ لا «فعل الله»؟","answer":"لأن عنوان الربوبية يستحضر التربية والرعاية والعناية؛ فحماية البيت من آثار تدبير الرب وحفظه، وفيه تأنيس للنبي ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص444، تحت عنوان «بلاغة التعبير بعنوان الربوبية دون الألوهية»","url":""}]},{"id":"s105-3","number":3,"surah":105,"verses":[2],"references":[{"surah":105,"verses":[2]}],"verseLabel":"الفيل: 2","question":"ماذا تصور ﴿فِي﴾ في قوله ﴿جَعَلَ كَيْدَهُمْ فِي تَضْلِيلٍ﴾؟","answer":"تصور كيدهم محاطًا بالإبطال والضياع كأنه غارق فيه لا يستطيع الخروج منه؛ فلا يصل تدبيرهم إلى غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص449–450، تحت عنوان «بلاغة استعمال حرف الظرفية»","url":""}]},{"id":"s105-9","number":9,"surah":105,"verses":[2],"references":[{"surah":105,"verses":[2]}],"verseLabel":"الفيل: 2","question":"ما الصورة في كلمة ﴿تَضْلِيلٍ﴾ عند وصف كيد أصحاب الفيل؟","answer":"استعير التضليل لإبطال الكيد وإبعاده عن طريق النجاح، فكأن تدبيرهم ضل وجهته وتاه عن مقصده حتى صار سبب هلاكهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص450، تحت عنوان «بلاغة الاستعارة في لفظ ﴿تضليل﴾»","url":""}]},{"id":"s105-4","number":4,"surah":105,"verses":[3],"references":[{"surah":105,"verses":[3]}],"verseLabel":"الفيل: 3","question":"ماذا توحي الكلمة الغريبة ﴿أَبَابِيلَ﴾ في مشهد الطير؟","answer":"توحي بجماعات كثيرة متتابعة تأتي فوجًا بعد فوج من جهات شتى؛ وغرابة اللفظ تلائم غرابة المشهد الذي باغت الجيش.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص455، تحت عنوان «دلالة استعمال اللفظ الغريب ﴿أبابيل﴾»","url":""}]},{"id":"s105-5","number":5,"surah":105,"verses":[4],"references":[{"surah":105,"verses":[4]}],"verseLabel":"الفيل: 4","question":"ماذا يفيد تنكير ﴿حِجَارَةٍ﴾ في عذاب أصحاب الفيل؟","answer":"يفيد التهويل والتعظيم؛ فهي حجارة مجهولة لهم في حقيقتها وأثرها، صغيرة في حجمها لكنها تنفذ بإذن الله وتحدث هلاكًا عظيمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص459، تحت عنوان «نكتة تنكير (حجارة)»","url":""}]},{"id":"s105-10","number":10,"surah":105,"verses":[4],"references":[{"surah":105,"verses":[4]}],"verseLabel":"الفيل: 4","question":"ماذا تضيف كلمة ﴿سِجِّيلٍ﴾ إلى وصف الحجارة؟","answer":"تميزها بأنها حجارة عذاب مقدرة ومسجلة، وتوحي بكثرتها وتتابعها؛ فلم تكن حجارة عارضة بل عقوبة مهيأة تصيب أهدافها.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص460، تحت عنوان «دلالة التعبير بمفردة ﴿سجيل﴾ على تقدير العذاب وكثرته»","url":""}]},{"id":"s105-6","number":6,"surah":105,"verses":[5],"references":[{"surah":105,"verses":[5]}],"verseLabel":"الفيل: 5","question":"ما الذي تصوره عبارة ﴿كَعَصْفٍ مَأْكُولٍ﴾ من مصير أصحاب الفيل؟","answer":"تشبه أجسادهم بعد الهلاك ببقايا الزرع المفتت؛ فتجمع الصورة التمزق والحقارة وزوال القوة بعد ما كانوا جيشًا مرهوبًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص461–462، تحت عنوان «دلالة كاف التشبيه في ﴿كعصف مأكول﴾»","url":""}]},{"id":"s105-11","number":11,"surah":105,"verses":[5],"references":[{"surah":105,"verses":[5]}],"verseLabel":"الفيل: 5","question":"لماذا وُصف العصف في التشبيه بأنه ﴿مَأْكُولٍ﴾؟","answer":"لزيادة تصوير التفتت والتبعثر؛ فهو كقشر الزرع الذي أكلت الدواب حبه أو مضغته ثم تركت فضلاته، فلا يبقى فيه تماسك ولا قوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص463، تحت عنوان «بلاغة وصف العصف بأنه مأكول في تشبيه مهلك القوم»","url":""}]},{"id":"s105-7","number":7,"surah":105,"verses":[1,2,3,4,5],"references":[{"surah":105,"verses":[1,2,3,4,5]}],"verseLabel":"الفيل: 1–5","question":"كيف صنعت سورة الفيل مشهدًا متحركًا من الطير والحجارة والهلاك؟","answer":"وصلت عناصر الصورة في تتابع سريع: طير جماعات، وحجارة مسجلة، ورمي يعقبه تحول الجيش إلى عصف مأكول؛ فتبدو قدرة الله في مشهد حي متكامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص464، تحت عنوان «بلاغة تصوير مشهد الطير والحجارة والهلاك»","url":""}]},{"id":"s106-1","number":1,"surah":106,"verses":[1,2],"references":[{"surah":106,"verses":[1,2]}],"verseLabel":"قريش: 1–2","question":"لماذا تكرر لفظ ﴿إِيلَافِ﴾ في مطلع سورة قريش؟","answer":"ليُفصّل الثاني ما أجمله الأول، فيبين أن الإيلاف المقصود هو رحلة الشتاء والصيف، وليزيد العناية بهذه النعمة ويثبت عظمها في النفس تمهيدًا للدعوة إلى شكر المنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص482، تحت عنوان «فائدة تكرار لفظ الإيلاف»","url":""}]},{"id":"s106-3","number":3,"surah":106,"verses":[2],"references":[{"surah":106,"verses":[2]}],"verseLabel":"قريش: 2","question":"لماذا قيل ﴿رِحْلَةَ الشِّتَاءِ وَالصَّيْفِ﴾ بالإفراد مع أنهما رحلتان؟","answer":"لأن الرحلة اسم جنس يشمل رحلتي الموسمين، ولأنهما متحدتان في الغرض وهو التجارة، فكأنهما رحلة واحدة متكررة. ويجوز تقدير المحذوف: رحلة الشتاء ورحلة الصيف.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص483–484، تحت عنوان «نكتة إفراد ﴿رحلة﴾ دون تثنيتها»","url":""}]},{"id":"s106-4","number":4,"surah":106,"verses":[3],"references":[{"surah":106,"verses":[3]}],"verseLabel":"قريش: 3","question":"ما دلالة الفاء في ﴿فَلْيَعْبُدُوا﴾؟","answer":"الفاء تربط الأمر بالعبادة بالنعمة السابقة، ومن توجيهها أنها في جواب شرط مقدر: إن لم يعبدوه لغيرها فليعبدوه لأجل هذا الإيلاف. فتظهر استحقاق المنعم للشكر والعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص486، تحت عنوان «نوع الفاء ودلالتها»","url":""}]},{"id":"s106-5","number":5,"surah":106,"verses":[3],"references":[{"surah":106,"verses":[3]}],"verseLabel":"قريش: 3","question":"لماذا دُعيت قريش إلى عبادة ﴿رَبَّ هَذَا الْبَيْتِ﴾؟","answer":"لأن وصف الربوبية يستحضر تربيته وإنعامه ورعايته، ويذكّر قريشًا بأن الذي حفظ البيت ورزق أهله وأمّنهم هو وحده المستحق للعبادة، لا الأصنام المحيطة به.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص487، تحت عنوان «دلالة التعبير بلفظ الربوبية»","url":""}]},{"id":"s106-9","number":9,"surah":106,"verses":[3],"references":[{"surah":106,"verses":[3]}],"verseLabel":"قريش: 3","question":"ما أثر الإشارة القريبة في قوله ﴿هَذَا الْبَيْتِ﴾؟","answer":"تستحضر البيت الحرام المشاهد المعهود أمام قريش، فتجعل الحجة أقرب إلى حسهم: هذا البيت الذي يعرفون حرمته وأمنه شاهد حاضر على نعمة ربه ووجوب عبادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص488، تحت عنوان «دلالة استعمال اسم الإشارة القريب»","url":""}]},{"id":"s106-6","number":6,"surah":106,"verses":[4],"references":[{"surah":106,"verses":[4]}],"verseLabel":"قريش: 4","question":"ما الذي تبرزه المقابلة بين ﴿أَطْعَمَهُمْ مِنْ جُوعٍ﴾ و﴿آمَنَهُمْ مِنْ خَوْفٍ﴾؟","answer":"تبرز انتقال قريش من ضدين يهدمان الحياة، الجوع والخوف، إلى أصلي استقامتها، الشبع والأمن؛ فتتجلى النعمتان معًا ويقوى استحقاق المنعم للشكر والعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص492، تحت عنوان «بلاغة التناسب في فن الطباق»","url":""}]},{"id":"s106-7","number":7,"surah":106,"verses":[4],"references":[{"surah":106,"verses":[4]}],"verseLabel":"قريش: 4","question":"ما دلالة تنكير ﴿جُوعٍ﴾ و﴿خَوْفٍ﴾؟","answer":"تذكر الموسوعة للتنكير وجه التكثير باعتبار تعدد ما دفع عنهم من جوع وخوف، ووجه التعظيم باعتبار شدتهما. فاللفظ ينوه بعظم النعمة في دفع الحاجة والخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص491، تحت عنوان «غرض تنكير لفظي ﴿جوع﴾ و﴿خوف﴾»","url":""}]},{"id":"s106-8","number":8,"surah":106,"verses":[1],"references":[{"surah":105,"verses":[4]},{"surah":106,"verses":[1]}],"verseLabel":"قريش: الفيل–قريش","question":"كيف تتصل سورة قريش بسورة الفيل؟","answer":"تروي سورة الفيل حماية البيت من المعتدين، ثم تبيّن سورة قريش ما أثمرته هذه الحماية لأهله من الإيلاف والرزق والأمن؛ فتتتابع نعم الحفظ والمعاش لتقود إلى عبادة رب البيت.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص473، تحت عنوان «ارتباط سورة قريش بسورة الفيل على قول»","url":""}]},{"id":"s106-10","number":10,"surah":106,"verses":[1,3],"references":[{"surah":106,"verses":[1,3]}],"verseLabel":"قريش: 1، 3","question":"ما سر تقديم ﴿لِإِيلَافِ قُرَيْشٍ﴾ على متعلَّقه ﴿فَلْيَعْبُدُوا﴾؟","answer":"له فوائد: فهو يوسّع المعنى فيحتمل التعلق بـ«فليعبدوا» أو بمضمر تقديره «اعجبوا»، ويقوّي الربط بسورة الفيل حتى كأنهما سورة واحدة، ويفيد أهمية هذا الإيلاف في حياتهم. وهو من تقديم العلة على الفعل، فذكر ما يستدعي العبادة أولًا ثم طلبها، كما في الفاتحة. ولو أُخّر لامتنعت الفاء ولاحتمل تعلّقه بـ«أطعمهم» فيذهب المعنى.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص100–102.","url":""}]},{"id":"s106-11","number":11,"surah":106,"verses":[1,2],"references":[{"surah":106,"verses":[1,2]}],"verseLabel":"قريش: 1–2","question":"ما سر إطلاق «الإيلاف» أولًا ثم إبدال ﴿إِيلَافِهِمْ رِحْلَةَ الشِّتَاءِ وَالصَّيْفِ﴾ منه، وإفراد «رحلة»؟","answer":"أطلق الإيلاف ثم أبدل منه المقيّد بالرحلتين تفخيمًا لأمره وتذكيرًا بعظيم النعمة فيه، وهذا التوجيه منقول عن «الكشاف». وأفرد «رحلة» والمراد رحلتان لأمن اللبس، ولأنه لو قال «رحلتي الشتاء والصيف» لأوهم أن في الشتاء رحلتين وفي الصيف رحلتين.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص102.","url":""}]},{"id":"s106-12","number":12,"surah":106,"verses":[3],"references":[{"surah":106,"verses":[3]}],"verseLabel":"قريش: 3","question":"ما سر إضافة الرب إلى البيت والمجيء باسم الإشارة في ﴿رَبَّ هَٰذَا الْبَيْتِ﴾ دون «ربهم»؟","answer":"الرحلتان إنما نجحتا واستمرتا بسبب هذا البيت، وربّ البيت هو الذي يحميه وقد فعل بأصحاب الفيل ما فعل. ولو قال «ربهم الذي أطعمهم» لم يدلّ على خصوص قريش، لأن الله أطعم خلقًا كثيرًا. واسم الإشارة عيّن البيت تعيينًا لا لبس فيه، واختيار «الرب» أنسب لأنه الذي يرعى مربوبه فيطعمه إذا جاع ويؤمنه إذا خاف.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص102–104.","url":""}]},{"id":"s106-13","number":13,"surah":106,"verses":[4],"references":[{"surah":106,"verses":[4]}],"verseLabel":"قريش: 4","question":"ما سر قوله: ﴿أَطْعَمَهُم مِّن جُوعٍ﴾ دون «أشبعهم»، وتنكير «جوع» و«خوف»؟","answer":"الشبع قد يورث البطنة والتخمة، أما الإطعام فيزيل الجوع، وخير الطعام ما سدّ الجوعة. ولم يكتف بـ«أطعمهم» لأن من الإطعام ما لا يسدّ الجوعة، فقال «من جوع» لتكون النعمة أتم. ونكّر الجوع والخوف لإطلاقهما فيشملان كل جوع وخوف، ولو عرّفهما لاحتمل العهد، وقيل التنكير للتعظيم. وفي «التفسير الكبير» نحو هذا.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص105.","url":""}]},{"id":"s106-14","number":14,"surah":106,"verses":[4],"references":[{"surah":106,"verses":[4]}],"verseLabel":"قريش: 4","question":"ما سر تقديم الجوع على الخوف هنا، مع تقديم الخوف في آية البقرة؟","answer":"الجوع أشدّ لأنه إذا استمر أهلك، والإطعام هو الغرض من الرحلتين والأمن سبب نجاحهما، وقريش في بلد غير ذي زرع. وهو مناسب لتقديم الشتاء على الصيف، لأن الحاجة إلى الطعام في الشتاء أشدّ ودواعي الإخافة في الصيف أكثر. أما آية البقرة ففي سياق القتل والمصائب فناسب تقديم الخوف.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص105–107.","url":""}]},{"id":"s107-1","number":1,"surah":107,"verses":[1],"references":[{"surah":107,"verses":[1]}],"verseLabel":"الماعون: 1","question":"ما أثر افتتاح السورة بالاستفهام ﴿أَرَأَيْتَ﴾؟","answer":"يوقظ الذهن ويشوّق إلى معرفة حال المكذب، ثم يحمل على التعجب من اجتماع إنكار الجزاء مع قسوة السلوك؛ فكأن السامع مدعو إلى أن يشاهد هذه الحال ويحكم عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص504–505، تحت عنوان «بلاغة الاستفهام وغرضه»","url":""}]},{"id":"s107-10","number":10,"surah":107,"verses":[1],"references":[{"surah":107,"verses":[1]}],"verseLabel":"الماعون: 1","question":"لماذا عُبر عن المكذب بالدين بالاسم الموصول؟","answer":"لتكون صلته هي العلة التي يُعرف بها ويُتعجب من آثارها، فتتعلق العبرة بوصف التكذيب لا بشخص معين، ويشمل الحكم كل من اتصف به.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص506، تحت عنوان «نكتة التعبير بالاسم الموصول»","url":""}]},{"id":"s107-2","number":2,"surah":107,"verses":[2],"references":[{"surah":107,"verses":[2]}],"verseLabel":"الماعون: 2","question":"ما دلالة ﴿يَدُعُّ الْيَتِيمَ﴾؟","answer":"الدع دفع شديد بعنف، فيصور إهانة اليتيم وزجره عن حقه أو حاجته. واختيار اللفظ يكشف قسوة المعاملة واستغلال ضعف من لا يستطيع دفع الأذى عن نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص509، تحت عنوان «بلاغة استعمال مفردة (الدع) مادة وصيغة»","url":""}]},{"id":"s107-3","number":3,"surah":107,"verses":[3],"references":[{"surah":107,"verses":[3]}],"verseLabel":"الماعون: 3","question":"ما سرّ التعبير بقوله ﴿لَا يَحُضُّ عَلَى طَعَامِ الْمِسْكِينِ﴾؟","answer":"ذم ترك الحض يبين أن المعروف لا يقتصر على أن يطعم المرء بنفسه، بل يشمل حث غيره. وهو أبلغ في تصوير البخل: فمن أمسك حتى عن الحث كان أبعد عن البذل، مع أن الحث لا يتوقف على امتلاك المال.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص511، تحت عنوان «بلاغة الكناية في ترك الحض»","url":""}]},{"id":"s107-4","number":4,"surah":107,"verses":[3],"references":[{"surah":107,"verses":[3]}],"verseLabel":"الماعون: 3","question":"لماذا أضيف الطعام إلى المسكين؟","answer":"من أوجه الإضافة أن الطعام حق للمسكين، فترك إعطائه منع لحقه. وفي هذا التعبير توبيخ للبخيل؛ إذ يستأثر بما للمحتاج فيه نصيب مستحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص513، تحت عنوان «نوع الإضافة ودلالتها»","url":""}]},{"id":"s107-5","number":5,"surah":107,"verses":[4],"references":[{"surah":107,"verses":[4]}],"verseLabel":"الماعون: 4","question":"لماذا قطع سرد الصفات بالوعيد ﴿فَوَيْلٌ لِلْمُصَلِّينَ﴾؟","answer":"ليوقف السامع عند خطورة الصفات بدل أن تمر في سرد متتابع، وليظهر أن مجرد صورة الصلاة لا تمنع الوعيد حين يقترن بها السهو والرياء ومنع المعروف.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص515–516، تحت عنوان «نكتة ترك سرد الصفات وإيراد لفظ (ويل)»","url":""}]},{"id":"s107-11","number":11,"surah":107,"verses":[4],"references":[{"surah":107,"verses":[4]}],"verseLabel":"الماعون: 4","question":"ماذا يفيد وصف المستحقين للويل بـ﴿الَّذِينَ هُمْ عَنْ صَلَاتِهِمْ سَاهُونَ﴾؟","answer":"يربط الوعيد بعلته، فيبين أن الذم ليس لمطلق المصلين بل لمن ثبت منهم الإعراض عن الصلاة والتفريط في حقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص517، تحت عنوان «دلالة الاسم الموصول»","url":""}]},{"id":"s107-6","number":6,"surah":107,"verses":[5],"references":[{"surah":107,"verses":[5]}],"verseLabel":"الماعون: 5","question":"ما الفرق بين السهو عن الصلاة والسهو فيها؟","answer":"التعدية بـ«عن» تدل على الإعراض وعدم الاعتداد بالصلاة والتفريط فيها. أما السهو العارض في أثناء الصلاة فليس هو المقصود بهذا الوصف؛ فالفرق بين الغفلة عنها والخطأ غير المقصود داخلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص517–518، تحت عنوان «نكتة التعدية بحرف ﴿عن﴾ دون (في)»","url":""}]},{"id":"s107-7","number":7,"surah":107,"verses":[6],"references":[{"surah":107,"verses":[6]}],"verseLabel":"الماعون: 6","question":"كيف يصور ﴿يُرَاءُونَ﴾ عبادةً تتجدد لأجل أنظار الناس؟","answer":"يصوّر المضارع رياءً يتجدد، وتكشف المفاعلة أن العمل يُعرض على الناس طلبًا لنظرهم وثنائهم؛ فظاهر العبادة متعلق بالخلق لا بالخالق.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص520–521، تحت عنوان «بلاغة التعبير بصيغة المضارع والمفاعلة»","url":""}]},{"id":"s107-8","number":8,"surah":107,"verses":[7],"references":[{"surah":107,"verses":[7]}],"verseLabel":"الماعون: 7","question":"ما سعة ﴿الْمَاعُونَ﴾؟","answer":"تذكر الموسوعة للماعون معنى ما ينتفع به الناس على العموم، أو المال والزكاة، أو الأدوات اليسيرة التي يتعاونون بإعارتها. وعلى الوجه الأخير يشتد ذم البخل لأنهم يمنعون ما يسهل بذله من المعروف.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص523–524، تحت عنوان «معنى تعريف لفظ ﴿الماعون﴾»","url":""}]},{"id":"s107-9","number":9,"surah":107,"verses":[1,2,3,4,5,6,7],"references":[{"surah":107,"verses":[1,2,3,4,5,6,7]}],"verseLabel":"الماعون: 1–7","question":"ما الرابط بين دع اليتيم وترك الحض على طعام المسكين؟","answer":"كلاهما ثمرة لقسوة القلب الناشئة عن التكذيب بالجزاء: الأول اعتداء على الضعيف، والثاني امتناع حتى عن الحث على سد حاجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص510، تحت عنوان «مناسبة العطف ودلالته»","url":""}]},{"id":"s107-12","number":12,"surah":107,"verses":[1,2,3,4,5,6,7],"references":[{"surah":107,"verses":[1,2,3,4,5,6,7]}],"verseLabel":"الماعون: 1–7","question":"كيف تربط الفاء بين التكذيب بالدين والوعيد للمصلين؟","answer":"تجعل الوعيد وما بعده متفرعًا على صفات المكذب السابقة، فتقرر أن السهو والرياء ليسا منفصلين عن فساد الاعتقاد والسلوك، بل من آثارهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص514–515، تحت عنوان «نوع الفاء ودلالتها الارتباطية بالسابق»","url":""}]},{"id":"s107-13","number":13,"surah":107,"verses":[1,2,3,4,5,6,7],"references":[{"surah":107,"verses":[1,2,3,4,5,6,7]}],"verseLabel":"الماعون: 1–7","question":"ماذا يضيف ﴿وَيَمْنَعُونَ الْمَاعُونَ﴾ بعد وصفهم بالرياء؟","answer":"يكشف أن إظهارهم الخير لا يصحبه بذل حقيقي؛ فهم يطلبون ثناء الناس بالعبادة الظاهرة ثم يمنعون عنهم أيسر المنافع، فتكتمل صورة التناقض.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص522، تحت عنوان «بلاغة الاحتراس في العطف»","url":""}]},{"id":"s108-1","number":1,"surah":108,"verses":[1],"references":[{"surah":108,"verses":[1]}],"verseLabel":"الكوثر: 1","question":"لماذا افتتحت سورة الكوثر بجملة مؤكدة؟","answer":"لتقرير العطاء العظيم وتثبيت بشارته في قلب النبي ﷺ، والرد على من أنكر فضله أو زعم انقطاع ذكره.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص537، تحت عنوان «بلاغة افتتاح السورة بالتوكيد»","url":""}]},{"id":"s108-9","number":9,"surah":108,"verses":[1],"references":[{"surah":108,"verses":[1]}],"verseLabel":"الكوثر: 1","question":"ماذا يضيف ضمير الجمع في ﴿إِنَّا أَعْطَيْنَاكَ﴾؟","answer":"يعظّم شأن المعطي سبحانه، ومن ثم يعظّم المنحة ويطمئن النبي ﷺ إلى أن وراءها قدرة لا يحدها شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص537، تحت عنوان «نكتة التعبير بضمير الجمع»","url":""}]},{"id":"s108-2","number":2,"surah":108,"verses":[1],"references":[{"surah":108,"verses":[1]}],"verseLabel":"الكوثر: 1","question":"ما دلالة اختيار ﴿أَعْطَيْنَاكَ﴾ لا «آتيناك»؟","answer":"تذكر الموسوعة أن الإعطاء أنسب هنا لإبراز التفضل والإنعام، في حين يحتمل الإيتاء في أصل الاستعمال ما يكون واجبًا أو فضلًا. فاختيار «أعطيناك» يبرز أن الكوثر منحة عظيمة تفضل الله بها على نبيه ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص538، تحت عنوان «بلاغة التعبير بمفردة (الإعطاء) دون (الإيتاء)»","url":""}]},{"id":"s108-3","number":3,"surah":108,"verses":[1],"references":[{"surah":108,"verses":[1]}],"verseLabel":"الكوثر: 1","question":"ماذا أفاد تعريف ﴿الْكَوْثَرَ﴾؟","answer":"يحتمل العهد إلى النهر الموعود في الجنة، ويحتمل استغراق جنس الخير الكثير؛ فيجمع ما خص به النبي ﷺ من نهر وقرآن ونبوة وذكر وفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص540–541، تحت عنوان «معنى تعريف لفظ ﴿الكوثر﴾»","url":""}]},{"id":"s108-10","number":10,"surah":108,"verses":[1],"references":[{"surah":108,"verses":[1]}],"verseLabel":"الكوثر: 1","question":"لماذا اختير لفظ ﴿الْكَوْثَرَ﴾ للتعبير عن عطاء النبي ﷺ؟","answer":"لأن مادته وصيغته تدلان على الخير البالغ في الكثرة، حتى صار اللفظ الوجيز جامعًا لفيض العطاء وتنوع وجوهه.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص541، تحت عنوان «بلاغة التعبير بالكوثر مادة وصيغة»","url":""}]},{"id":"s108-4","number":4,"surah":108,"verses":[2],"references":[{"surah":108,"verses":[2]}],"verseLabel":"الكوثر: 2","question":"لماذا قُدّمت الصلاة على النحر؟","answer":"لأن الصلاة أعظم منزلة وأعم تكررًا، وهي صلة العبد بربه وأسبق في استحقاق الذكر من عبادة النحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص543، تحت عنوان «غرض تقديم الأمر بالصلاة على الأمر بالنحر»","url":""}]},{"id":"s108-11","number":11,"surah":108,"verses":[2],"references":[{"surah":108,"verses":[2]}],"verseLabel":"الكوثر: 2","question":"ماذا أضاف عطف النحر على الصلاة؟","answer":"جمع وجهي الشكر: العبادة البدنية في الصلاة والبذل المالي في النحر، ورد العبادة كلها إلى الله وحده خلافًا للمشركين.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص546، تحت عنوان «نكتة عطف الأمر بالنحر على الأمر بالصلاة»","url":""}]},{"id":"s108-5","number":5,"surah":108,"verses":[2],"references":[{"surah":108,"verses":[2]}],"verseLabel":"الكوثر: 2","question":"كيف دل قوله ﴿لِرَبِّكَ﴾ على إخلاص الصلاة والنحر لله وحده؟","answer":"أفادت اختصاص الصلاة والنحر بالله وإخلاصهما له وحده، تعريضًا بمن كان يصلي أو يذبح لغيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص544، تحت عنوان «نوع اللام ودلالتها»","url":""}]},{"id":"s108-12","number":12,"surah":108,"verses":[2],"references":[{"surah":108,"verses":[2]}],"verseLabel":"الكوثر: 2","question":"لماذا قيل ﴿لِرَبِّكَ﴾ باسم الربوبية؟","answer":"ليذكّر النبي ﷺ بأن من رباه وأنعم عليه بالكوثر هو المستحق للشكر والعبادة، وفي الإضافة تشريف وعناية خاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص545، تحت عنوان «بلاغة التعبير بعنوان الربوبية»","url":""}]},{"id":"s108-6","number":6,"surah":108,"verses":[3],"references":[{"surah":108,"verses":[3]}],"verseLabel":"الكوثر: 3","question":"كيف حصر قوله ﴿إِنَّ شَانِئَكَ هُوَ الْأَبْتَرُ﴾ الانقطاع في مبغض النبي ﷺ؟","answer":"أكد بضمير الفصل أن المنقطع حقيقةً عن الخير والذكر الحسن هو الشانئ نفسه، فردّ دعوى البتر إلى قائلها وثبّت للنبي ﷺ دوام الذكر والفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص550، تحت عنوان «فائدة التعبير بضمير الفصل»","url":""}]},{"id":"s108-7","number":7,"surah":108,"verses":[3],"references":[{"surah":108,"verses":[3]}],"verseLabel":"الكوثر: 3","question":"ما الفرق بين «مبغضك» و﴿شَانِئَكَ﴾؟","answer":"الشنء أخص من مطلق البغض؛ فهو بغض مع كراهة وتقبيح، قد يحمل صاحبه على الاجتناب والازدراء. لذلك يلائم وصف من تجاوز مجرد البغض إلى إظهار العيب والعداوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص555، تحت عنوان «الشنء والبغض والعداوة»","url":""}]},{"id":"s108-8","number":8,"surah":108,"verses":[1,2,3],"references":[{"surah":108,"verses":[1,2,3]}],"verseLabel":"الكوثر: 1–3","question":"كيف تقابل أول السورة وآخرها؟","answer":"يقابل الكوثر، بما يدل عليه من كثرة الخير للنبي ﷺ، الأبتر الذي انقطع شانئه عن الخير والذكر الحسن. فتؤكد النهاية ما قرره المطلع من العطاء، وترد قول العدو عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص553–554، تحت عنوان «دلالة المقابلة الضدية بين (﴿الكوثر﴾ و﴿الأبتر﴾)»","url":""}]},{"id":"s108-13","number":13,"surah":108,"verses":[1,3],"references":[{"surah":108,"verses":[1,3]}],"verseLabel":"الكوثر: 1، 3","question":"ما سر إسناد الإعطاء إلى الله تعالى وعدم إسناد البتر إليه في السورة؟","answer":"قال ﴿إِنَّا أَعْطَيْنَاكَ﴾ ولم يقل «وجعلنا شانئك هو الأبتر»، بل أسند البتر إلى الشانئ نفسه، فهو أبتر من غير جعل جاعل وذلك وصفه هو، وهذا أذمّ له وأقبح. وبهذا ارتبط آخر السورة بأولها: أعطى نبيه الكوثر، ومبغضه مقطوع من كل خير.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص96–97.","url":""}]},{"id":"s108-14","number":14,"surah":108,"verses":[1,3],"references":[{"surah":108,"verses":[1,3]}],"verseLabel":"الكوثر: 1، 3","question":"ما سر مناسبة سورة الكوثر لسورة الماعون قبلها؟","answer":"هي كالمقابلة لها: ففي مقابل البخل في الماعون ﴿إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ﴾، وفي مقابل السهو عن الصلاة ﴿فَصَلِّْ﴾، وفي مقابل الرياء ﴿لِرَبِّكَ﴾، وفي مقابل منع الماعون ﴿وَانْحَرْ﴾. وفي مقابل التكذيب بالدين ذكر الكوثر، لأن من أشهر معانيه نهر في الجنة، وهذا يقتضي الإيمان بيوم الدين.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص75–76.","url":""}]},{"id":"s108-15","number":15,"surah":108,"verses":[2],"references":[{"surah":108,"verses":[2]}],"verseLabel":"الكوثر: 2","question":"ما سر الالتفات في ﴿فَصَلِّ لِرَبِّكَ﴾ بعد ﴿إِنَّا أَعْطَيْنَاكَ﴾، دون «فصلّ لنا»؟","answer":"أفاد أن الصلاة تكون للرب وحده لا للمعطي على الإطلاق، فالمعطي يستحق الشكر ولا يستحق الصلاة إلا الله، ورفع توهم أن «نا» ضمير اشتراك لا ضمير عظمة. واختيار «الرب» لما فيه من معنى التربية والعناية المناسب للعطاء، وإضافته إلى ضمير الخطاب تكريم. وفي «التفسير الكبير» نحو هذا.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص86–87، 93.","url":""}]},{"id":"s108-16","number":16,"surah":108,"verses":[2],"references":[{"surah":108,"verses":[2]}],"verseLabel":"الكوثر: 2","question":"ما سر التعبير بـ﴿وَانْحَرْ﴾ دون «اذبح» أو «ضَحّ» أو «آتِ الزكاة»؟","answer":"النحر خاص بالإبل وهي أعزّ أموال العرب، فناسب العطاءَ الكثير أن يتصدق بالكثير شكرًا، والذبح والتضحية عامّان يجزئ فيهما الشاة. والضحية مختصة بأيام الأضحى والنحر مطلق. ولو قال «وآتِ الزكاة» لما اختلف عن أمر عامة المسلمين فلا يكون شكرًا خاصًّا على الكوثر. وفي «التفسير الكبير» نحو هذا.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص88–90.","url":""}]},{"id":"s108-17","number":17,"surah":108,"verses":[3],"references":[{"surah":108,"verses":[3]}],"verseLabel":"الكوثر: 3","question":"ما سر التعبير بـ«الأبتر» دون «المبتور»، وبـ«شانئ» في قراءة الجمهور؟","answer":"«الأبتر» صفة دالة على الثبوت كالأسمر والأعمى، بخلاف «المبتور» الدال على الحدوث. وقراءة الجمهور «شانئك» أولى من «شَنِئك»؛ لأن «شَنِئ» صيغة مبالغة تجعل البتر للمبالغ في البغض، أما «شانئك» فيدل على أن المبغض أبتر مهما قلّ بغضه أو كثر.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص95.","url":""}]},{"id":"s108-18","number":18,"surah":108,"verses":[1],"references":[{"surah":108,"verses":[1]}],"verseLabel":"الكوثر: 1","question":"ما سر توكيد الجملة بـ«إن» وإسناد الفعل إلى ضمير العظمة في ﴿إِنَّا أَعْطَيْنَاكَ﴾؟","answer":"بناء الفعل على الضمير المتقدم يفيد الاختصاص والاهتمام، وإسناده إلى ضمير التعظيم مع توكيده يفيد أنه لا يستطيع أحد أن ينزع هذا العطاء منه. والعطاء الكثير جدًا الممتد من الدنيا إلى الآخرة يقتضي التوكيد وتعظيم معطيه، فاجتمع أعظم معطٍ وأعظم عطاء.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص77، 84.","url":""}]},{"id":"s108-19","number":19,"surah":108,"verses":[1],"references":[{"surah":108,"verses":[1]}],"verseLabel":"الكوثر: 1","question":"ما دلالة التعبير بالماضي «أعطيناك» دون «سنعطيك»؟","answer":"فيه إشارة إلى تحقق الوقوع وأن ذلك كائن لا محالة، وقيل يدل على أن هذا الإعطاء حاصل في الماضي، وقيل هو إشارة إلى تعظيم الإعطاء. ويجوز أن يكون إشارة إلى عطاء بدأ وهو مستمر لا ينقطع إلى الآخرة.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص81.","url":""}]},{"id":"s108-20","number":20,"surah":108,"verses":[1],"references":[{"surah":108,"verses":[1]}],"verseLabel":"الكوثر: 1","question":"ما سر التعبير بـ«الكوثر» دون «الكثير»؟","answer":"«الكوثر» يجمع معنيين: الكثرة والخير، فهو الخير الكثير، ويكون صفة ويكون ذاتًا موصوفة بكثرة الخير كالنهر الموعود. أما «الكثير» فيفيد الكثرة فقط غير محددة بشيء، ولذلك يقال: رجل كوثر وتسكت، ولا يقال: رجل كثير حتى تقول: كثير الخير. وحذف الموصوف للإطلاق.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص83–84.","url":""}]},{"id":"s109-1","number":1,"surah":109,"verses":[1],"references":[{"surah":109,"verses":[1]}],"verseLabel":"الكافرون: 1","question":"لماذا افتتحت سورة المفاصلة بالأمر ﴿قُلْ﴾؟","answer":"ليظهر أن هذا الموقف ليس اجتهادًا شخصيًا من النبي ﷺ، بل إعلان مأمور به من الله يجب تبليغه بلا مواربة. كما يجعله جوابًا علنيًا حاسمًا عن عرض المساومة في العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص564–565، تحت عنوان «دلالة الافتتاح بفعل (القول)»","url":""}]},{"id":"s109-8","number":8,"surah":109,"verses":[1],"references":[{"surah":109,"verses":[1]}],"verseLabel":"الكافرون: 1","question":"لماذا وُوجه المخاطبون بوصف ﴿الْكَافِرُونَ﴾ صراحة؟","answer":"لأن كفرهم هو سبب استحالة الاتفاق معهم على معبود أو عبادة مشتركة، ولأن الخطاب يتجه إلى قوم معلومين أصروا على المساومة. فالوصف يكشف حقيقة الخلاف بدل أن يغطيها بلفظ ملطف.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص566–567، تحت عنوان «دلالة التعريف بـ(أل) في ﴿الكافرون﴾»","url":""}]},{"id":"s109-2","number":2,"surah":109,"verses":[2,3,4,5],"references":[{"surah":109,"verses":[2,3,4,5]}],"verseLabel":"الكافرون: 2–5","question":"لماذا تكرر نفي المشاركة في العبادة أربع مرات؟","answer":"ليغلق باب المساومة في كل زمن: لا تقع المشاركة الآن ولا تنتظر مستقبلًا، من النبي ﷺ ولا من أولئك المخاطبين. فالتقابل بين الجمل الفعلية والاسمية يقرر ثبات المفاصلة ويمنع حمل الكلام على رفض مؤقت.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص581–582، تحت عنوان «نكتة التقابل الزمني في الآيات الأربع»","url":""}]},{"id":"s109-3","number":3,"surah":109,"verses":[2,4],"references":[{"surah":109,"verses":[2,4]}],"verseLabel":"الكافرون: 2، 4","question":"ما الفرق بين ﴿لَا أَعْبُدُ﴾ و﴿وَلَا أَنَا عَابِدٌ﴾؟","answer":"تنفي الجملة الفعلية وقوع العبادة، أما الجملة الاسمية فتنفي اتصاف النبي ﷺ بكونه عابدًا لما يعبدون وتثبت موقفه. فالتنويع يقوي النفي من جهة الفعل ومن جهة الصفة، ويمنع توهم أنه موقف عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص576، تحت عنوان «علاقة الجملة الاسمية بالجملة الفعلية ﴿لا أعبد﴾»","url":""}]},{"id":"s109-4","number":4,"surah":109,"verses":[2,3],"references":[{"surah":109,"verses":[2,3]}],"verseLabel":"الكافرون: 2–3","question":"هل تشير ﴿مَا﴾ في ﴿مَا تَعْبُدُونَ﴾ إلى المعبود أم إلى طريقة العبادة؟","answer":"تحتمل أن تكون موصولة فيكون النفي متعلقًا بالمعبود، وأن تكون مصدرية فينفي مماثلة طريقة العبادة أيضًا. ويجمع الاحتمالان أن التوحيد لا يلتقي بالشرك لا فيمن يُعبد ولا في الكيفية التي يتقرب بها العابد.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص573، تحت عنوان «سر التعبير بـ﴿ما﴾، والغرض منها»","url":""}]},{"id":"s109-5","number":5,"surah":109,"verses":[3,5],"references":[{"surah":109,"verses":[3,5]}],"verseLabel":"الكافرون: 3، 5","question":"لماذا أعيدت جملة ﴿وَلَا أَنْتُمْ عَابِدُونَ مَا أَعْبُدُ﴾ بلفظها؟","answer":"لتؤكد أن نفي عبادتهم لله على الوجه الحق ثابت في الحال ومستمر في الاستقبال بالنسبة إلى أولئك المخاطبين، فلا يكون التكرار حشوًا. كما يثبت الجملة في موقعها مقابل نفي عبادة النبي ﷺ لمعبوداتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص579، تحت عنوان «دلالة الجملة على التوكيد للمدلول أو الموقع»","url":""}]},{"id":"s109-6","number":6,"surah":109,"verses":[6],"references":[{"surah":109,"verses":[6]}],"verseLabel":"الكافرون: 6","question":"هل تعني ﴿لَكُمْ دِينُكُمْ وَلِيَ دِينِ﴾ إقرارًا بصحة الدينين؟","answer":"لا؛ فالواو تجمع الطرفين في الكلام لكنها لا تجمعهما في الحق، بل تؤكد أن لكل فريق طريقًا متميزًا لا يمكن التوفيق بينه وبين الآخر. فالآية إعلان براءة من المساومة، لا تصحيح للشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص585، تحت عنوان «دلالة (الواو) في ﴿ولي﴾ والغرض منها»","url":""}]},{"id":"s109-7","number":7,"surah":109,"verses":[6],"references":[{"surah":109,"verses":[6]}],"verseLabel":"الكافرون: 6","question":"ما الذي يفيده تقديم ﴿لَكُمْ﴾ و﴿لِيَ﴾ في ختام السورة؟","answer":"يفيد الاختصاص والمفاصلة: دينكم لكم لا أشارككم فيه، وديني لي لا تشاركونني فيه على طريقتكم. فيغلق التقديم باب الخلط الذي اقترحوه ويجعل الحدود بين التوحيد والشرك واضحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص584، تحت عنوان «دلالة تقديم الجار والمجرور ﴿لكم﴾»","url":""}]},{"id":"s109-9","number":9,"surah":109,"verses":[6],"references":[{"surah":109,"verses":[6]}],"verseLabel":"الكافرون: 6","question":"ما سر حذف ياء المتكلم في ﴿وَلِيَ دِينِ﴾ مع إثباتها في آية الزمر: ﴿قُلِ اللَّهَ أَعْبُدُ مُخْلِصًا لَّهُ دِينِي﴾؟","answer":"سورة الكافرون مبنية على النفي والترك، أي عدم حصول الشيء، والحذف أخفّ من الذكر فناسب الترك، أما آيات الزمر ففي إثبات العبادة والأمر بها فناسبها الذكر. ثم إن الزمر أكدت الإخلاص في الدين وكررته، وضمائر المتكلم في سياقها ثلاثة عشر في ثلاث آيات، في حين ليس في سورة الكافرون كلها أكثر من سبعة، فناسب إظهار الياء هناك دون هنا.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص177–178.","url":""}]},{"id":"s110-1","number":1,"surah":110,"verses":[1],"references":[{"surah":110,"verses":[1]}],"verseLabel":"النصر: 1","question":"ماذا تفيد ﴿إِذَا﴾ في افتتاح سورة النصر؟","answer":"تفيد استقبال أمر متحقق الوقوع، فتجعل النصر الموعود بمنزلة الحدث الآتي يقينًا؛ وبذلك يجيء الافتتاح بشارة وتثبيتًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص595، تحت عنوان «دلالة ﴿إذا﴾ والغرض منها»","url":""}]},{"id":"s110-9","number":9,"surah":110,"verses":[1],"references":[{"surah":110,"verses":[1]}],"verseLabel":"النصر: 1","question":"لماذا أضيف النصر إلى الله في ﴿نَصْرُ اللَّهِ﴾؟","answer":"لينسب تحقق النصر إلى عون الله وتيسيره، فلا يغتر المؤمنون بقوتهم وأسبابهم؛ وهو أيضًا تشريف لهذا النصر بأنه نصر مخصوص من عنده.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص599، تحت عنوان «نكتة إضافة المصدر لفاعله في ﴿نصر الله﴾»","url":""}]},{"id":"s110-2","number":2,"surah":110,"verses":[1],"references":[{"surah":110,"verses":[1]}],"verseLabel":"النصر: 1","question":"ما الفرق بين النصر والفتح؟","answer":"النصر إعانة وإظهار على العدو، والفتح فتح البلد والفصل بين الخصمين. وبينهما تلازم في هذا المقام؛ فالغلبة على الأعداء تفضي إلى فتح بلادهم والتمكن منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص619، تحت عنوان «النصر والفتح»","url":""}]},{"id":"s110-3","number":3,"surah":110,"verses":[2],"references":[{"surah":110,"verses":[2]}],"verseLabel":"النصر: 2","question":"ما الصورة في قوله ﴿يَدْخُلُونَ فِي دِينِ اللَّهِ﴾؟","answer":"صُوّر الدين كالمكان المحيط الذي يدخله الناس ويستقرون فيه؛ فتجعل الاستعارة الانتقال إلى الإسلام دخولًا كاملًا في حماه.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص606، تحت عنوان «دلالة الاستعارة التصريحية التبعية في الجار»","url":""}]},{"id":"s110-10","number":10,"surah":110,"verses":[2],"references":[{"surah":110,"verses":[2]}],"verseLabel":"النصر: 2","question":"ماذا ترسم كلمة ﴿أَفْوَاجًا﴾ من انتشار الإسلام؟","answer":"ترسم جماعات كثيرة متتابعة تدخل بعد أن كان الناس يدخلون أفرادًا؛ فتجسد اتساع الفتح وسرعة إقبال القبائل.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص607–608، تحت عنوان «سر التعبير بصيغة الجمع ﴿أفواجًا﴾»","url":""}]},{"id":"s110-4","number":4,"surah":110,"verses":[2],"references":[{"surah":110,"verses":[2]}],"verseLabel":"النصر: 2","question":"ما دلالة المضارع ﴿يَدْخُلُونَ﴾ بعد مجيء الفتح؟","answer":"المضارع يصور دخول الناس متجددًا مستمرًا، ويستحضر هيئة الدخول بعد النصر والفتح كأنها مشاهدة؛ فلا يقف المشهد عند دخول وقع وانقضى.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص605، تحت عنوان «نكتة التعبير بفعل (الدخول) مضارعًا»","url":""}]},{"id":"s110-5","number":5,"surah":110,"verses":[3],"references":[{"surah":110,"verses":[3]}],"verseLabel":"النصر: 3","question":"لماذا كان جواب النصر التسبيح والاستغفار؟","answer":"يربط الشرط تمام النصر والفتح ودخول الناس بالأمر بالتسبيح والتحميد والاستغفار، شكرًا على إتمام النعمة وإتمامًا للعبادة. وتذكر الموسوعة أن تخصيص هذا المقام بالأمر يشعر بقرب الارتحال، مع دوام تسبيحه واستغفاره قبل ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص613–614، تحت عنوان «دلالة تعليق (التسبيح والتحميد والاستغفار) على الشرط»","url":""}]},{"id":"s110-6","number":6,"surah":110,"verses":[3],"references":[{"surah":110,"verses":[3]}],"verseLabel":"النصر: 3","question":"لماذا قيل ﴿فَسَبِّحْ بِحَمْدِ رَبِّكَ﴾ فاقترن التسبيح بالحمد؟","answer":"ليجمع الذكر تنزيه الله عن كل نقص مع الثناء عليه وشكره على تمام النعمة؛ فلا يكون التسبيح مجرد نفي، بل يصاحبه اعتراف بالفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص609–610، تحت عنوان «نكتة التعبير بـ(الباء)، والغرض منها»","url":""}]},{"id":"s110-11","number":11,"surah":110,"verses":[3],"references":[{"surah":110,"verses":[3]}],"verseLabel":"النصر: 3","question":"لماذا قيل ﴿بِحَمْدِ رَبِّكَ﴾ لا «بحمد الله»؟","answer":"لأن الربوبية تستحضر ما أحاط بالنبي ﷺ من تربية ورعاية وإحسان حتى تم النصر؛ فيناسب المقام أن يحمد ربه الذي تولى أمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص611، تحت عنوان «دلالة ذكر لفظ الاسم الأحسن (الرب) دون العلم الجليل»","url":""}]},{"id":"s110-7","number":7,"surah":110,"verses":[3],"references":[{"surah":110,"verses":[3]}],"verseLabel":"النصر: 3","question":"لماذا استؤنفت جملة ﴿إِنَّهُ كَانَ تَوَّابًا﴾ بعد الأمر بالاستغفار؟","answer":"لأنها تعلل الأمر وتبشر بنتيجته: استغفره لأنه كثير القبول لتوبة عباده؛ فجاء الفصل كجواب عن سؤال مقدر: لماذا نستغفر؟","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص615، تحت عنوان «نكتة الفصل في جملة: ﴿إنه كان توابًا﴾»","url":""}]},{"id":"s110-12","number":12,"surah":110,"verses":[3],"references":[{"surah":110,"verses":[3]}],"verseLabel":"النصر: 3","question":"ماذا يكشف وصف الله بأنه ﴿تَوَّابًا﴾؟","answer":"يكشف كثرة قبوله توبة عباده مرة بعد مرة، بل وتوفيقهم إليها؛ فصيغة المبالغة تفتح باب الرجاء ولا تحصر القبول في توبة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص616–617، تحت عنوان «نكتة التعبير بصيغة المبالغة ﴿توابًا﴾»","url":""}]},{"id":"s110-8","number":8,"surah":110,"verses":[1],"references":[{"surah":110,"verses":[1]}],"verseLabel":"النصر: السورة","question":"كيف تجمع سورة النصر بين بشارة الفتح وإشارة الوداع؟","answer":"تبشر بتمام النصر ودخول الناس أفواجًا، وهذا التمام نفسه يدل على اكتمال مهمة البلاغ وقرب الرحيل؛ لذلك سميت أيضًا سورة التوديع، وصار الفتح علامة إنجاز الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص591، تحت عنوان «المحور العام للسورة»","url":""}]},{"id":"s110-13","number":13,"surah":110,"verses":[1],"references":[{"surah":110,"verses":[1]}],"verseLabel":"النصر: السورة","question":"لماذا عُلقت أوامر التسبيح والحمد والاستغفار على تحقق النصر؟","answer":"لتعلم المؤمن أن تمام النجاح وقت شكر وتواضع وافتقار، لا وقت زهو؛ وفي توجيه النبي ﷺ إلى هذه الأعمال بعد اكتمال المهمة إشارة لطيفة إلى الاستعداد للقاء الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص613–614، تحت عنوان «دلالة تعليق (التسبيح والتحميد والاستغفار) على الشرط»","url":""}]},{"id":"s111-1","number":1,"surah":111,"verses":[1],"references":[{"surah":111,"verses":[1]}],"verseLabel":"المسد: 1","question":"ما سر افتتاح سورة المسد مباشرة بالدعاء على أبي لهب بالخسران؟","answer":"يفاجئه الافتتاح بحكم الهلاك من أول كلمة، فيلائم مقام الوعيد والتشهير بعداوته للدعوة، ويشد السامع إلى المصير الذي تفصله بقية السورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص629، تحت عنوان «براعة الاستهلال في الافتتاح»","url":""}]},{"id":"s111-9","number":9,"surah":111,"verses":[1],"references":[{"surah":111,"verses":[1]}],"verseLabel":"المسد: 1","question":"لماذا نُسب التباب إلى يدي أبي لهب في قوله ﴿تَبَّتْ يَدَا أَبِي لَهَبٍ﴾؟","answer":"لأن اليدين آلة أكثر الأعمال والكسب، فذكرهما يصور خسران ما باشره وسعى فيه، وهو كناية عن خسرانه كله أو مجاز بإطلاق الجزء وإرادة صاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص631–632، تحت عنوان «دلالة الكناية أو المجاز المرسل في (اليدين)»","url":""}]},{"id":"s111-2","number":2,"surah":111,"verses":[1],"references":[{"surah":111,"verses":[1]}],"verseLabel":"المسد: 1","question":"ما الفرق بين ﴿تَبَّتْ﴾ الأولى و﴿وَتَبَّ﴾ الثانية؟","answer":"تحتمل الأولى الدعاء عليه والثانية الإخبار بتحقق هلاكه، وتحتمل الثانية توكيد الأولى، وقيل: الأولى لخسران عمله ويديه والثانية لهلاك نفسه؛ فتتضافر الوجوه على إحاطة التباب به وبسعيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص636–637، تحت عنوان «دلالة الجمع بين فعلي (التباب)»","url":""}]},{"id":"s111-3","number":3,"surah":111,"verses":[1,3],"references":[{"surah":111,"verses":[1,3]}],"verseLabel":"المسد: 1، 3","question":"لماذا ذكر القرآن أبا لهب بكنيته ولم يذكر اسمه؟","answer":"لأن كنيته كانت الأشهر والأعرف به في قومه، وفي العدول إليها تجنب لذكر اسمه «عبد العزى» المتضمن تعظيم صنم.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص633، تحت عنوان «نكتة العدول عن العلم إلى اللقب»","url":""}]},{"id":"s111-10","number":10,"surah":111,"verses":[1,3],"references":[{"surah":111,"verses":[1,3]}],"verseLabel":"المسد: 1، 3","question":"ما المفارقة في انتقال أبي لهب من إشراق اللقب إلى قوله ﴿سَيَصْلَى﴾؟","answer":"كانت كنيته توحي عندهم بإشراق الوجه وحسنه، ثم انقلب ذلك الإشراق في الوعيد إلى احتراق بالنار؛ فصار اللقب الذي افتخر به مناسبًا لعقوبته ومصدر تهكم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص642، تحت عنوان «نكتة الطباق بين ﴿أبي لهب﴾ و﴿سيصلى﴾»","url":""}]},{"id":"s111-11","number":11,"surah":111,"verses":[1,3],"references":[{"surah":111,"verses":[1,3]}],"verseLabel":"المسد: 1، 3","question":"ماذا يضيف وصف النار بأنها ﴿ذَاتَ لَهَبٍ﴾؟","answer":"يصور اللهب صفة ملازمة للنار لا تنفك عنها، ويعظم شدة اشتعالها واضطرامها.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص644، تحت عنوان «نكات الإضافة في ﴿ذات لهب﴾»","url":""}]},{"id":"s111-4","number":4,"surah":111,"verses":[2],"references":[{"surah":111,"verses":[2]}],"verseLabel":"المسد: 2","question":"لماذا جُمع بين ﴿مَالُهُ﴾ و﴿مَا كَسَبَ﴾؟","answer":"ليعم النفي ما ملكه من مال وما حصله من ربح وعمل ومنعة، ويحتمل أن يشمل كسبه أولاده أيضًا؛ فلا يبقى سبب كان يتقوى به إلا سقط نفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص640، تحت عنوان «سر التغاير في التعبير عن المال والكسب»","url":""}]},{"id":"s111-5","number":5,"surah":111,"verses":[3],"references":[{"surah":111,"verses":[3]}],"verseLabel":"المسد: 3","question":"كيف صار قوله عن أبي لهب ﴿سَيَصْلَى نَارًا﴾ دليلًا على صدق القرآن؟","answer":"نزل الوعيد وأبو لهب حي، فأخبر ضمنًا أنه لن يؤمن وسيختم على الكفر؛ ثم وقع الأمر كما أخبر، مع أنه كان يستطيع ادعاء الإيمان مكابرةً لو أراد الطعن في الخبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص644، تحت عنوان «دلالة (الكناية) في الآية»","url":""}]},{"id":"s111-6","number":6,"surah":111,"verses":[4],"references":[{"surah":111,"verses":[4]}],"verseLabel":"المسد: 4","question":"لماذا ذُكرت امرأته معه؟","answer":"ذكرها معه يبين مشاركتها له في العذاب لمشاركتها في إيذاء النبي صلى الله عليه وسلم. فالعطف يجمعهما في الحكم كما اجتمعا على العداوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص645، تحت عنوان «دلالة (الواو)، والغرض منها»","url":""}]},{"id":"s111-7","number":7,"surah":111,"verses":[4],"references":[{"surah":111,"verses":[4]}],"verseLabel":"المسد: 4","question":"ما الذي يكشفه وصف امرأة أبي لهب بأنها ﴿حَمَّالَةَ﴾ لا مجرد حاملة؟","answer":"يكشف كثرة مباشرتها لهذا الأذى وملازمتها له حتى صار لها شأنًا وعادة، سواء أريد حمل الحطب حقيقة أو حمل أسباب الفتنة والنميمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص646، تحت عنوان «سر التعبير بـ﴿حمالة﴾ مادة وصيغة»","url":""}]},{"id":"s111-12","number":12,"surah":111,"verses":[4],"references":[{"surah":111,"verses":[4]}],"verseLabel":"المسد: 4","question":"كيف تصوّر عبارة ﴿حَمَّالَةَ الْحَطَبِ﴾ دور امرأة أبي لهب في الأذى؟","answer":"تصورها كمن يحمل الوقود ليزيد النار اشتعالًا؛ فكما كانت تنقل الشر وتسعى بالنميمة والفتنة كانت تغذي نار العداوة، مع احتمال حملها الحطب حقيقة في طريق النبي.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص647–648، تحت عنوان «دلالة الاستعارة التمثيلية في لفظ ﴿حمالة الحطب﴾»","url":""}]},{"id":"s111-8","number":8,"surah":111,"verses":[5],"references":[{"surah":111,"verses":[5]}],"verseLabel":"المسد: 5","question":"ما الذي يصوره قوله ﴿فِي جِيدِهَا حَبْلٌ مِنْ مَسَدٍ﴾؟","answer":"يصوّر غاية الذل والعذاب في عنق كانت موضع الزينة، ويحتمل الحبل المحكم حقيقة أو سلسلة من سلاسل النار صُورت بالحبل لقوة الفتل والإحكام.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص653، تحت عنوان «دلالة الاستعارة التصريحية في ﴿حبل﴾»","url":""}]},{"id":"s111-13","number":13,"surah":111,"verses":[5],"references":[{"surah":111,"verses":[5]}],"verseLabel":"المسد: 5","question":"كيف جاء عذاب امرأة أبي لهب من جنس عملها؟","answer":"لما حملت أسباب الأذى والفتنة في الدنيا مُثلت في الآخرة حاملةً للحطب وفي جيدها حبل؛ فتعكس صورة الجزاء عملها وتجمع الإهانة بالعقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص655، تحت عنوان «دلالة الاستعارة التمثيلية ﴿في جيدها حبل﴾»","url":""}]},{"id":"s111-14","number":14,"surah":111,"verses":[1,2],"references":[{"surah":111,"verses":[1,2]}],"verseLabel":"المسد: 1، 2","question":"ما سر اقتران ذكر الكسب بذكر اليدين في قوله تعالى: ﴿تَبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ * مَا أَغْنَىٰ عَنْهُ مَالُهُ وَمَا كَسَبَ﴾؟","answer":"الأيدي آلة الكسب، ولذلك كثيرًا ما يقترن الكسب بالأيدي في القرآن، كقوله: ﴿بِمَا كَسَبَتْ أَيْدِي النَّاسِ﴾ و﴿فَبِمَا كَسَبَتْ أَيْدِيكُمْ﴾؛ فلما ذكر يدَي أبي لهب ذكر ما كسب.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية، ج2، ص96.","url":""}]},{"id":"s112-1","number":1,"surah":112,"verses":[1],"references":[{"surah":112,"verses":[1]}],"verseLabel":"الإخلاص: 1","question":"لماذا افتتحت سورة الإخلاص بالأمر ﴿قُلْ﴾؟","answer":"للتنويه بعظمة جواب التوحيد، وبيان أن النبي ﷺ مأمور بتبليغه كما أوحي إليه، فيتلقى السامع العقيدة بوصفها وحيًا محكمًا لا رأيًا بشريًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص667–668، تحت عنوان «نكتة الافتتاح بالأمر ﴿قل﴾»","url":""}]},{"id":"s112-2","number":2,"surah":112,"verses":[1],"references":[{"surah":112,"verses":[1]}],"verseLabel":"الإخلاص: 1","question":"ماذا يحقق الضمير ﴿هُوَ﴾ في قوله ﴿قُلْ هُوَ اللَّهُ أَحَدٌ﴾؟","answer":"يحتمل أن يكون ضمير الشأن، فيثير الترقب لما سيأتي من خبر عظيم، وأن يعود إلى الرب المسؤول عنه؛ وفي الوجهين يجمع الانتباه قبل تقرير حقيقة التوحيد الحاسمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص669، تحت عنوان «نكتة التعبير بالضمير ﴿هو﴾»","url":""}]},{"id":"s112-3","number":3,"surah":112,"verses":[1],"references":[{"surah":112,"verses":[1]}],"verseLabel":"الإخلاص: 1","question":"لماذا قيل ﴿أَحَدٌ﴾ لا «واحد»؟","answer":"لأن ﴿أحد﴾ في هذا المقام تنفي الشريك والتركيب والمماثلة، وتقرر انفرادًا لا يدخل في سلسلة العدد ولا يجانس وحدانية المخلوقات.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص670–671، تحت عنوان «نكتة اختيار ﴿أحد﴾»","url":""}]},{"id":"s112-4","number":4,"surah":112,"verses":[2],"references":[{"surah":112,"verses":[2]}],"verseLabel":"الإخلاص: 2","question":"ما الذي يجمعه وصف الله بـ﴿الصَّمَدُ﴾؟","answer":"يجمع كمال السيادة والغنى والثبات، وأن الخلق يقصدونه في حوائجهم كلها بينما لا يفتقر هو إلى أحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص676، تحت عنوان «دلالة صيغة ﴿الصمد﴾»","url":""}]},{"id":"s112-5","number":5,"surah":112,"verses":[2],"references":[{"surah":112,"verses":[2]}],"verseLabel":"الإخلاص: 2","question":"ماذا يفيد تعريف الطرفين في ﴿اللَّهُ الصَّمَدُ﴾؟","answer":"يقصر الصمدية الكاملة على الله وحده؛ فهو المقصود في الحوائج والغني عن الخلق بلا شريك في هذا الكمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص676، تحت عنوان «دلالة تعريف الطرفين»","url":""}]},{"id":"s112-11","number":11,"surah":112,"verses":[2],"references":[{"surah":112,"verses":[2]}],"verseLabel":"الإخلاص: 2","question":"كيف رسخت السورة حقائق الأحدية والصمدية فلم تعرضها كأحوال عابرة؟","answer":"لتقرير ثبوت الأحدية والصمدية وسائر ما تخبر به السورة ودوامه، فتأتي الصفات حقائق راسخة لا أحوالًا عارضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص673، تحت عنوان «فائدة تعدد الإخبار بالاسمية»","url":""}]},{"id":"s112-6","number":6,"surah":112,"verses":[3],"references":[{"surah":112,"verses":[3]}],"verseLabel":"الإخلاص: 3","question":"ما سرّ تقديم ﴿لَمْ يَلِدْ﴾ على ﴿وَلَمْ يُولَدْ﴾؟","answer":"قدم نفي أن يلد لأن نسبة الولد إليه كانت مقالة ادعاها المخاطبون، فناسب البدء بإبطالها. ثم نفى أن يكون مولودًا، تتميمًا للتنزيه عن جهتي الولادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص680–681، تحت عنوان «نكتة الترتيب»","url":""}]},{"id":"s112-7","number":7,"surah":112,"verses":[3],"references":[{"surah":112,"verses":[3]}],"verseLabel":"الإخلاص: 3","question":"ماذا ينفي قوله ﴿لَمْ يَلِدْ﴾؟","answer":"ينفي أن يكون لله ولد، وما تستلزمه الولادة من المجانسة والانقسام والحاجة إلى امتداد أو نظير؛ فكل ذلك يناقض أحديته وصمديته.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص679، تحت عنوان «دلالة الكناية في ﴿لم يلد﴾»","url":""}]},{"id":"s112-12","number":12,"surah":112,"verses":[3],"references":[{"surah":112,"verses":[3]}],"verseLabel":"الإخلاص: 3","question":"ماذا ينفي قوله ﴿وَلَمْ يُولَدْ﴾؟","answer":"ينفي أن يكون ناشئًا عن غيره أو مسبوقًا بعدم، لأن المولود حادث محتاج إلى والديه، والله غني أزلي لا ابتداء لوجوده.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص681، تحت عنوان «دلالة الفعل ﴿يولد﴾»","url":""}]},{"id":"s112-8","number":8,"surah":112,"verses":[4],"references":[{"surah":112,"verses":[4]}],"verseLabel":"الإخلاص: 4","question":"لماذا قُدم ﴿لَهُ﴾ في ﴿وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ﴾؟","answer":"للعناية بأن النفي متعلق بالله خاصة، وتوجيه الذهن من أول التركيب إلى اختصاصه بانعدام النظير والمكافئ.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص684، تحت عنوان «نكتة تقديم ﴿له﴾»","url":""}]},{"id":"s112-13","number":13,"surah":112,"verses":[4],"references":[{"surah":112,"verses":[4]}],"verseLabel":"الإخلاص: 4","question":"لماذا قُدم ﴿كُفُوًا﴾ على ﴿أَحَدٌ﴾؟","answer":"لتسليط النفي على وصف المكافأة نفسه قبل ذكر أي أحد، فيشتد تقرير استحالة النظير، مع محافظة النظم على فاصلة السورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص684، تحت عنوان «نكتة تقديم ﴿كفوًا﴾»","url":""}]},{"id":"s112-9","number":9,"surah":112,"verses":[1,4],"references":[{"surah":112,"verses":[1,4]}],"verseLabel":"الإخلاص: 1، 4","question":"كيف تعانق لفظ ﴿أَحَدٌ﴾ في أول السورة وآخرها؟","answer":"«أحد» في المطلع وصف يثبت انفراده الذي لا يجانس الموجودات، وفي الختام نكرة في سياق النفي تستغرق كل من يتوهم مكافئًا له. فيجتمع إثبات الأحدية مع نفي كل نظير.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص686–687، تحت عنوان «دلالة الجناس التام بين الصدر والعجز»","url":""}]},{"id":"s112-10","number":10,"surah":112,"verses":[1],"references":[{"surah":112,"verses":[1]}],"verseLabel":"الإخلاص: السورة","question":"كيف جاء النفي تفصيلًا بعد إثبات الأحدية والصمدية؟","answer":"أثبت المطلع كمال التفرد والغنى إجمالًا، ثم فصل لازمهما بنفي الولد والوالد والمكافئ؛ فانتقلت السورة من أصل جامع إلى إبطال صور النقص واحدةً واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص673–674، تحت عنوان «نكتة التفصيل بعد الإجمال»","url":""}]},{"id":"s112-14","number":14,"surah":112,"verses":[1],"references":[{"surah":112,"verses":[1]}],"verseLabel":"الإخلاص: السورة","question":"كيف يقابل ختام السورة وصفي ﴿أَحَدٌ﴾ و﴿الصَّمَدُ﴾؟","answer":"يناسب نفي الولادة الصمدية التي تقتضي الغنى وعدم الحاجة، ويناسب نفي الكفء الأحدية التي تقتضي انفراد الله بلا شبيه؛ فيشرح الختام ما أثبته المطلع.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص686، تحت عنوان «بلاغة اللف والنشر المرتب»","url":""}]},{"id":"s112-15","number":15,"surah":112,"verses":[2],"references":[{"surah":112,"verses":[2]}],"verseLabel":"الإخلاص: 2","question":"ما سر التعبير بـ«الصمد» دون «المقصود» أو «الملتجَأ إليه»؟","answer":"«الصمد» له أكثر من معنى من معاني الكمال: المصمود إليه في الحوائج، والسيد الذي انتهى سؤدده، والذي لا جوف له، والدائم الباقي بعد فناء خلقه، وهو الصمد بكل هذه المعاني. و«المقصود» معنى واحد من معانيه، ولم يقيّد الصمدية بشيء فهو المقصود على الإطلاق.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص63–65.","url":""}]},{"id":"s112-16","number":16,"surah":112,"verses":[1],"references":[{"surah":112,"verses":[1]}],"verseLabel":"الإخلاص: 1","question":"ما سر البدء بـ«قُلْ»، وما دلالة الضمير «هو» في ﴿قُلْ هُوَ اللَّهُ أَحَدٌ﴾؟","answer":"أُمر الرسول ﷺ بإعلان هذه العقيدة وتبليغها، لا على طريقة الإخبار المجرد أو الاعتقاد الشخصي، لأهمية ما تضمنته من أصول اعتقادية. والمشهور أن «هو» ضمير الشأن، وهو يُؤتى به في مواطن التفخيم، فيبقى الذهن مترقبًا لما يفسّره فيتمكن عند وروده فضل تمكن. وهذا التوجيه منقول عن «روح المعاني».","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص59–60.","url":""}]},{"id":"s112-17","number":17,"surah":112,"verses":[1],"references":[{"surah":112,"verses":[1]}],"verseLabel":"الإخلاص: 1","question":"ما سر تفسير الضمير باسم «الله» دون غيره من الأسماء الحسنى؟","answer":"أراد أن يفصح عن ذاته العلية باسمه الذي لا يشركه فيه أحد، فلم يقل «هو الرحمن أحد» أو «الحي» أو «العالم»، لأن ذلك لا ينصّ تصريحًا على أن المقصود به الله، فجاء بما يزيل كل وهم وخاطرة شرك.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص63.","url":""}]},{"id":"s112-18","number":18,"surah":112,"verses":[1,2],"references":[{"surah":112,"verses":[1,2]}],"verseLabel":"الإخلاص: 1–2","question":"ما سر تنكير «أحد» وتعريف «الصمد»؟","answer":"الأحدية كانت مجهولة مستنكرة عند أكثر الخلق فجاءت نكرة، والصمدية معلومة عندهم لأنهم يلجؤون إلى الله في الشدائد فجاءت معرفة، وهذا التوجيه منقول عن «التفسير الكبير». والتعريف في «الصمد» يفيد الحصر، فلا مقصود على الحقيقة سواه، ولو قال «الله صمد» لم يقصر القصد عليه.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص65–66.","url":""}]},{"id":"s112-19","number":19,"surah":112,"verses":[1,2],"references":[{"surah":112,"verses":[1,2]}],"verseLabel":"الإخلاص: 1–2","question":"ما سر البدء بالأحدية ثم الصمدية، وعدم الجمع بينهما في آية واحدة؟","answer":"بدأ بالأحدية لأن التوحيد رأس المسائل الاعتقادية، ومن آمن بالله وحده آمن بأنه الملجأ، والمقصود من الجميع لا يكون إلا واحدًا. ولم يقل «هو الله أحد الصمد» لأهمية كل منهما في الاعتقاد، فجعل كلًّا منهما مسألة مستقلة، وليفرّق بين المجهول والمعلوم.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص66–67.","url":""}]},{"id":"s112-20","number":20,"surah":112,"verses":[3],"references":[{"surah":112,"verses":[3]}],"verseLabel":"الإخلاص: 3","question":"ما سر قوله: ﴿لَمْ يَلِدْ وَلَمْ يُولَدْ﴾ دون «الذي لم يلد»، وتقديم نفي الولد على نفي الوالد؟","answer":"أراد إخبارهم بما جهلوه، ولو قال «الذي لم يلد» لكان المعنى أنهم يعلمونه، وهم كانوا يقولون إن الله وَلَد. وبدأ بنفي الولد لأنهم ادّعوا له ولدًا ولم يدّع أحد أن له والدًا، فبدأ بالأهم ثم أشار إلى الحجة، وهذا التوجيه منقول عن «التفسير الكبير».","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص67–69.","url":""}]},{"id":"s112-21","number":21,"surah":112,"verses":[4],"references":[{"surah":112,"verses":[4]}],"verseLabel":"الإخلاص: 4","question":"ما سر التعبير بـ«كُفُوًا» بالواو، وتكرير «أحد» في أول السورة وآخرها؟","answer":"«كفوًا» إبدال من «كفء»، وهي صورة لا نظير لها في الأسماء المعربة، إذ لا يكون فيها اسم آخره واو لازمة قبلها ضمة، فجاء بكلمة لا نظير لها في العربية لمن ليس له نظير. وجاء بـ«أحد» في الإثبات وهي الخاصة بالله، وفي النفي وهي الدالة على العموم، فنفى عنه النظير على وجه العموم.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص73.","url":""}]},{"id":"s113-1","number":1,"surah":113,"verses":[1],"references":[{"surah":113,"verses":[1]}],"verseLabel":"الفلق: 1","question":"لماذا افتتحت سورة الفلق بالأمر ﴿قُلْ﴾؟","answer":"ليعلم الله نبيه ﷺ والأمة من بعده صيغة الاستعاذة التي تقال كما أُنزلت، وليكون طلب الحماية إعلانًا مأمورًا به لا عبارة منشأة من عند الرسول. فالافتتاح يلفت إلى العناية بألفاظ السورة وبثها للناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص697–698، تحت عنوان «نكتة الاستفتاح بالفعل ﴿قل﴾»","url":""}]},{"id":"s113-11","number":11,"surah":113,"verses":[1],"references":[{"surah":113,"verses":[1]}],"verseLabel":"الفلق: 1","question":"ماذا يصور الفعل ﴿أَعُوذُ﴾ في مطلع السورة؟","answer":"يصور لجوء المستعيذ إلى الله واعتصامه بحماه طالبًا الوقاية من الشر. وجيء به مضارعًا ليستحضر طلب الحماية ويتجدد كلما تجدد موجب الاستعاذة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص699، تحت عنوان «دلالة الفعل ﴿أعوذ﴾»","url":""}]},{"id":"s113-2","number":2,"surah":113,"verses":[1],"references":[{"surah":113,"verses":[1]}],"verseLabel":"الفلق: 1","question":"لماذا ناسب طلب الحماية أن تكون الاستعاذة بـ﴿رَبِّ الْفَلَقِ﴾؟","answer":"لأن الفلق يصور الصبح وهو يشق الظلمة ويبددها؛ فمن يخرج النور من قلب الليل قادر على كشف الشرور التي تستتر فيه ودفعها. وفي الصورة بعث للرجاء بأن بعد شدة الظلام فرجًا وحماية.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص701–702، تحت عنوان «نكتة الاستعارة في ﴿الفلق﴾»","url":""}]},{"id":"s113-3","number":3,"surah":113,"verses":[2],"references":[{"surah":113,"verses":[2]}],"verseLabel":"الفلق: 2","question":"لماذا بدأ بالاستعاذة ﴿مِنْ شَرِّ مَا خَلَقَ﴾؟","answer":"تفيد ﴿ما﴾ العموم، فتشمل الاستعاذة كل ما قد يوجد فيه شر من المخلوقات، ولا تنحصر في نوع بعينه؛ فيلجأ المستعيذ إلى رب الخلق من الشر كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص703–704، تحت عنوان «دلالة ﴿ما﴾»","url":""}]},{"id":"s113-4","number":4,"surah":113,"verses":[2],"references":[{"surah":113,"verses":[2]}],"verseLabel":"الفلق: 2","question":"هل في قوله ﴿مِنْ شَرِّ مَا خَلَقَ﴾ نسبة الشر إلى الخلق كله؟","answer":"لا يصف التعبير كل المخلوقات بالشر؛ فالمستعاذ منه هو الشر الصادر منها، لا ذواتها بإطلاق. وإضافة الشر إلى ما خلق تحدد مصدر الضرر الذي يطلب المستعيذ الوقاية منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص703، تحت عنوان «دلالة الإضافة»","url":""}]},{"id":"s113-5","number":5,"surah":113,"verses":[3],"references":[{"surah":113,"verses":[3]}],"verseLabel":"الفلق: 3","question":"لماذا قيد شر الغاسق بـ﴿إِذَا وَقَبَ﴾؟","answer":"قيد الغاسق بوقت وقوبه لأن الخوف من الشر يشتد عند دخول الليل واستحكام ظلمته، حين تتستر فيه الهوام وأهل الفساد. فالتقييد يعين الحال التي تشتد فيها الحاجة إلى الحماية.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص708، تحت عنوان «دلالة تقييد ﴿غاسق﴾»","url":""}]},{"id":"s113-6","number":6,"surah":113,"verses":[3],"references":[{"surah":113,"verses":[3]}],"verseLabel":"الفلق: 3","question":"كيف تصور كلمة ﴿غَاسِقٍ﴾ شدة ظلام الليل؟","answer":"تصور الظلمة كأنها مادة سائلة تنصب في المكان وتغمره؛ فتجعل حلول الليل مشهدًا محسوسًا لظلام كثيف يملأ ما حول الإنسان، وهو أنسب بما يختفي فيه من أسباب الأذى.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص707، تحت عنوان «دلالة الاستعارة في ﴿غاسق﴾»","url":""}]},{"id":"s113-12","number":12,"surah":113,"verses":[3],"references":[{"surah":113,"verses":[3]}],"verseLabel":"الفلق: 3","question":"ماذا تضيف كلمة ﴿وَقَبَ﴾ إلى صورة الليل؟","answer":"تدل على دخول الظلام وانتشاره واستقراره حتى يحيط بالأشياء، فلا تتحدث الآية عن مجرد إقبال الليل بل عن بلوغه حال الاستحكام التي تشتد فيها المخاوف والحاجة إلى الحماية.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص708، تحت عنوان «دلالة الفعل ﴿وقب﴾»","url":""}]},{"id":"s113-7","number":7,"surah":113,"verses":[4],"references":[{"surah":113,"verses":[4]}],"verseLabel":"الفلق: 4","question":"ماذا تصور كلمة ﴿النَّفَّاثَاتِ﴾ عن فعل السحر؟","answer":"تصور تكرار النفث في العقد وملازمته، لا نفخة عارضة؛ فالصيغة ترسم إصرار فاعلي السحر على عملهم الخفي وتناسب الاستعاذة من شر يتعمدونه ويكررونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص710، تحت عنوان «دلالة كلمة ﴿النفاثات﴾»","url":""}]},{"id":"s113-8","number":8,"surah":113,"verses":[5],"references":[{"surah":113,"verses":[5]}],"verseLabel":"الفلق: 5","question":"لماذا خُص الحاسد بحال ﴿إِذَا حَسَدَ﴾؟","answer":"القيد يخص الاستعاذة بحال ظهور الحسد وعمل صاحبه بمقتضاه لإلحاق الضرر بالمحسود. فالتحذير متعلق بالشر حين يبرز أثره، وهو وجه تذكره الموسوعة في توجيه الظرف.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص715، تحت عنوان «دلالة التقييد بالظرف»","url":""}]},{"id":"s113-9","number":9,"surah":113,"verses":[2,3,4,5],"references":[{"surah":113,"verses":[2,3,4,5]}],"verseLabel":"الفلق: 2–5","question":"لماذا خُص الغاسق والسحر والحسد بعد عموم ﴿مِنْ شَرِّ مَا خَلَقَ﴾؟","answer":"للتنبيه إلى خطورة هذه الشرور مع دخولها في العموم؛ فهي أذى خفي تشتد الحاجة إلى الاحتماء منه وقد لا يرى الإنسان سببه أو وقت مجيئه. فذكر الخاص بعد العام يبرز شأنه ولا يخرجه من العموم.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص705، تحت عنوان «نكتة التوافق في العطف»","url":""}]},{"id":"s113-13","number":13,"surah":113,"verses":[2,3,4,5],"references":[{"surah":113,"verses":[2,3,4,5]}],"verseLabel":"الفلق: 2–5","question":"لماذا تكررت عبارة ﴿مِنْ شَرِّ﴾ مع كل نوع في السورة؟","answer":"لتجدد الانتباه إلى كل خطر وجعله مقصودًا بالاستعاذة على حدة؛ فالغاسق والنفاثات والحاسد ليست أمثلة تمر في سرد واحد، بل شرور مستقلة يطلب العبد الحماية من كل منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص706، تحت عنوان «نكتة الإطناب بتكرار المتعلق»","url":""}]},{"id":"s113-10","number":10,"surah":113,"verses":[1],"references":[{"surah":113,"verses":[1]},{"surah":114,"verses":[1]}],"verseLabel":"الفلق: الفلق–الناس","question":"ما الذي يجمع سورتي الفلق والناس في بنائهما ومقصدهما؟","answer":"تفتتح كلتاهما بالأمر ﴿قل أعوذ﴾ لتعلما العبد الالتجاء إلى الله وطلب حمايته. فهما خاتمتان متآزرتان تجمعان أصل الاعتصام بالله أمام وجوه الشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص727، تحت عنوان «نكتة المشابهة بين المعوذتين»","url":""}]},{"id":"s113-14","number":14,"surah":113,"verses":[1],"references":[{"surah":113,"verses":[1]},{"surah":114,"verses":[1]}],"verseLabel":"الفلق: الفلق–الناس","question":"كيف اختلفت الشرور في المعوذتين، ولماذا كثرت صفات المستعاذ به في سورة الناس؟","answer":"تعرض الفلق شرورًا متعددة يغلب تعلقها بالأذى الخارجي والبدني، أما الناس فتخص شر الوسوسة الذي ينفذ إلى الباطن ويمس الدين. ولشدة هذا الخطر الخفي ذكرت سورة الناس الرب والملك والإله، بينما اكتفت الفلق برب الفلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص746، تحت عنوان «سر التغاير بين المعوذتين»","url":""}]},{"id":"s113-15","number":15,"surah":113,"verses":[1],"references":[{"surah":113,"verses":[1]}],"verseLabel":"الفلق: 1","question":"ما سر اختيار «الفلق» دون «الصبح»، وما دلالة تخصيصه بالذكر في الاستعاذة؟","answer":"الفلق مشعر بتبدد ظلمة الليل ومجيء الفرج، والقادر على إزالة الظلمة عن العالم قادر أن يدفع عن العائذ ما يخافه، وفي «التفسير الكبير» وتفسير البيضاوي نحو هذا. ولفظ «الفلق» مشعر بالتغير والحركة لأنه انشقاق الضوء عن الظلمة، أما «الصبح» فيفيد تعيين الوقت، والفلق أعمّ معنى إذ يشمل كل ما يفلقه الله. وناسب ذكرُه ذكرَ «الغاسق» بعده.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص30–32.","url":""}]},{"id":"s113-16","number":16,"surah":113,"verses":[1],"references":[{"surah":113,"verses":[1]}],"verseLabel":"الفلق: 1","question":"ما سر قوله: «أعوذ» من غير توكيد، مع قوله في مواطن أخرى: ﴿وَإِنِّي عُذْتُ بِرَبِّي وَرَبِّكُم﴾؟","answer":"الاستعاذة تكون على قدر ما يحذره المستعيذ؛ فإذا كان المحذور شديدًا متسلطًا يتهدده هو على الخصوص أكّدها، كاستعاذة موسى حين هدده فرعون بالقتل، وإلا قال «أعوذ». وما في المعوذتين ليس من هذا النوع من التهديد المخصوص، فلم يحتج إلى توكيد.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص26–28.","url":""}]},{"id":"s113-17","number":17,"surah":113,"verses":[2],"references":[{"surah":113,"verses":[2]}],"verseLabel":"الفلق: 2","question":"ما سر التعبير بـ«ما» في ﴿مِن شَرِّ مَا خَلَقَ﴾ دون «مَن» أو «الذي»؟","answer":"ليتناول كل شرّ من العاقل وغيره، وغلّب غير العاقل لأن الأصل ألا يصدر شرّ من عاقل، وفي «التفسير الكبير» نحو هذا. و«ما» أعمّ من «الذي» و«التي» و«الذين» و«اللاتي»، لأنها تكون للمفرد والمثنى والجمع المذكر والمؤنث، فكانت أولى من غيرها على كل وجه.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص33–34.","url":""}]},{"id":"s113-18","number":18,"surah":113,"verses":[2,5],"references":[{"surah":113,"verses":[2,5]}],"verseLabel":"الفلق: 2، 5","question":"ما سر ترتيب المستعاذ منه في السورة، وتنكير «غاسق» و«حاسد» وتعريف «النفاثات»؟","answer":"تدرّج من العام إلى الخاص ومن الكثرة إلى القلة: فبدأ بشر ما خلق، ثم الغاسق الذي يدخل كل يوم، ثم النفاثات وهن كثير وشرهن متعدد، ثم الحاسد وشره مخصوص بالحسد. وخصّ هؤلاء بعد التعميم لخفاء شرهم، وهذا منقول عن «الكشاف». ونكّر الغاسق والحاسد لأنه ليس كل غاسق يكون فيه الشر ولا كل حاسد يكون منه الضرر، وعرّف النفاثات لأن كل نفاثة شريرة.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص41–42.","url":""}]},{"id":"s113-19","number":19,"surah":113,"verses":[2,5],"references":[{"surah":113,"verses":[2,5]}],"verseLabel":"الفلق: 2، 5","question":"ما سر تكرير «مِن شَرّ» مع كل مستعاذ منه؟","answer":"للدلالة على أن كلًّا من المذكورين تنبغي الاستعاذة منه على وجه الاستقلال لعظم شره. ولو قال «من شر ما خلق وغاسق والنفاثات» لاحتمل الاستعاذة من شرها إذا اجتمعت لا إذا انفردت، أو الاستعاذة من ذواتها لا من شرورها، وذكر «من» مع كل واحد أدلّ على استقلال كل صنف وآكد.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص38–39.","url":""}]},{"id":"s113-20","number":20,"surah":113,"verses":[4],"references":[{"surah":113,"verses":[4]}],"verseLabel":"الفلق: 4","question":"ما سر التعبير بـ«النفاثات» صفةً بلا موصوف، وبجمع الإناث، وبصيغة المبالغة؟","answer":"لم يذكر الموصوف لإرادة العموم، وجاء بجمع الإناث لأنه يشمل النفوس والأرواح والجماعات والنساء، ولو قال «النفاثين» لم يشمل إلا الذكور. ولما جمع «العُقَد» جمع كثرة جاء بصيغة المبالغة «نفّاثات» لأنه لما كثرت العقد كثر النفث، نظير «عالم الغيب» و«علّام الغيوب».","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص37–38.","url":""}]},{"id":"s113-21","number":21,"surah":113,"verses":[5],"references":[{"surah":113,"verses":[5]}],"verseLabel":"الفلق: 5","question":"ما سر التعبير بـ«حاسد» دون «حسود»، وتقييده وتقييد الغاسق بـ«إذا» دون النفاثات؟","answer":"«حاسد» أعمّ لأنه يشمل المبالغ وغير المبالغ، والحسود إذا حسد كان حاسدًا في حينه. وقيّد الغاسق والحاسد بـ«إذا» لأن شرّ الغاسق يكون إذا دخل، والحاسد لا يؤثر إلا إذا أظهر حسده وعمل بمقتضاه، بخلاف شر النفاثات فهو مطلق غير مقيّد. وفي «البحر المحيط» و«روح المعاني» نحو هذا.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص37–38، 43.","url":""}]},{"id":"s113-22","number":22,"surah":113,"verses":[1],"references":[{"surah":113,"verses":[1]}],"verseLabel":"الفلق: 1","question":"ما سر الأمر بـ«قُلْ» في ﴿قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ﴾ دون أن يقال: «أعوذ»؟","answer":"الله يريد من الإنسان أن يُعلن صراحةً ضعفه وحاجته إلى ربه، وألا يكتفي بالشعور بالحاجة. وفي هذا الإعلان قتل للكبر والعجب والشعور بالاستغناء الذي هو سبب الطغيان، وهو من أسباب الطاعة ومما يليّن القلوب، والمطلوب مواطأة اللسان للقلب.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص25–26.","url":""}]},{"id":"s113-23","number":23,"surah":113,"verses":[1],"references":[{"surah":113,"verses":[1]}],"verseLabel":"الفلق: 1","question":"ما سر اختيار لفظ «الرب» في الاستعاذة؟","answer":"الرب هو المالك والمربي والقيّم، فالاستعاذة بربّ المخلوقات من شرورها أنسب لأنه وحده القادر على كفّها. وهو مناسب من جهتين: من جهة المستعاذ منه فهو مالكه المسيطر عليه، ومن جهة المستعيذ فهو مربيه القائم على حفظه، ولذلك كثر لفظ «الرب» مع الاستعاذة.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص32–33.","url":""}]},{"id":"s114-1","number":1,"surah":114,"verses":[1,2,3],"references":[{"surah":114,"verses":[1,2,3]}],"verseLabel":"الناس: 1–3","question":"ما أثر تكرار كلمة ﴿النَّاسِ﴾ في السورة كلها؟","answer":"يجعل الناس محور الخطاب من أوله إلى آخره: يقرر ربوبية الله وملكه وألوهيته لهم، ثم يكشف موضع الوسوسة ومصدريها، فيشعرهم بأن التحصين موجه إليهم جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص745–746، تحت عنوان «نكتة تكرار (الناس)»","url":""}]},{"id":"s114-2","number":2,"surah":114,"verses":[1,2,3],"references":[{"surah":114,"verses":[1,2,3]}],"verseLabel":"الناس: 1–3","question":"لماذا رُتبت الصفات ﴿رَبِّ النَّاسِ مَلِكِ النَّاسِ إِلَهِ النَّاسِ﴾؟","answer":"من وجوه الترتيب أن الإنسان يعرف ربه من خلقه وتربيته، ثم يدرك سعة ملكه وتدبيره، ثم كمال استحقاقه للعبادة. فهو تدرج في التعريف بالمستعاذ به، وجمع لما يحقق الحماية من الرعاية والقدرة والألوهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص732–733، تحت عنوان «نكت ترتيب الأوصاف»","url":""}]},{"id":"s114-3","number":3,"surah":114,"verses":[1],"references":[{"surah":114,"verses":[1]}],"verseLabel":"الناس: 1","question":"ماذا توحي إضافة الرب إلى الناس في ﴿رَبِّ النَّاسِ﴾؟","answer":"تستحضر افتقارهم إلى من يربيهم ويدفع عنهم الشر، وتمنحهم شرف الانتساب إلى ربهم والثقة بعنايته وحمايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص728، تحت عنوان «دلالة إضافة (رب الناس)»","url":""}]},{"id":"s114-11","number":11,"surah":114,"verses":[1],"references":[{"surah":114,"verses":[1]}],"verseLabel":"الناس: 1","question":"لماذا اختير ﴿النَّاسِ﴾ خاصةً في وصف الرب؟","answer":"لأنهم المخاطبون بالاستعاذة والمبتلون بوسوسة الصدور، ولأن الإنسان بلغ من كمال الخلق ما يجعله أحوج إلى صيانة عقله وإيمانه من هذا الشر الخفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص728، تحت عنوان «نكتة اختيار ﴿الناس﴾»","url":""}]},{"id":"s114-4","number":4,"surah":114,"verses":[4],"references":[{"surah":114,"verses":[4]}],"verseLabel":"الناس: 4","question":"ماذا توحي صيغة ﴿الْوَسْوَاسِ﴾؟","answer":"تصور الإلقاء الخفي المتكرر، ويحتمل اللفظ أن يكون مصدرًا جُعل اسمًا للموسوس أو صيغة مبالغة تدل على ملازمته هذا الفعل وكثرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص735، تحت عنوان «دلالة صيغة ﴿الوسواس﴾»","url":""}]},{"id":"s114-12","number":12,"surah":114,"verses":[4],"references":[{"surah":114,"verses":[4]}],"verseLabel":"الناس: 4","question":"لماذا وُصف الموسوس بأنه ﴿الْخَنَّاسِ﴾؟","answer":"لأنه يختفي ويتراجع كلما ذُكر الله، ثم يعاود عند الغفلة؛ فالوصف يكشف طريقة عمله وينبه إلى أن الذكر يضعف كيده.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص737–738، تحت عنوان «دلالة ﴿الخناس﴾»","url":""}]},{"id":"s114-5","number":5,"surah":114,"verses":[4],"references":[{"surah":114,"verses":[4]}],"verseLabel":"الناس: 4","question":"ماذا أفاد تعريف ﴿الْوَسْوَاسِ﴾؟","answer":"أفاد استغراق جنس الموسوس، فلا تنحصر الاستعاذة في شيطان معين بل تشمل كل من يلقي الشر خفية في الصدور.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص737، تحت عنوان «دلالة تعريف ﴿الوسواس﴾»","url":""}]},{"id":"s114-6","number":6,"surah":114,"verses":[5],"references":[{"surah":114,"verses":[5]}],"verseLabel":"الناس: 5","question":"لماذا قيل ﴿فِي صُدُورِ النَّاسِ﴾ بدل «في قلوبهم»؟","answer":"لأن الصدر محل القلب ومجال ما يختلج في باطن الإنسان، فيصور التعبير شمول الوسوسة للباطن وما يحيط بالقلب من خواطر خفية.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص742، تحت عنوان «سر ذكر الصدور»","url":""}]},{"id":"s114-7","number":7,"surah":114,"verses":[5],"references":[{"surah":114,"verses":[5]}],"verseLabel":"الناس: 5","question":"ما دلالة المضارع ﴿يُوَسْوِسُ﴾؟","answer":"المضارع يصور الوسوسة متجددة مستمرة، فتكون صلة الموصول بيانًا لسبب الاستعاذة الدائمة. ولتجدد هذا الشر يحتاج المستعيذ إلى تجديد الاستعاذة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص740، تحت عنوان «نكتة التعبير بالصلة»","url":""}]},{"id":"s114-8","number":8,"surah":114,"verses":[6],"references":[{"surah":114,"verses":[6]}],"verseLabel":"الناس: 6","question":"ماذا يكشف قوله ﴿مِنَ الْجِنَّةِ وَالنَّاسِ﴾ عن مصادر الوسوسة؟","answer":"يكشف أن الموسوس قد يكون من الجن بإلقائه الخفي، وقد يكون من الإنس بإغوائه وتزيينه الباطل؛ فالاستعاذة تشمل المصدرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص743–744، تحت عنوان «دلالة ﴿من﴾»","url":""}]},{"id":"s114-9","number":9,"surah":114,"verses":[1,2,3,4,5,6],"references":[{"surah":114,"verses":[1,2,3,4,5,6]}],"verseLabel":"الناس: 1–6","question":"لماذا بدأت السورة بالمستعاذ به ثلاث مرات وذكرت المستعاذ منه مرة؟","answer":"تفصيل صفات المستعاذ به مع إفراد شر الوسوسة يعظم شأن الحماية المطلوبة من شر يمس الدين وباطن الإنسان. فذكر الربوبية والملك والألوهية يقوي تعلق المستعيذ بمن يربيه ويملكه ويستحق عبادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص734، تحت عنوان «سر الإطناب في السورة»","url":""}]},{"id":"s114-10","number":10,"surah":114,"verses":[1],"references":[{"surah":1,"verses":[1]},{"surah":114,"verses":[1]}],"verseLabel":"الناس: الفاتحة–الناس","question":"لماذا يناسب تجديد الاستعاذة عند الفراغ من قراءة القرآن؟","answer":"لأن القارئ يجدد عهده بالعمل بما قرأ، ويلجأ إلى الله من وساوس تصرفه عنه ومن آفات العجب والتقصير بعد تمام هذه النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص726، تحت عنوان «مناسبة الاستعاذة لختم القرآن»","url":""}]},{"id":"s114-13","number":13,"surah":114,"verses":[1],"references":[{"surah":1,"verses":[1]},{"surah":114,"verses":[1]}],"verseLabel":"الناس: الفاتحة–الناس","question":"ما حكمة ختم القرآن بسورة الناس؟","answer":"لإظهار العناية بالناس الذين خوطبوا بهذا الكتاب من أوله إلى آخره، وختم الرحلة بتعليمهم الالتجاء إلى الله من الشر الخفي الذي يصدهم عن هدايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص746–747، تحت عنوان «نكتة الختم بهذه السورة»","url":""}]},{"id":"s114-14","number":14,"surah":114,"verses":[1,3],"references":[{"surah":114,"verses":[1,3]}],"verseLabel":"الناس: 1، 3","question":"ما سر ترك العطف بالواو بين الصفات، وتكرير لفظ «الناس» دون الضمير؟","answer":"لم يعطف لئلا يُظنّ أنها ذوات متعددة، فهو الرب والملك والإله، وفي «التفسير القيم» نحو هذا. وكرر «الناس» لأن اللفظ يطلق على القليل والكثير: فناس المربي أقلّ، وناس الملك أكثر، وناس الإله يشملون الجميع؛ فلو قال «رب الناس وملكهم وإلههم» لظُنّ أنه ملك أولئك وحدهم وإلههم فحسب.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص46–49.","url":""}]},{"id":"s114-15","number":15,"surah":114,"verses":[1,4],"references":[{"surah":114,"verses":[1,4]}],"verseLabel":"الناس: 1، 4","question":"ما سر الاستعاذة بثلاث صفات من شرّ واحد في الناس، مع الاستعاذة بصفة واحدة من شرور متعددة في الفلق؟","answer":"شرّ الوسواس أخطر على الفرد والمجتمع من تلك الشرور، لأنه يعود على من ألقيت إليه الوسوسة وعلى غيره فيقع تحت طائلة الحساب في الدنيا والآخرة. ومضرة الدين أعظم من مضرة الدنيا فجاءت الاستعاذة منها بصفات ثلاث، وفي «البحر المحيط» نحو هذا.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص45.","url":""}]},{"id":"s114-16","number":16,"surah":114,"verses":[1,6],"references":[{"surah":114,"verses":[1,6]}],"verseLabel":"الناس: 1، 6","question":"ما سر قوله: ﴿بِرَبِّ النَّاسِ﴾ دون «برب الجنة والناس» مع أن الوسواس من الفريقين؟","answer":"ذكر الوسوسة في صدور الناس لا في صدور الجنة، فالمعدوّ عليهم هم الناس، فاستعاذوا بربهم وملكهم وإلههم ليحميهم من هذا العدوان، كما يستغيث الموالي بسيدهم ووالي أمرهم. وفي «الكشاف» نحو هذا.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص54.","url":""}]},{"id":"s114-17","number":17,"surah":114,"verses":[6],"references":[{"surah":114,"verses":[6]}],"verseLabel":"الناس: 6","question":"ما سر التعبير بـ«الجِنَّة» في مقابل «الناس»، وتقديمها في ﴿مِنَ الْجِنَّةِ وَالنَّاسِ﴾؟","answer":"الجن يقابل الإنس وهما الأصلان للجنسين، أما «الجنة» فمجموعة من الجن أو أفراد منهم فقابلت «الناس» الذين هم مجموعة قليلة أو كثيرة من الإنس. وقدّم الجنة لأنهم المعتدون على الناس والأصل في الوسوسة، وقد تكون وسوسة الإنسي بسبب وسوسة الشيطان؛ أما تقديم شياطين الإنس في الأنعام فلأن السياق هناك في كفرة الإنس.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص55–57. المصادر","url":""}]},{"id":"s114-18","number":18,"surah":114,"verses":[4],"references":[{"surah":114,"verses":[4]}],"verseLabel":"الناس: 4","question":"ما سر قوله: ﴿مِن شَرِّ الْوَسْوَاسِ﴾ دون «من الوسواس» أو «من شر وسوسته»؟","answer":"الموسوِس قد يكون من الناس، ونحن لا نستعيذ من الناس على العموم لأنا مأمورون بمخالطتهم ودعوتهم، بل من شرورهم، فحسُن ذكر «الشر». واستعاذ من شر الذات الموسوِسة لا من شر وسوستها فحسب لتعمّ الاستعاذة شروره كلها، وفي «التفسير القيم» نحو هذا.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص51–52.","url":""}]},{"id":"s114-19","number":19,"surah":114,"verses":[4],"references":[{"surah":114,"verses":[4]}],"verseLabel":"الناس: 4","question":"ما دلالة وصف الوسواس بـ«الخنّاس»؟","answer":"«الخنّاس» صيغة مبالغة من الخنوس وهو التأخر والاستتار، مناسبة لمبالغة «الوسواس»، فهو مزاول للوسوسة والخنوس كلما سنحت فرصة. وفيه تعريف بصفة العدوّ: لا نستطيع القضاء عليه وإنما ندفع شره بذكر الله فيخنس ثم يعاود في لحظة الغفلة، ولم يقل «المنهزم» أو «المقتول».","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص52–53.","url":""}]},{"id":"s114-20","number":20,"surah":114,"verses":[5],"references":[{"surah":114,"verses":[5]}],"verseLabel":"الناس: 5","question":"ما سر التعبير بـ«في» في ﴿يُوَسْوِسُ فِي صُدُورِ النَّاسِ﴾ دون «إلى» أو اللام؟","answer":"ذكر موضع الوسوسة وهو الصدر، أما «إلى» واللام فتكونان للشخص الموسوَس إليه، كقوله: ﴿فَوَسْوَسَ إِلَيْهِ الشَّيْطَانُ﴾ و﴿فَوَسْوَسَ لَهُمَا الشَّيْطَانُ﴾. والشيطان يدخل الصدر فيلقي منه ما يريد إلقاءه إلى القلب، وفي «التفسير القيم» و«روح المعاني» نحو هذا.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص53–54.","url":""}]}]);
